// Content for Crossroads (node g16, ages 9–12, Chapter 3) — NEW v2 build to GDD 16 (mechanic-embodying),
// the decision-making node (Thread D · Relationships) and the **branching-dilemma flagship** of the whole
// app. "Stop, think, choose well." 84 researched, India-grounded scenarios across the six steps of the
// decision routine, each encoded as one of the shared v2 play actions (branch / reflect / strike-rewrite /
// role-play / sort / build / match) — no binary "tap the right card", led by the **branching dilemma card**
// (branch ×29 — decide a real crossroads, see the ripple, get a debrief; this is the reference branch engine
// later relationship/ethics nodes reuse). Teaches the reusable routine: stop & think (pause), see your
// options (not black-and-white), weigh the consequences ("then what?", short vs long term), decide by your
// values, navigate friendship crossroads, and own your choice. DECIDE, DON'T DICTATE; REAL AUTONOMY
// (dilemmas often have more than one defensible move; the game backs the child's reasoning); SAFE TO BE WRONG
// (a weaker choice plays out as a learnable consequence, never a buzzer — "you can change course"); VALUES
// NOT PREACHING; big/risky calls route to "ask a trusted adult" (safety dilemmas link Boundary Bot g15 &
// Safety Squad g08 — Childline 1098). Builds on g09 (Friend or Frenemy); prereq g15. Rendered by the shared
// engine (components/games/v2-engine.tsx). gameId "crossroads". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // — Stop and think (pause before deciding) —
  {"id":"cr-001","cat":"stop-think","type":"branch","hook":"A friend dares you to do something risky, right now, fast.","options":[{"text":"Pause: \"give me a sec to think\"","consequence":"The pressure cools; you can choose clearly.","outcome":"thoughtful","best":true},{"text":"Just react instantly","consequence":"Snap reactions under pressure often go wrong; pause first."}],"debrief":"A quick pause before deciding is the first decision-making power.","relearn":"Stop and think before you decide, especially under pressure.","persona":"Aarav","source":"stop and think"},
  {"id":"cr-002","cat":"stop-think","type":"strike-rewrite","hook":"\"Deciding fast always means deciding well.\"","myth":{"un":"The faster you decide, the better.","re":"A short pause to think leads to better choices.","why":"Snap decisions skip the thinking step."},"relearn":"Pausing to think makes for better decisions than rushing.","persona":"any","source":"stop and think"},
  {"id":"cr-003","cat":"stop-think","type":"role-play","hook":"You feel rushed into a choice.","setup":"Buy yourself thinking time. Say:","yourLine":[{"text":"\"Let me think about it and get back to you.\"","best":true},{"text":"\"Okay, fine, whatever you want.\""}],"relearn":"You can ask for time before deciding; that's smart, not weak.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-004","cat":"stop-think","type":"reflect","hook":"Lensy: a Crossroads is any moment you have to choose. Notice you hit lots of them?","prompt":"What do you think?","options":["Yes, all day","Big and small ones","More than I realised"],"affirm":"You make dozens of choices a day, practising helps you make them well.","relearn":"You face choices constantly; good decision-making is a daily skill.","persona":"any","source":"decision awareness"},
  {"id":"cr-005","cat":"stop-think","type":"branch","hook":"You're angry and about to fire off a reply.","options":[{"text":"Wait, breathe, decide when calm","consequence":"You avoid a reaction you'd regret.","outcome":"regulated","best":true},{"text":"Send it red-hot","consequence":"Heat-of-the-moment choices often backfire; pause first."}],"debrief":"Don't make big choices in the heat of a feeling; cool down first.","relearn":"Pause and cool down before deciding when you're worked up.","persona":"Aarav","source":"emotion + decisions (links g41)"},
  {"id":"cr-006","cat":"stop-think","type":"build","hook":"Build your 'stop and think' move.","prompt":"Order the first steps of a good decision.","pieces":["pause / breathe","ask 'what's really going on?'","think before acting"],"mode":"sequence","key":["pause / breathe","ask 'what's really going on?'","think before acting"],"relearn":"Pause, understand the moment, then think, before you act.","persona":"any","source":"decision process"},
  {"id":"cr-007","cat":"stop-think","type":"reflect","hook":"Lensy: even just counting to three before choosing helps. Try it?","prompt":"What do you think?","options":["Yes","Worth a try","Simple but smart"],"affirm":"A three-second pause is a tiny habit with big payoff.","relearn":"A quick count to three before deciding really helps.","persona":"any","source":"stop and think"},
  // — See your options (not black-and-white) —
  {"id":"cr-008","cat":"see-options","type":"branch","hook":"It feels like you only have two choices: do the dare, or lose the friends.","options":[{"text":"Look for a third option (suggest something else fun)","consequence":"You find a way that keeps friends AND your line.","outcome":"creative","best":true},{"text":"Pick one of the two and feel stuck","consequence":"There's almost always a third option; look for it."}],"debrief":"Most crossroads have more than two paths, brainstorm a third.","relearn":"Look beyond two options; there's usually a third way.","persona":"Aarav","source":"options thinking"},
  {"id":"cr-009","cat":"see-options","type":"strike-rewrite","hook":"\"There are only two choices: their way or no friends.\"","myth":{"un":"It's always do-what-they-say or be alone.","re":"Most situations have several options, not just two.","why":"Black-and-white thinking hides good middle paths."},"relearn":"Most choices aren't just two options; look for more.","persona":"any","source":"options thinking"},
  {"id":"cr-010","cat":"see-options","type":"reflect","hook":"Lensy: ask yourself 'what are three things I could do here?' Useful trick?","prompt":"What do you think?","options":["Yes","Opens it up","I'll ask that"],"affirm":"'What are three options?' breaks black-and-white thinking.","relearn":"Asking for three options widens your choices.","persona":"any","source":"options thinking"},
  {"id":"cr-011","cat":"see-options","type":"branch","hook":"Two friends fell out and each wants you to take their side.","options":[{"text":"Find a third path: stay kind to both, don't carry messages","consequence":"You keep both friendships and stay out of it.","outcome":"wise","best":true},{"text":"Pick a side","consequence":"You don't have to pick a side; there's a kinder third option."}],"debrief":"You don't have to choose between two friends; a third path exists.","relearn":"At a friendship crossroads, look for a path that hurts no one.","persona":"Diya","source":"options / friendship (links g09)"},
  {"id":"cr-012","cat":"see-options","type":"sort","hook":"Sort: a real option here, or a false 'only two'?","items":[{"id":"a","text":"Suggest a different activity"},{"id":"b","text":"Either obey or be alone"},{"id":"c","text":"Ask for time to decide"},{"id":"d","text":"It's all or nothing"},{"id":"e","text":"Ask 'what else could we do?'"},{"id":"f","text":"Do it their way or never speak again"}],"bins":[{"id":"real","label":"Real option","valence":"pos"},{"id":"false","label":"False 'only two'","valence":"neg"}],"key":{"a":"real","b":"false","c":"real","d":"false","e":"real","f":"false"},"relearn":"Suggesting alternatives, asking for time and asking 'what else?' are real options; 'all or nothing' is a trap.","persona":"any","source":"options thinking"},
  {"id":"cr-013","cat":"see-options","type":"reflect","hook":"Lensy: even 'do nothing right now' can be an option. Knew that?","prompt":"What do you think?","options":["Yes","Waiting counts","Good to know"],"affirm":"Sometimes the best move is to wait and not decide yet.","relearn":"Waiting, or not deciding yet, is a valid option too.","persona":"any","source":"options thinking"},
  // — Weigh the consequences (then what?) —
  {"id":"cr-014","cat":"weigh-consequences","type":"branch","hook":"You could copy a friend's homework to save time tonight.","options":[{"text":"Think ahead: you'd learn nothing and could get caught","consequence":"You decide to do your own or ask for help.","outcome":"thoughtful","best":true},{"text":"Copy without thinking ahead","consequence":"'Then what?' thinking shows copying costs more than it saves."}],"debrief":"Ask 'then what?', the short win can cost more later.","relearn":"Think about what happens next before you choose.","persona":"any","source":"consequential thinking"},
  {"id":"cr-015","cat":"weigh-consequences","type":"reflect","hook":"Lensy: the magic question is 'what might happen if I choose this?' Powerful?","prompt":"What do you think?","options":["Yes","Then-what thinking","I'll use it"],"affirm":"'What might happen?' is the heart of weighing a choice.","relearn":"Ask 'what might happen if I choose this?' for each option.","persona":"any","source":"consequential thinking"},
  {"id":"cr-016","cat":"weigh-consequences","type":"branch","hook":"Friends want you to skip class to hang out.","options":[{"text":"Weigh it: miss work, get in trouble vs a bit of fun","consequence":"You see the cost outweighs the fun and say no.","outcome":"thoughtful","best":true},{"text":"Go without weighing it","consequence":"Weighing the real costs makes the choice clearer."}],"debrief":"Weighing the real costs and benefits makes a fuzzy choice clear.","relearn":"Weigh the costs and benefits before deciding.","persona":"Aarav","source":"pros and cons"},
  {"id":"cr-017","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Spreading a rumour","right":"Hurt + lost trust"},{"left":"Helping a friend study","right":"They learn + closer bond"},{"left":"Lying to a parent","right":"Trust damaged if found out"},{"left":"Owning up to a mistake","right":"Respect for your honesty"},{"left":"Leaving someone out","right":"They feel hurt and alone"}],"relearn":"Every choice has likely consequences you can predict.","persona":"any","source":"consequential thinking","cat":"weigh-consequences"},
  {"id":"cr-018","cat":"weigh-consequences","type":"strike-rewrite","hook":"\"Only the right-now matters; the future doesn't.\"","myth":{"un":"Only how I feel right now matters in a choice.","re":"Good choices weigh the future too, not just the moment.","why":"The 'then what?' often matters more than the now."},"relearn":"Weigh the longer-term, not just the right-now.","persona":"any","source":"long-term thinking"},
  {"id":"cr-019","cat":"weigh-consequences","type":"branch","hook":"You could post something funny but mean about a classmate.","options":[{"text":"Think ahead: it could spread and really hurt them","consequence":"You don't post it; you avoid lasting harm.","outcome":"thoughtful","best":true},{"text":"Post it for the laughs","consequence":"Online, consequences spread fast and last; think ahead."}],"debrief":"Online choices have big, lasting ripples, weigh them.","relearn":"Think ahead about online choices; they ripple far.","persona":"any","source":"consequences / online (links g12)"},
  {"id":"cr-020","cat":"weigh-consequences","type":"build","hook":"Build a quick pros-and-cons check.","prompt":"What goes in a good weigh-up?","pieces":["good things that could happen","not-so-good things","how it affects others","how I'll feel after"],"mode":"assemble","key":["good things that could happen","not-so-good things","how it affects others","how I'll feel after"],"relearn":"Weigh the goods, the bads, the effect on others, and how you'll feel after.","persona":"any","source":"pros and cons"},
  {"id":"cr-021","cat":"weigh-consequences","type":"reflect","hook":"Lensy: a choice that feels great now can feel bad later, and the reverse. Noticed?","prompt":"What do you think?","options":["Yes","Future me matters","I'll think ahead"],"affirm":"Thinking of 'future you' helps you choose well now.","relearn":"Consider how 'future you' will feel about the choice.","persona":"Diya","source":"long-term thinking"},
  {"id":"cr-022","type":"sort","hook":"Sort: a short-term win that's a long-term loss, or a good long-term choice?","items":[{"id":"a","text":"Cheating to win once"},{"id":"b","text":"Practising to get good"},{"id":"c","text":"Skipping practice for TV"},{"id":"d","text":"Saving up for something you want"},{"id":"e","text":"Revising a little each day"},{"id":"f","text":"Copying homework to finish fast"}],"bins":[{"id":"longgood","label":"Good long-term","valence":"pos"},{"id":"shortwin","label":"Short win, long loss","valence":"neg"}],"key":{"a":"shortwin","b":"longgood","c":"shortwin","d":"longgood","e":"longgood","f":"shortwin"},"relearn":"Good choices often trade a small now for a bigger later.","persona":"any","source":"long-term thinking","cat":"weigh-consequences"},
  // — Decide by your values —
  {"id":"cr-023","cat":"decide-with-values","type":"reflect","hook":"Lensy: when choices are hard, ask 'what kind of person do I want to be?' Helpful compass?","prompt":"What do you think?","options":["Yes","A good compass","I'll ask that"],"affirm":"Your values are a compass that points the way at hard crossroads.","relearn":"Deciding by your values guides you through hard choices.","persona":"any","source":"values-based decisions"},
  {"id":"cr-024","cat":"decide-with-values","type":"branch","hook":"Going along would be easy, but it doesn't feel right to you.","options":[{"text":"Trust that 'doesn't feel right' and choose your values","consequence":"You feel proud, even if it's harder.","outcome":"values","best":true},{"text":"Ignore the feeling and go along","consequence":"That 'doesn't feel right' is your values talking; listen."}],"debrief":"That uneasy feeling is often your values flagging the choice.","relearn":"Listen to the 'this isn't right' feeling; it's your values.","persona":"Aarav","source":"values / conscience"},
  {"id":"cr-025","cat":"decide-with-values","type":"strike-rewrite","hook":"\"The right choice is whatever keeps people liking me.\"","myth":{"un":"The best choice is whatever makes people like me.","re":"Sometimes the right choice isn't the popular one.","why":"Pleasing everyone can mean betraying yourself."},"relearn":"The right choice isn't always the popular one.","persona":"Diya","source":"values vs approval"},
  {"id":"cr-026","type":"match","persona":"any","hook":"Match the value to a choice that honours it.","pairs":[{"left":"Honesty","right":"Owning up to a mistake"},{"left":"Kindness","right":"Including a left-out kid"},{"left":"Fairness","right":"Sharing the turn"},{"left":"Courage","right":"Doing the right but unpopular thing"},{"left":"Loyalty","right":"Standing by a friend who's honest"}],"relearn":"Your values point to choices that honour them.","source":"values","cat":"decide-with-values"},
  {"id":"cr-027","cat":"decide-with-values","type":"reflect","hook":"Lensy: what's one value that matters a lot to you?","prompt":"Pick one.","options":["Honesty","Kindness","Fairness","Loyalty"],"affirm":"Knowing your values makes tough choices clearer.","relearn":"Knowing your core values helps you decide.","persona":"any","source":"values clarity"},
  {"id":"cr-028","cat":"decide-with-values","type":"branch","hook":"A choice could get you ahead but means letting a friend down.","options":[{"text":"Weigh your values: is the win worth it?","consequence":"You choose in a way you can be proud of.","outcome":"values","best":true},{"text":"Take the win, ignore the cost to the friend","consequence":"Check the choice against your values before deciding."}],"debrief":"Run a tempting choice past your values before you take it.","relearn":"Check tempting choices against your values.","persona":"any","source":"values"},
  {"id":"cr-029","cat":"decide-with-values","type":"role-play","hook":"You've decided to do the right but unpopular thing.","setup":"Own it calmly. Say:","yourLine":[{"text":"\"I'm going to do what I think is right.\"","best":true},{"text":"\"Okay, I'll just go with the crowd.\""}],"relearn":"You can calmly stand by a values-based choice.","persona":"Aarav","source":"values / voice"},
  {"id":"cr-030","cat":"decide-with-values","type":"strike-rewrite","hook":"\"If everyone's doing it, it must be the right choice.\"","myth":{"un":"If everyone's doing it, it's the right choice.","re":"Popular and right aren't the same; decide for yourself.","why":"Crowds can be wrong."},"relearn":"'Everyone's doing it' doesn't make it right.","persona":"any","source":"values vs conformity"},
  // — Friendship crossroads —
  {"id":"cr-031","cat":"friendship-crossroads","type":"branch","hook":"A friend asks you to cover for them about something risky.","options":[{"text":"Care for them honestly, even if it's not what they want","consequence":"You're a true friend, not just a convenient one.","outcome":"caring","best":true},{"text":"Cover for them no matter what","consequence":"Real loyalty includes not helping a friend do harm."}],"debrief":"True loyalty sometimes means not covering for a friend.","relearn":"Being a real friend can mean not covering for them.","persona":"Diya","source":"loyalty vs right"},
  {"id":"cr-032","cat":"friendship-crossroads","type":"strike-rewrite","hook":"\"A real friend always covers for you, no matter what.\"","myth":{"un":"Real friends cover for each other no matter what.","re":"Real friends look out for your wellbeing, even when it's not what you asked.","why":"Helping someone do harm isn't loyalty."},"relearn":"Loyalty isn't covering for anything; it's caring for the real you.","persona":"any","source":"loyalty"},
  {"id":"cr-033","cat":"friendship-crossroads","type":"branch","hook":"Your group is leaving someone out, and you can feel it's wrong.","options":[{"text":"Choose to include them, even if the group grumbles","consequence":"You do the kind thing; others may follow.","outcome":"ally","best":true},{"text":"Go along with the exclusion","consequence":"You can choose kindness over going along."}],"debrief":"At a crossroads between the group and kindness, you can pick kindness.","relearn":"You can choose to include someone, even against the group.","persona":"any","source":"inclusion / decisions"},
  {"id":"cr-034","cat":"friendship-crossroads","type":"branch","hook":"A friend is about to do something that could hurt them; you know.","options":[{"text":"Tell a trusted adult, even if the friend is upset","consequence":"You may have helped keep them safe.","outcome":"caring","best":true},{"text":"Stay quiet to keep the friend happy","consequence":"For safety, telling beats staying quiet, even if they're cross."}],"debrief":"If a friend's safety is at stake, telling a trusted adult is the right call.","relearn":"For a friend's safety, telling a trusted adult is the right choice.","persona":"Asha","source":"safeguarding (links g09)"},
  {"id":"cr-035","cat":"friendship-crossroads","type":"reflect","hook":"Lensy: hard friend choices test what kind of friend you are. Worth getting right?","prompt":"What do you think?","options":["Yes","It matters","I want to choose well"],"affirm":"Choosing well at friend crossroads makes you the friend others trust.","relearn":"How you choose at friendship crossroads shapes who you are.","persona":"any","source":"values / friendship"},
  {"id":"cr-036","cat":"friendship-crossroads","type":"branch","hook":"You did something unkind to keep in with the group, and feel bad.","options":[{"text":"Apologise and rejoin your values","consequence":"You repair it and choose better next time.","outcome":"repair","best":true},{"text":"Pretend you don't care","consequence":"Owning it and apologising is the braver, better path."}],"debrief":"If a choice went against your values, you can own it and change.","relearn":"You can repair a choice that went against your values.","persona":"any","source":"repair / accountability"},
  {"id":"cr-037","type":"sort","items":[{"id":"a","text":"Gently telling a friend a hard truth"},{"id":"b","text":"Helping them cheat"},{"id":"c","text":"Standing up for them"},{"id":"d","text":"Joining in to exclude someone"},{"id":"e","text":"Getting help when they're unsafe"},{"id":"f","text":"Spreading their secret"}],"bins":[{"id":"true","label":"True-friend choice","valence":"pos"},{"id":"goalong","label":"Just going along","valence":"neg"}],"key":{"a":"true","b":"goalong","c":"true","d":"goalong","e":"true","f":"goalong"},"cat":"friendship-crossroads","persona":"any","source":"friendship / values","relearn":"True-friend choices care for people; go-along choices just avoid friction.","hook":"Sort: a true-friend choice, or a go-along choice?"},
  {"id":"cr-038","cat":"friendship-crossroads","type":"role-play","hook":"A friend pressures you to ditch another friend.","setup":"Refuse the ultimatum. Say:","yourLine":[{"text":"\"I don't want to choose; I can be friends with both.\"","best":true},{"text":"\"Okay, I'll drop them.\""}],"relearn":"You can refuse a 'pick me or them' ultimatum.","persona":"Diya","source":"friendship / voice"},
  // — Owning your choice —
  {"id":"cr-039","cat":"own-your-choice","type":"branch","hook":"You made a choice that turned out badly.","options":[{"text":"Own it, learn from it, and try a better choice next time","consequence":"You grow; a bad call becomes a lesson.","outcome":"growth","best":true},{"text":"Blame everyone else","consequence":"Owning a choice is how you learn from it."}],"debrief":"Owning a choice, good or bad, is how your judgement grows.","relearn":"Own your choices and learn from the ones that go wrong.","persona":"Aarav","source":"accountability"},
  {"id":"cr-040","cat":"own-your-choice","type":"strike-rewrite","hook":"\"A bad decision means I'm a bad or stupid person.\"","myth":{"un":"Making a bad choice means I'm bad or stupid.","re":"Everyone makes some bad calls; what matters is learning.","why":"Mistakes are part of learning to decide well."},"relearn":"A bad choice doesn't define you; learning from it does.","persona":"any","source":"growth mindset"},
  {"id":"cr-041","cat":"own-your-choice","type":"reflect","hook":"Lensy: it's okay to change your mind if a choice isn't working. Agree?","prompt":"What do you think?","options":["Yes","I can course-correct","Good to know"],"affirm":"Changing course when something's not working is smart, not weak.","relearn":"You can change a choice that isn't working out.","persona":"any","source":"flexibility"},
  {"id":"cr-042","cat":"own-your-choice","type":"branch","hook":"You're facing a big, confusing choice alone.","options":[{"text":"Ask a trusted adult for advice","consequence":"A wise outside view helps you decide.","outcome":"resourceful","best":true},{"text":"Stress about it in secret","consequence":"Asking for advice is a smart part of deciding."}],"debrief":"Asking a trusted person for advice is part of good decision-making.","relearn":"For big choices, ask a trusted adult for advice.","persona":"Rohit","source":"help-seeking"},
  {"id":"cr-043","cat":"own-your-choice","type":"reflect","hook":"Lensy: every choice you own teaches you something for next time. See the pattern?","prompt":"What do you think?","options":["Yes","I'm learning","Choices = practice"],"affirm":"Each owned choice sharpens your judgement for the next one.","relearn":"Owning choices builds better judgement over time.","persona":"any","source":"growth"},
  {"id":"cr-044","cat":"own-your-choice","type":"role-play","hook":"You realise a choice you made hurt someone.","setup":"Take responsibility. Say:","yourLine":[{"text":"\"That was my call, and I'm sorry, I'll fix it.\"","best":true},{"text":"\"It wasn't my fault.\""}],"relearn":"Owning your part of a choice is mature and respected.","persona":"any","source":"accountability / voice"},
  {"id":"cr-045","cat":"own-your-choice","type":"sort","hook":"Sort: owning a choice, or dodging it?","items":[{"id":"a","text":"\"I chose that, and here's what I learned\""},{"id":"b","text":"\"It's everyone else's fault\""},{"id":"c","text":"Apologising and fixing it"},{"id":"d","text":"Making excuses"},{"id":"e","text":"\"That was my call to make\""},{"id":"f","text":"\"Don't blame me for any of it\""}],"bins":[{"id":"own","label":"Owning it","valence":"pos"},{"id":"dodge","label":"Dodging it","valence":"neg"}],"key":{"a":"own","b":"dodge","c":"own","d":"dodge","e":"own","f":"dodge"},"relearn":"Owning a choice means accepting and learning, not excusing.","persona":"any","source":"accountability"},
  {"id":"cr-046","cat":"stop-think","type":"branch","hook":"A salesy ad pressures you to 'decide now or miss out'.","options":[{"text":"Recognise the rush trick and take your time","consequence":"You don't get pushed into a hasty choice.","outcome":"savvy","best":true},{"text":"Decide instantly because of the timer","consequence":"'Decide now!' is a pressure trick; slow down."}],"debrief":"'Decide now!' is often a trick; real choices can wait for thought.","relearn":"Beware 'decide now' pressure; you can take time.","persona":"Aarav","source":"decisions / persuasion (links g12)"},
  {"id":"cr-047","cat":"see-options","type":"branch","hook":"You and a friend both want to do different things this weekend.","options":[{"text":"Brainstorm options: take turns, find a third thing you both like","consequence":"You find a win-win instead of a standoff.","outcome":"creative","best":true},{"text":"Insist on your way only","consequence":"Brainstorming options beats a my-way standoff."}],"debrief":"Generating options together turns a clash into a solution.","relearn":"Brainstorm options together to find a win-win.","persona":"Diya","source":"options / compromise"},
  {"id":"cr-048","cat":"weigh-consequences","type":"reflect","hook":"Lensy: who else does this choice affect? Worth checking?","prompt":"What do you think?","options":["Yes","Others matter","I'll consider them"],"affirm":"Good choices consider how they land on others, too.","relearn":"Consider who else your choice affects.","persona":"any","source":"consequences / empathy"},
  {"id":"cr-049","cat":"decide-with-values","type":"branch","hook":"You could win by bending the rules and probably not get caught.","options":[{"text":"Choose fair play because it matches your values","consequence":"You win or lose with integrity intact.","outcome":"values","best":true},{"text":"Bend the rules since no one's looking","consequence":"Values guide you even when no one's watching."}],"debrief":"Who you are when no one's watching is your real character.","relearn":"Let your values guide you even when no one's watching.","persona":"any","source":"integrity"},
  {"id":"cr-050","cat":"friendship-crossroads","type":"branch","hook":"Your friends mock someone and look at you to join in.","options":[{"text":"Choose not to join, change the subject or speak up","consequence":"You stay kind; sometimes others follow.","outcome":"ally","best":true},{"text":"Join in to fit in","consequence":"At this crossroads, you can choose kindness over fitting in."}],"debrief":"A crossroads between fitting in and kindness, choose kindness.","relearn":"You can choose not to join in mockery.","persona":"any","source":"bystander / decisions (links g11)"},
  {"id":"cr-051","cat":"own-your-choice","type":"reflect","hook":"Lensy: you won't always choose perfectly, and that's okay. Relieved?","prompt":"What do you think?","options":["Yes","No one's perfect","I'll keep learning"],"affirm":"Nobody decides perfectly; steady practice is what counts.","relearn":"You won't always choose perfectly; keep learning.","persona":"any","source":"self-compassion"},
  {"id":"cr-052","cat":"stop-think","type":"strike-rewrite","hook":"\"Asking for time to think makes me look indecisive.\"","myth":{"un":"Asking for time to decide looks weak or indecisive.","re":"Taking time to think is a sign of a careful decider.","why":"Good deciders don't rush important calls."},"relearn":"Taking time to decide is smart, not weak.","persona":"any","source":"stop and think"},
  {"id":"cr-053","cat":"see-options","type":"reflect","hook":"Lensy: at a crossroads, picture each path leading somewhere. Helpful image?","prompt":"What do you think?","options":["Yes","I can see the paths","Nice way to think"],"affirm":"Picturing where each path leads helps you choose.","relearn":"Imagine where each option leads before choosing.","persona":"any","source":"options / consequences"},
  {"id":"cr-054","cat":"weigh-consequences","type":"branch","hook":"A risky dare could make you 'cool' but could also hurt you.","options":[{"text":"Weigh real risk vs a moment of 'cool'","consequence":"You see the risk isn't worth a few seconds of cred.","outcome":"thoughtful","best":true},{"text":"Do it for the clout","consequence":"Weigh real harm against fleeting 'cool', it rarely adds up."}],"debrief":"Weigh lasting risk against fleeting status; usually it's not worth it.","relearn":"Weigh real risk against short-lived 'cool'.","persona":"Aarav","source":"risk / consequences"},
  {"id":"cr-055","cat":"decide-with-values","type":"reflect","hook":"Lensy: a good choice is one you could explain to someone you respect. Test?","prompt":"What do you think?","options":["Yes","Good test","I'll use it"],"affirm":"If you could explain it to someone you respect, it's probably right.","relearn":"Test a choice: could you explain it to someone you respect?","persona":"Rohit","source":"values test"},
  {"id":"cr-056","cat":"friendship-crossroads","type":"branch","hook":"You promised two friends two different things at the same time.","options":[{"text":"Be honest, apologise, and sort it fairly","consequence":"Honesty keeps both friendships intact.","outcome":"honest","best":true},{"text":"Dodge both and hope they forget","consequence":"Honesty and a fair fix beat dodging."}],"debrief":"When choices clash, honesty and a fair fix work best.","relearn":"When you can't keep both promises, be honest and fix it fairly.","persona":"Diya","source":"honesty / decisions"},
  {"id":"cr-057","cat":"own-your-choice","type":"branch","hook":"You're tempted to blame a friend for a choice you both made.","options":[{"text":"Own your share of it","consequence":"You stay fair and keep the friendship.","outcome":"accountable","best":true},{"text":"Pin it all on them","consequence":"Owning your share is fairer and more respected."}],"debrief":"Own your part of a shared choice; don't scapegoat.","relearn":"Own your share of a choice you made together.","persona":"any","source":"accountability"},
  {"id":"cr-058","cat":"stop-think","type":"reflect","hook":"Lensy: which is your hardest moment to pause in, anger, excitement, or pressure?","prompt":"Be honest.","options":["Anger","Excitement","Pressure","All of them"],"affirm":"Knowing when you rush helps you build a pause there.","relearn":"Know the moments you rush, and practise pausing then.","persona":"Aarav","source":"self-awareness"},
  {"id":"cr-059","type":"sort","hook":"Sort: thinking ahead, or only-now thinking?","items":[{"id":"a","text":"\"How will I feel about this tomorrow?\""},{"id":"b","text":"\"I want it NOW, who cares later\""},{"id":"c","text":"\"What might go wrong?\""},{"id":"d","text":"\"Just do it, don't think\""},{"id":"e","text":"\"Who else does this affect?\""},{"id":"f","text":"\"Decide instantly, no thinking\""}],"bins":[{"id":"ahead","label":"Thinking ahead","valence":"pos"},{"id":"now","label":"Only-now","valence":"neg"}],"key":{"a":"ahead","b":"now","c":"ahead","d":"now","e":"ahead","f":"now"},"relearn":"Thinking ahead asks how you'll feel later and what could go wrong.","persona":"any","source":"long-term thinking","cat":"weigh-consequences"},
  {"id":"cr-060","cat":"decide-with-values","type":"branch","hook":"Doing the right thing here means missing out on something fun.","options":[{"text":"Accept the trade-off for your values","consequence":"You feel solid about who you are.","outcome":"values","best":true},{"text":"Ditch your values for the fun","consequence":"Sometimes values cost a little fun; usually worth it."}],"debrief":"Living your values sometimes costs a little; it's usually worth it.","relearn":"Sometimes values cost a little fun, and it's worth it.","persona":"any","source":"values"},
  {"id":"cr-061","cat":"friendship-crossroads","type":"reflect","hook":"Lensy: a friend who only likes you when you do what they say, real friend?","prompt":"What do you think?","options":["Not really","A real friend respects my choices","Red flag"],"affirm":"A friend who respects your choices is the real kind.","relearn":"Real friends respect your right to make your own choices.","persona":"Diya","source":"friendship / autonomy (links g09)"},
  {"id":"cr-062","cat":"own-your-choice","type":"reflect","hook":"Lensy: you're the main decider in your own life. Feel that responsibility, and power?","prompt":"What do you think?","options":["Yes","My choices are mine","Powerful"],"affirm":"Your choices are yours, that's both a responsibility and a power.","relearn":"You're the main decision-maker in your own life.","persona":"any","source":"agency"},
  {"id":"cr-063","cat":"see-options","type":"branch","hook":"You're stuck between two bad options.","options":[{"text":"Ask: is there a different option, or a way to change the situation?","consequence":"You often find a better path or buy time.","outcome":"creative","best":true},{"text":"Just pick the less-bad one quickly","consequence":"Before settling for less-bad, look for a better third path."}],"debrief":"Two bad options is a cue to look harder for a third.","relearn":"Two bad options? Look for a third or change the situation.","persona":"any","source":"options thinking"},
  {"id":"cr-064","cat":"weigh-consequences","type":"branch","hook":"You could keep a found wallet or hand it in.","options":[{"text":"Hand it in; weigh how you'd feel and how the owner feels","consequence":"You do right and feel good about it.","outcome":"values","best":true},{"text":"Keep it","consequence":"Weighing the owner's loss and your conscience points to handing it in."}],"debrief":"Weigh others' feelings and your conscience, not just the gain.","relearn":"Weigh others and your conscience, not just what you'd get.","persona":"any","source":"values / consequences"},
  {"id":"cr-065","cat":"stop-think","type":"role-play","hook":"A friend wants an answer 'right now or never'.","setup":"Resist the false rush. Say:","yourLine":[{"text":"\"If it has to be now, then my answer is no.\"","best":true},{"text":"\"Okay okay, yes!\""}],"relearn":"A forced 'now or never' can get a calm 'then it's no'.","persona":"Aarav","source":"pressure / voice"},
  {"id":"cr-066","cat":"decide-with-values","type":"strike-rewrite","hook":"\"Doing the right thing is only worth it if people notice.\"","myth":{"un":"The right choice only counts if people see it.","re":"The right choice matters even when no one notices.","why":"Integrity is for you, not an audience."},"relearn":"The right choice counts even when no one's watching.","persona":"any","source":"integrity"},
  {"id":"cr-067","cat":"friendship-crossroads","type":"branch","hook":"Standing up for what's right might cost you a friendship.","options":[{"text":"Do what's right; a friend who needs you to do wrong isn't a true friend","consequence":"You keep your integrity, and the right people respect it.","outcome":"values","best":true},{"text":"Stay quiet to keep the friend","consequence":"A friendship that needs you to betray your values is shaky."}],"debrief":"If a friendship needs you to do wrong, that's the problem.","relearn":"Don't trade your values to keep such a friendship.","persona":"Aarav","source":"values / friendship"},
  {"id":"cr-068","cat":"own-your-choice","type":"build","hook":"Build your Crossroads decision routine.","prompt":"Order the steps of a good decision.","pieces":["stop and think","list my options","weigh consequences","check my values","choose and own it"],"mode":"sequence","key":["stop and think","list my options","weigh consequences","check my values","choose and own it"],"relearn":"Stop, list options, weigh consequences, check values, choose and own it.","persona":"any","source":"decision process / consolidation"},
  {"id":"cr-069","cat":"weigh-consequences","type":"reflect","hook":"Lensy: some choices are small and some are big. Spend more thought on the big ones?","prompt":"What do you think?","options":["Yes","Match thought to size","Smart"],"affirm":"Save your careful weighing for the choices that really matter.","relearn":"Give bigger choices more careful thought.","persona":"any","source":"decision proportion"},
  {"id":"cr-070","cat":"decide-with-values","type":"branch","hook":"Capstone: friends pressure you toward a choice that clashes with your values.","options":[{"text":"Stop, see options, weigh it, and choose your values","consequence":"You use the whole toolkit and choose well.","outcome":"values","best":true},{"text":"Cave to the pressure","consequence":"Run it through your decision steps; your values will guide you."}],"debrief":"Use your full routine, and let your values have the final word.","relearn":"Use your decision steps and let values decide at a hard crossroads.","persona":"Aarav","source":"consolidation"},
  {"id":"cr-071","cat":"see-options","type":"strike-rewrite","hook":"\"If I can't see a good option, there isn't one.\"","myth":{"un":"If I can't immediately see a good option, none exists.","re":"Asking others or sleeping on it often reveals new options.","why":"Options aren't always obvious at first."},"relearn":"If no good option is obvious, ask or wait, more may appear.","persona":"any","source":"options thinking"},
  {"id":"cr-072","cat":"weigh-consequences","type":"reflect","hook":"Lensy: 'will I be proud or sorry tomorrow?' is a quick consequence check. Use it?","prompt":"What do you think?","options":["Yes","Proud-or-sorry test","I'll use it"],"affirm":"The 'proud or sorry tomorrow?' check is fast and powerful.","relearn":"Ask 'will I be proud or sorry tomorrow?' before deciding.","persona":"Diya","source":"consequential thinking"},
  {"id":"cr-073","cat":"friendship-crossroads","type":"role-play","hook":"A friend's about to make a risky choice and asks what you think.","setup":"Be honestly caring. Say:","yourLine":[{"text":"\"As your friend, I don't think that's a good idea, here's why.\"","best":true},{"text":"\"Sure, do whatever.\""}],"relearn":"A caring friend shares honest concern about a risky choice.","persona":"Asha","source":"friendship / voice"},
  {"id":"cr-074","cat":"own-your-choice","type":"branch","hook":"You followed advice and it went wrong; you want to blame the adviser.","options":[{"text":"Accept you chose to follow it, and learn","consequence":"You keep ownership and grow.","outcome":"growth","best":true},{"text":"Blame them entirely","consequence":"You chose to take the advice; own your part."}],"debrief":"Even when you follow advice, the choice was still yours to make.","relearn":"Taking advice is still your choice; own the outcome.","persona":"any","source":"accountability"},
  {"id":"cr-075","cat":"stop-think","type":"reflect","hook":"Lensy: pausing isn't slow or scared, it's how good deciders work. Reframe it?","prompt":"What do you think?","options":["Yes","Pausing is strength","Reframed"],"affirm":"The pause is a power move, not a weakness.","relearn":"Pausing to think is a strength, not a weakness.","persona":"any","source":"stop and think"},
  {"id":"cr-076","cat":"decide-with-values","type":"reflect","hook":"Lensy: your choices, over time, become your character. Worth choosing well?","prompt":"What do you think?","options":["Yes","Choices = who I become","Worth it"],"affirm":"Each good choice is a brick in the person you're becoming.","relearn":"Your choices, repeated, become your character.","persona":"any","source":"character"},
  {"id":"cr-077","type":"sort","items":[{"id":"a","text":"Including the left-out kid"},{"id":"b","text":"Joining a pile-on"},{"id":"c","text":"Telling a hard truth kindly"},{"id":"d","text":"Spreading a secret"},{"id":"e","text":"Standing up for a friend"},{"id":"f","text":"Lying to cover a friend"}],"bins":[{"id":"wise","label":"Wise choice","valence":"pos"},{"id":"regret","label":"Regret later","valence":"neg"}],"key":{"a":"wise","b":"regret","c":"wise","d":"regret","e":"wise","f":"regret"},"cat":"friendship-crossroads","persona":"any","source":"values / decisions","relearn":"Wise crossroads choices are kind and honest; regret-later ones aren't.","hook":"Sort: a wise crossroads choice, or a regret-later one?"},
  {"id":"cr-078","cat":"weigh-consequences","type":"branch","hook":"Capstone: a choice offers a big reward but a real chance of harm to others.","options":[{"text":"Weigh the harm to others heavily; choose carefully","consequence":"You don't take a reward that hurts people.","outcome":"values","best":true},{"text":"Grab the reward, ignore the harm","consequence":"Harm to others should weigh heavily in any choice."}],"debrief":"A reward isn't worth it if it harms others; weigh that heavily.","relearn":"Weigh harm to others heavily, not just your own gain.","persona":"any","source":"ethics / consequences"},
  {"id":"cr-079","cat":"own-your-choice","type":"reflect","hook":"Lensy: what's one choice you're proud of making recently?","prompt":"Think of one.","options":["A kind one","A brave one","An honest one","A smart one"],"affirm":"Hold onto that, you can make more choices like it.","relearn":"Noticing your good choices helps you make more.","persona":"any","source":"self-efficacy"},
  {"id":"cr-080","cat":"decide-with-values","type":"role-play","hook":"You're at a real crossroads and choosing your values.","setup":"Affirm your decision. Say:","yourLine":[{"text":"\"This is my choice, and it's the right one for me.\"","best":true},{"text":"\"I'll just do what's easiest.\""}],"relearn":"You can own a values-based choice with confidence.","persona":"Aarav","source":"values / voice"},
  {"id":"cr-081","cat":"stop-think","type":"sort","hook":"Sort: helps you decide well, or rushes you?","items":[{"id":"a","text":"Taking a breath first"},{"id":"b","text":"A 'decide now!' timer"},{"id":"c","text":"Listing your options"},{"id":"d","text":"Friends chanting 'do it'"},{"id":"e","text":"Saying 'let me think'"},{"id":"f","text":"A dare shouted in your face"}],"bins":[{"id":"helps","label":"Helps decide well","valence":"pos"},{"id":"rushes","label":"Rushes you","valence":"uhoh"}],"key":{"a":"helps","b":"rushes","c":"helps","d":"rushes","e":"helps","f":"rushes"},"relearn":"Breathing and listing options help; timers, dares and chants rush you.","persona":"any","source":"decision process"},
  {"id":"cr-082","cat":"own-your-choice","type":"reflect","hook":"Lensy: what's your big take-away from Crossroads?","prompt":"Pick your motto.","options":["Stop and think","See more options","Weigh consequences","Choose my values"],"affirm":"Carry that. You're ready to choose well at any crossroads.","relearn":"Stop, see options, weigh consequences, choose your values, own it.","persona":"any","source":"consolidation"},
  {"id":"cr-083","cat":"see-options","type":"reflect","hook":"Lensy: knowing you always have options makes you feel...?","prompt":"Pick one.","options":["Free","In control","Less stuck"],"affirm":"Knowing you have options is freedom; you're never truly stuck.","relearn":"You always have options; that's a kind of freedom.","persona":"any","source":"agency"},
  {"id":"cr-084","cat":"friendship-crossroads","type":"reflect","hook":"Lensy: the friends who respect your choices are keepers. Agree?","prompt":"What do you think?","options":["Yes","Keepers","Those are real friends"],"affirm":"Friends who respect your choices are the ones worth keeping.","relearn":"Keep the friends who respect your right to choose.","persona":"Diya","source":"friendship / autonomy"},
  {"id":"cr-900","type":"reflect","persona":"any","hook":"Lensy: before a hard choice, ask 'who do I want to be after this?' Useful?","prompt":"What do you think?","options":["Yes","A real compass","I'll try that"],"affirm":"Picturing who you want to be after a choice makes the right path clearer.","relearn":"Ask who you want to be after a choice; it guides you.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-901","type":"reflect","persona":"any","hook":"Lensy: which value would you never trade away, even to fit in?","prompt":"Pick one.","options":["Honesty","Fairness","Loyalty","Courage"],"affirm":"Naming the value you won't trade makes pressure easier to stand up to.","relearn":"Knowing the value you won't trade steadies you under pressure.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-902","type":"reflect","persona":"Diya","hook":"Lensy: would your choice still feel right if no one ever found out?","prompt":"What do you think?","options":["Yes","Good test","I'll check that"],"affirm":"If a choice feels right even unseen, your values are leading it.","relearn":"A choice that feels right unseen is led by your values.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-903","type":"reflect","persona":"Rohit","hook":"Lensy: could you tell your choice to someone you really look up to?","prompt":"Pick one.","options":["Yes","Most of the time","I'd want to"],"affirm":"If you could explain it to someone you respect, it's likely the right call.","relearn":"Test a choice: could you explain it to someone you respect?","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-904","type":"reflect","persona":"any","hook":"Lensy: liked by everyone, or true to yourself — which matters more right now?","prompt":"What feels true?","options":["True to myself","A bit of both","Still figuring it out"],"affirm":"There's no wrong answer here; noticing the pull is what matters.","relearn":"Pleasing everyone can cost being true to yourself; notice the pull.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-905","type":"reflect","persona":"Aarav","hook":"Lensy: 'everyone's doing it' — does that alone make a thing right for you?","prompt":"What do you think?","options":["No","Not by itself","I'll decide for me"],"affirm":"Deciding for yourself, not by the crowd, is real strength.","relearn":"'Everyone's doing it' doesn't decide it; you do.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-906","type":"reflect","persona":"any","hook":"Lensy: think of a value you're proud you stuck to once. What was it?","prompt":"Pick or picture one.","options":["Honesty","Kindness","Standing up for someone","Keeping a promise"],"affirm":"Remembering a time you stood by a value makes the next time easier.","relearn":"Recalling a value you kept makes keeping it again easier.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-907","type":"reflect","persona":"any","hook":"Lensy: a choice can be popular and still not be right. Have you seen that?","prompt":"What do you think?","options":["Yes","Sometimes","I think so"],"affirm":"Spotting that popular and right differ is a sign you're deciding for yourself.","relearn":"Popular and right are different things; you can tell them apart.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-908","type":"reflect","persona":"Diya","hook":"Lensy: which would future-you thank you for — easy now, or right now?","prompt":"What feels true?","options":["The right one","Depends on the day","I'd ask future-me"],"affirm":"Checking what future-you would thank you for is your values speaking.","relearn":"Asking what future-you would thank you for guides the choice.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-909","type":"reflect","persona":"any","hook":"Lensy: a tiny lie that helps you fit in — does it sit right with you?","prompt":"What do you think?","options":["Not really","Sometimes hard","I'd rather be honest"],"affirm":"Noticing when a small lie doesn't sit right is your honesty value working.","relearn":"When a small lie doesn't sit right, that's your honesty talking.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-910","type":"reflect","persona":"any","hook":"Lensy: if your choice were on a poster, would you be glad it was yours?","prompt":"What do you think?","options":["Yes","Usually","I'd want to be"],"affirm":"Picturing your choice on a poster is a quick, honest values check.","relearn":"Imagine your choice on a poster; would you own it proudly?","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-911","type":"reflect","persona":"Aarav","hook":"Lensy: standing by what's right can feel lonely. Still worth it to you?","prompt":"What feels true?","options":["Yes","Hard but yes","Some days"],"affirm":"It's okay to find it hard; choosing your values even when alone is brave.","relearn":"Choosing your values can feel lonely and still be worth it.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-912","type":"reflect","persona":"any","hook":"Lensy: which feels better later — being liked, or liking who you were?","prompt":"Pick one.","options":["Liking who I was","Both matter","Still deciding"],"affirm":"Wanting to like who you were is your values pointing the way.","relearn":"Liking who you were later is a value-led way to choose.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-913","type":"reflect","persona":"Rohit","hook":"Lensy: a fair choice and an easy choice differ. Which do you lean to?","prompt":"What feels true?","options":["The fair one","It varies","I'd like to lean fair"],"affirm":"Leaning toward fair, even when it's harder, is your values at work.","relearn":"Leaning to the fair choice over the easy one follows your values.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-914","type":"branch","persona":"any","hook":"The group is mocking a new kid. Joining in would make you fit in.","options":[{"text":"Stay out of it and be kind to the new kid","consequence":"You feel solid; you acted like the person you want to be.","outcome":"values","best":true},{"text":"Join the mocking so you fit in","consequence":"Fitting in this way costs your kindness; check it against your values."}],"debrief":"Fitting in isn't worth trading away a value like kindness.","relearn":"Don't trade kindness just to fit in; decide by your values.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-915","type":"branch","persona":"Aarav","hook":"Friends dare you to skip class. Saying yes would look cool to them.","options":[{"text":"Pass; choose what you'd be proud of, not what looks cool","consequence":"You keep your self-respect even if they tease a bit.","outcome":"values","best":true},{"text":"Skip so you look cool","consequence":"Looking cool now can cost what you value; weigh that first."}],"debrief":"What looks cool and what you'd be proud of aren't always the same.","relearn":"Choose what you'd be proud of, not just what looks cool.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-916","type":"branch","persona":"Diya","hook":"You found a wallet with money. No one saw you pick it up.","options":[{"text":"Hand it in even though no one's watching","consequence":"You act with honesty whether seen or not.","outcome":"values","best":true},{"text":"Keep it since no one saw","consequence":"Who you are unseen is the real you; let values lead."}],"debrief":"The right choice matters even when nobody is watching.","relearn":"Integrity means choosing right even when no one sees.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-917","type":"branch","persona":"any","hook":"The whole class plans to prank a kind teacher. Everyone's in.","options":[{"text":"Decide for yourself and sit it out","consequence":"You choose by your values, not by the crowd's plan.","outcome":"values","best":true},{"text":"Join because everyone is","consequence":"'Everyone's in' isn't a reason; decide for yourself."}],"debrief":"A crowd can be wrong; deciding for yourself is the strong move.","relearn":"'Everyone's doing it' isn't a reason; decide for yourself.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-918","type":"branch","persona":"any","hook":"You could win the contest by copying a friend's secret design.","options":[{"text":"Enter your own work, even if it might not win","consequence":"You win or lose with your honesty intact.","outcome":"values","best":true},{"text":"Copy the design to win","consequence":"A win that breaks your values won't feel like one."}],"debrief":"A prize isn't worth a value you'd have to break to get it.","relearn":"Don't trade honesty for a win; the win won't feel right.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-919","type":"branch","persona":"Aarav","hook":"A funny but cruel meme about a classmate is going around. Share it?","options":[{"text":"Don't pass it on; it clashes with being kind","consequence":"You keep your kindness even when it's the unpopular move.","outcome":"values","best":true},{"text":"Share it for the laughs","consequence":"A laugh that hurts someone trades away your kindness."}],"debrief":"Funny isn't a free pass; check it against being kind.","relearn":"Don't pass on something cruel just because it's funny.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-920","type":"branch","persona":"Diya","hook":"You can blame a broken phone on a quiet kid who won't argue back.","options":[{"text":"Tell the truth that it was your slip","consequence":"You own it honestly and protect someone who can't defend himself.","outcome":"values","best":true},{"text":"Let the quiet kid take the blame","consequence":"Blaming someone who won't fight back breaks fairness and honesty."}],"debrief":"Honesty and fairness mean not pinning your slip on someone else.","relearn":"Don't pin your mistake on someone; choose honesty and fairness.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-921","type":"branch","persona":"any","hook":"The cool group will let you in only if you ignore your old friend.","options":[{"text":"Keep your old friend; a group worth joining wouldn't ask that","consequence":"You stay loyal and keep your self-respect.","outcome":"values","best":true},{"text":"Drop your old friend to get in","consequence":"A group that costs your loyalty isn't a real win."}],"debrief":"If joining means betraying a value, the price is too high.","relearn":"Don't betray a friend to be let in; that price is too high.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-922","type":"branch","persona":"any","hook":"You could pad a fundraiser total with money that wasn't really raised.","options":[{"text":"Report the real number, even if it looks smaller","consequence":"Your honesty holds and the count people trust is true.","outcome":"values","best":true},{"text":"Inflate the total to look better","consequence":"A nicer-looking lie still breaks the honesty you value."}],"debrief":"A better-looking number isn't worth your honesty.","relearn":"Report the true number; don't trade honesty for looking good.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-923","type":"branch","persona":"Aarav","hook":"Online, your squad is ganging up on one player. Pile on too?","options":[{"text":"Stay out and don't pile on","consequence":"You keep your fairness even when the squad doesn't.","outcome":"values","best":true},{"text":"Pile on so the squad approves","consequence":"Approval bought by being unfair costs a value you hold."}],"debrief":"Squad approval isn't worth ganging up against your values.","relearn":"Don't join a pile-on for approval; keep your fairness.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-924","type":"branch","persona":"Diya","hook":"You can sneak a peek at the answer key before tomorrow's test.","options":[{"text":"Don't look; study instead so the score is truly yours","consequence":"Whatever you score, it's honestly earned.","outcome":"values","best":true},{"text":"Peek since you probably won't get caught","consequence":"A score that isn't really yours breaks your honesty."}],"debrief":"A mark you cheated for isn't really yours; values say earn it.","relearn":"Earn your score honestly; a cheated mark isn't really yours.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-925","type":"branch","persona":"any","hook":"A teammate keeps the extra change a shopkeeper gave by mistake. Speak up?","options":[{"text":"Point out the mistake so it goes back","consequence":"Your fairness shows even when it's awkward.","outcome":"values","best":true},{"text":"Stay quiet and split the extra","consequence":"Keeping money that isn't yours breaks fairness."}],"debrief":"Returning what isn't yours is fairness in action, even if awkward.","relearn":"Return what isn't yours; fairness can be a little awkward.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-926","type":"branch","persona":"any","hook":"Trolling a teacher online would get you tons of likes from the group.","options":[{"text":"Skip it; likes aren't worth being unkind","consequence":"You keep your kindness instead of buying approval.","outcome":"values","best":true},{"text":"Post it for the likes","consequence":"Likes earned by being cruel cost a value you care about."}],"debrief":"Approval and likes aren't worth trading away kindness.","relearn":"Likes aren't worth being unkind; values beat approval.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-927","type":"branch","persona":"Rohit","hook":"You promised to help your cousin study, but a fun outing just came up.","options":[{"text":"Keep your promise; the outing can wait","consequence":"Your cousin can count on you; your word holds.","outcome":"values","best":true},{"text":"Ditch the promise for the outing","consequence":"Breaking a promise for fun chips at being someone people trust."}],"debrief":"Keeping your word is a value worth a little missed fun.","relearn":"Keep your promises; your word is worth a bit of missed fun.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-928","type":"branch","persona":"any","hook":"Your team could win by hiding an injury from the referee. Hide it?","options":[{"text":"Be honest with the referee about it","consequence":"You play fair, win or lose, and stay safe.","outcome":"values","best":true},{"text":"Hide it to keep the advantage","consequence":"An edge from hiding the truth breaks fair play."}],"debrief":"A win from hiding the truth isn't a fair win.","relearn":"Play fair; a win built on hiding the truth isn't real.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-929","type":"branch","persona":"any","hook":"The group wants to leave one friend out of the trip just to be mean.","options":[{"text":"Speak up to include them","consequence":"Your kindness and fairness shape the plan.","outcome":"values","best":true},{"text":"Go along with leaving them out","consequence":"Excluding someone to be mean clashes with your values."}],"debrief":"Including a left-out friend is a values choice you can make.","relearn":"Speak up to include; don't go along with being mean.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-930","type":"branch","persona":"Diya","hook":"You can take credit for a group project you barely worked on.","options":[{"text":"Give credit to the friend who did the work","consequence":"Your honesty and fairness stay intact.","outcome":"values","best":true},{"text":"Take the credit anyway","consequence":"Claiming work you didn't do breaks honesty and fairness."}],"debrief":"Taking credit you didn't earn trades away two of your values.","relearn":"Give credit where it's due; don't claim work you didn't do.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-931","type":"strike-rewrite","persona":"any","hook":"\"If a choice is popular, it's automatically the right one.\"","myth":{"un":"A popular choice is automatically the right one.","re":"Popular and right are not the same; decide by your values.","why":"Many people can agree on something and still be wrong."},"relearn":"Popular and right differ; decide by your values.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-932","type":"strike-rewrite","persona":"Aarav","hook":"\"Sticking to your values just makes you look uncool.\"","myth":{"un":"Standing by your values makes you look uncool.","re":"Standing by your values is a sign of real strength.","why":"Deciding for yourself takes more courage than following the crowd."},"relearn":"Standing by your values is strength, not uncool.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-933","type":"strike-rewrite","persona":"any","hook":"\"Doing the right thing only counts if you get credit for it.\"","myth":{"un":"The right choice only counts if you get credit.","re":"The right choice matters even when no one notices it.","why":"Integrity is something you keep for yourself, not for an audience."},"relearn":"The right choice counts even with no credit.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-934","type":"strike-rewrite","persona":"Diya","hook":"\"A choice nobody will ever find out about doesn't matter.\"","myth":{"un":"A choice no one will find out about doesn't matter.","re":"A choice still matters even if it stays secret.","why":"Each choice quietly shapes the kind of person you become."},"relearn":"Secret choices still matter; they shape who you are.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-935","type":"strike-rewrite","persona":"any","hook":"\"Being liked by everyone is the best way to choose.\"","myth":{"un":"The best choice is whatever keeps everyone liking you.","re":"Pleasing everyone can mean betraying yourself; choose by your values.","why":"You can't keep everyone happy, but you can stay true to yourself."},"relearn":"Don't choose just to be liked; choose by your values.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-936","type":"strike-rewrite","persona":"any","hook":"\"One small lie to fit in won't change who you are.\"","myth":{"un":"One small lie to fit in won't change who you are.","re":"Small choices add up and shape the kind of person you become.","why":"Honesty is built one choice at a time, including the small ones."},"relearn":"Small choices add up; honesty is built one at a time.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-937","type":"strike-rewrite","persona":"Aarav","hook":"\"Real strength is doing whatever the group dares you to.\"","myth":{"un":"Real strength is doing whatever the group dares you to.","re":"Real strength is choosing your own values, even under a dare.","why":"Going along is easy; standing on your own takes more nerve."},"relearn":"Strength is choosing your values, not following a dare.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-938","type":"strike-rewrite","persona":"any","hook":"\"Cheating is fine as long as you don't get caught.\"","myth":{"un":"Cheating is fine as long as you don't get caught.","re":"A score you didn't earn isn't really yours, caught or not.","why":"Cheating skips the learning and quietly chips at your honesty."},"relearn":"An unearned score isn't yours, caught or not.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-939","type":"strike-rewrite","persona":"any","hook":"\"If a value is hard to keep, it isn't worth keeping.\"","myth":{"un":"A value that's hard to keep isn't worth keeping.","re":"The values worth most are often the hardest to keep.","why":"Keeping a value when it's hard is exactly what makes it count."},"relearn":"Hard-to-keep values are often the ones worth most.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-940","type":"strike-rewrite","persona":"Rohit","hook":"\"Hide a values-based choice so no one argues with it.\"","myth":{"un":"You should hide a values-based choice to avoid arguments.","re":"You can calmly own a values choice: 'I'm doing what I think is right.'","why":"Owning your choice calmly earns more respect than hiding it."},"relearn":"You can calmly own a values choice without a fight.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-941","type":"match","persona":"any","hook":"Match each value to a choice that honours it.","pairs":[{"left":"Honesty","right":"Admitting you broke the vase"},{"left":"Kindness","right":"Sitting with the lonely kid"},{"left":"Fairness","right":"Letting everyone get a turn"},{"left":"Courage","right":"Speaking up when it's unpopular"},{"left":"Loyalty","right":"Standing by a friend who did the right thing"}],"relearn":"Your values point to choices that honour them.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-942","type":"match","persona":"any","hook":"Match the value to the choice that breaks it.","pairs":[{"left":"Honesty","right":"Copying someone's test answers"},{"left":"Kindness","right":"Sharing a mean meme"},{"left":"Fairness","right":"Hogging every turn"},{"left":"Respect","right":"Trolling a teacher online"},{"left":"Responsibility","right":"Blaming a friend for your slip"}],"relearn":"Naming the value a choice breaks helps you decide.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-943","type":"match","persona":"Diya","hook":"Match the values test to what it asks you.","pairs":[{"left":"The poster test","right":"Would I be glad this choice was mine?"},{"left":"The unseen test","right":"Would it still feel right if no one knew?"},{"left":"The respect test","right":"Could I explain it to someone I look up to?"},{"left":"The future test","right":"Would tomorrow-me thank me?"},{"left":"The crowd test","right":"Am I choosing, or just following along?"}],"relearn":"A few quick tests help check a choice against your values.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-944","type":"match","persona":"any","hook":"Match each value to a word that fits it.","pairs":[{"left":"Honesty","right":"Truthful"},{"left":"Kindness","right":"Caring"},{"left":"Fairness","right":"Even-handed"},{"left":"Courage","right":"Brave"},{"left":"Loyalty","right":"Dependable"}],"relearn":"Knowing what a value means makes it easier to choose by it.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-945","type":"match","persona":"any","hook":"Match the crossroads to the value it tests most.","pairs":[{"left":"Found money on the floor","right":"Honesty"},{"left":"A new kid eating alone","right":"Kindness"},{"left":"One turn left, two friends","right":"Fairness"},{"left":"A dare you don't agree with","right":"Courage"},{"left":"A promise you made earlier","right":"Loyalty"}],"relearn":"Spotting which value a choice tests guides your decision.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-946","type":"match","persona":"Rohit","hook":"Match the value-led line to the choice it owns.","pairs":[{"left":"\"I'd rather earn it.\"","right":"Studying instead of copying"},{"left":"\"That's not fair to him.\"","right":"Giving back the extra change"},{"left":"\"I won't pass that on.\"","right":"Refusing a cruel meme"},{"left":"\"I keep my word.\"","right":"Helping a cousin as promised"},{"left":"\"I'll include you.\"","right":"Inviting a left-out friend"}],"relearn":"A simple line can name the value behind your choice.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-947","type":"match","persona":"any","hook":"Match what people might offer to the value it asks you to trade.","pairs":[{"left":"\"Join us and you're in.\"","right":"Loyalty to an old friend"},{"left":"\"Just copy it, quick.\"","right":"Honesty"},{"left":"\"Share it, it's funny.\"","right":"Kindness"},{"left":"\"Skip your turn promise.\"","right":"Keeping your word"},{"left":"\"Everyone's leaving her out.\"","right":"Fairness"}],"relearn":"Spot the value a tempting offer asks you to trade away.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-948","type":"role-play","persona":"Aarav","hook":"The group is pushing you toward something that feels wrong.","setup":"Stand by your values. Say:","yourLine":[{"text":"\"I'm going to do what I think is right.\"","best":true},{"text":"\"Fine, whatever you all want.\""}],"relearn":"You can calmly stand by a values-based choice.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-949","type":"role-play","persona":"Diya","hook":"A friend asks you to lie for them so they look good.","setup":"Keep your honesty. Say:","yourLine":[{"text":"\"I can't lie about that, but I've still got you.\"","best":true},{"text":"\"Okay, I'll just say whatever you want.\""}],"relearn":"You can refuse to lie and still be a good friend.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-950","type":"role-play","persona":"any","hook":"Someone offers you answers to copy before a test.","setup":"Choose to earn it. Say:","yourLine":[{"text":"\"Thanks, but I'd rather do my own work.\"","best":true},{"text":"\"Sure, send them over.\""}],"relearn":"You can turn down cheating and earn your score honestly.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-951","type":"role-play","persona":"any","hook":"The group wants to leave one friend out of the plan.","setup":"Choose kindness out loud. Say:","yourLine":[{"text":"\"Let's include her too; it's not fair to leave her out.\"","best":true},{"text":"\"I guess, if that's what everyone wants.\""}],"relearn":"You can speak up to include someone left out.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-952","type":"role-play","persona":"Aarav","hook":"Friends laugh at you for not joining a cruel prank.","setup":"Own your choice. Say:","yourLine":[{"text":"\"Laugh if you want; I'm not in on this.\"","best":true},{"text":"\"Okay fine, I'll do it.\""}],"relearn":"You can own a values choice even when teased for it.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-953","type":"role-play","persona":"Rohit","hook":"You realise the change you got is more than it should be.","setup":"Choose fairness. Say:","yourLine":[{"text":"\"I think you gave me too much change.\"","best":true},{"text":"\"Cool, free money.\""}],"relearn":"You can speak up to return what isn't yours.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-954","type":"role-play","persona":"any","hook":"People ask you to explain why you won't go along with the crowd.","setup":"Explain calmly. Say:","yourLine":[{"text":"\"It just doesn't match what I think is right.\"","best":true},{"text":"\"No reason, I'll go along then.\""}],"relearn":"You can calmly explain a choice without a fight.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-955","type":"build","persona":"any","mode":"sequence","hook":"Build the steps for checking a choice against your values.","prompt":"Put the values-check steps in order.","pieces":["Name the value at stake","Picture who you want to be","Ask if you'd own it openly","Choose by that value"],"key":["Name the value at stake","Picture who you want to be","Ask if you'd own it openly","Choose by that value"],"relearn":"Name the value, picture yourself, check you'd own it, then choose.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-956","type":"build","persona":"Diya","mode":"assemble","hook":"Build a set of good 'is this right?' tests for a hard choice.","prompt":"Pick the questions that test a choice against your values.","pieces":["Would I own this openly?","Is it still right unseen?","Could I explain it to someone I respect?","Will it make me popular?","Does it match my values?"],"key":["Would I own this openly?","Is it still right unseen?","Could I explain it to someone I respect?","Does it match my values?"],"relearn":"Good values tests ask if you'd own it, not if it's popular.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-957","type":"build","persona":"any","mode":"assemble","hook":"Build a list of values that can guide a tough choice.","prompt":"Pick the values that can be a compass.","pieces":["Honesty","Kindness","Fairness","Courage","Getting the most likes"],"key":["Honesty","Kindness","Fairness","Courage"],"relearn":"Honesty, kindness, fairness and courage can guide a choice.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-958","type":"build","persona":"any","mode":"sequence","hook":"Build how to own a values choice out loud, step by step.","prompt":"Order the steps to stand by your choice calmly.","pieces":["Take a breath","Name what you'll do","Give your reason","Stay calm if they push"],"key":["Take a breath","Name what you'll do","Give your reason","Stay calm if they push"],"relearn":"Breathe, name your choice, give the reason, stay calm.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-959","type":"build","persona":"Aarav","mode":"assemble","hook":"Build reasons that make a choice right — drop the weak one.","prompt":"Pick the reasons that actually make a choice right.","pieces":["It matches my values","It's fair to others","I'd own it openly","Everyone else is doing it"],"key":["It matches my values","It's fair to others","I'd own it openly"],"relearn":"'Everyone's doing it' isn't a real reason a choice is right.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-960","type":"build","persona":"Rohit","mode":"assemble","hook":"Build the 'explain it to someone you respect' test kit.","prompt":"Pick what belongs in the respect test.","pieces":["Someone I look up to","An honest reason","A choice I'd own","A way to hide it"],"key":["Someone I look up to","An honest reason","A choice I'd own"],"relearn":"The respect test means an honest reason you'd happily own.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-961","type":"build","persona":"any","mode":"sequence","hook":"Build the path from temptation to a values-led choice.","prompt":"Order the steps when something tempting clashes with your values.","pieces":["Notice the uneasy feeling","Name the value it touches","Weigh it honestly","Choose your value"],"key":["Notice the uneasy feeling","Name the value it touches","Weigh it honestly","Choose your value"],"relearn":"Notice the unease, name the value, weigh it, choose it.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-962","type":"build","persona":"any","mode":"assemble","hook":"Build a kit of value-led lines you can use at a crossroads.","prompt":"Pick the lines that own a values choice.","pieces":["\"I'd rather earn it.\"","\"That's not fair to him.\"","\"I'm doing what's right.\"","\"Whatever you all say.\""],"key":["\"I'd rather earn it.\"","\"That's not fair to him.\"","\"I'm doing what's right.\""],"relearn":"Value-led lines own a choice instead of just going along.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-963","type":"sort","persona":"any","hook":"Sort each reason: a real reason to choose, or just crowd pressure?","bins":[{"id":"value","label":"A values reason","valence":"pos"},{"id":"crowd","label":"Just crowd pressure","valence":"neg"}],"items":[{"id":"a","text":"It's the fair thing to do"},{"id":"b","text":"Everyone else is doing it"},{"id":"c","text":"I'd be proud to own it"},{"id":"d","text":"They'll think I'm cool"},{"id":"e","text":"It's honest"},{"id":"f","text":"I don't want to look uncool"}],"key":{"a":"value","b":"crowd","c":"value","d":"crowd","e":"value","f":"crowd"},"relearn":"A values reason holds; 'everyone's doing it' is just pressure.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-964","type":"sort","persona":"Diya","hook":"Sort each choice: honours your values, or breaks them?","bins":[{"id":"honours","label":"Honours your values","valence":"pos"},{"id":"breaks","label":"Breaks your values","valence":"neg"}],"items":[{"id":"a","text":"Owning up to a mistake"},{"id":"b","text":"Copying a friend's answers"},{"id":"c","text":"Including a left-out kid"},{"id":"d","text":"Sharing a cruel meme"},{"id":"e","text":"Returning extra change"},{"id":"f","text":"Taking credit you didn't earn"}],"key":{"a":"honours","b":"breaks","c":"honours","d":"breaks","e":"honours","f":"breaks"},"relearn":"Some choices honour your values; others quietly break them.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-965","type":"sort","persona":"any","hook":"Sort each line: does it speak up for a value, or cave to the crowd?","bins":[{"id":"speak","label":"Speaks up for a value","valence":"tell"},{"id":"cave","label":"Caves to the crowd","valence":"neg"}],"items":[{"id":"a","text":"\"That's not fair to her.\""},{"id":"b","text":"\"Fine, whatever you all want.\""},{"id":"c","text":"\"I'd rather earn it.\""},{"id":"d","text":"\"I guess, if everyone's in.\""},{"id":"e","text":"\"Let's include him too.\""},{"id":"f","text":"\"Okay, I'll just go along.\""}],"key":{"a":"speak","b":"cave","c":"speak","d":"cave","e":"speak","f":"cave"},"relearn":"Some lines speak up for a value; others just cave.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-966","type":"sort","persona":"any","hook":"Sort each idea: true about values, or a busted myth?","bins":[{"id":"true","label":"True about values","valence":"pos"},{"id":"myth","label":"A busted myth","valence":"neg"}],"items":[{"id":"a","text":"Right matters even when unseen"},{"id":"b","text":"Popular always means right"},{"id":"c","text":"Decide for yourself, not the crowd"},{"id":"d","text":"A choice only counts if noticed"},{"id":"e","text":"Hard values are often worth most"},{"id":"f","text":"Standing by values is uncool"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Keep the true values ideas; drop the busted myths.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-967","type":"sort","persona":"Rohit","hook":"Sort each choice by which value it honours most.","bins":[{"id":"honest","label":"Honesty","valence":"neutral"},{"id":"fair","label":"Fairness","valence":"neutral"},{"id":"kind","label":"Kindness","valence":"neutral"}],"items":[{"id":"a","text":"Admitting you broke it"},{"id":"b","text":"Letting everyone get a turn"},{"id":"c","text":"Sitting with a lonely kid"},{"id":"d","text":"Telling the truth on a test"},{"id":"e","text":"Giving back extra change"},{"id":"f","text":"Comforting an upset friend"}],"key":{"a":"honest","b":"fair","c":"kind","d":"honest","e":"fair","f":"kind"},"relearn":"Each kind choice honours a value: honesty, fairness or kindness.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-968","type":"sort","persona":"any","hook":"Sort each pull: your values talking, or just wanting to be liked?","bins":[{"id":"values","label":"Your values talking","valence":"pos"},{"id":"liked","label":"Just wanting to be liked","valence":"uhoh"}],"items":[{"id":"a","text":"\"This wouldn't be fair.\""},{"id":"b","text":"\"They'll like me more if I do it.\""},{"id":"c","text":"\"I couldn't own this openly.\""},{"id":"d","text":"\"Everyone will think I'm cool.\""},{"id":"e","text":"\"This isn't honest.\""},{"id":"f","text":"\"I'll fit in if I join.\""}],"key":{"a":"values","b":"liked","c":"values","d":"liked","e":"values","f":"liked"},"relearn":"Tell your values apart from just wanting to be liked.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-969","type":"sort","persona":"any","hook":"Sort each test: a real values check, or not a real one?","bins":[{"id":"real","label":"A real values check","valence":"pos"},{"id":"notreal","label":"Not a real check","valence":"neg"}],"items":[{"id":"a","text":"Would I own this openly?"},{"id":"b","text":"Will it get me the most likes?"},{"id":"c","text":"Is it still right if unseen?"},{"id":"d","text":"Is everyone else doing it?"},{"id":"e","text":"Could I explain it to someone I respect?"},{"id":"f","text":"Will it look cool to the group?"}],"key":{"a":"real","b":"notreal","c":"real","d":"notreal","e":"real","f":"notreal"},"relearn":"Real values checks ask if you'd own it, not if it's popular.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-970","type":"sort","persona":"Aarav","hook":"Sort each move under a dare: keeps your values, or trades them away?","bins":[{"id":"keep","label":"Keeps your values","valence":"pos"},{"id":"trade","label":"Trades them away","valence":"neg"}],"items":[{"id":"a","text":"Saying 'I'm not in on this'"},{"id":"b","text":"Joining a cruel prank for laughs"},{"id":"c","text":"Refusing to copy on a test"},{"id":"d","text":"Skipping class on a dare"},{"id":"e","text":"Including a kid the group mocks"},{"id":"f","text":"Piling on someone online"}],"key":{"a":"keep","b":"trade","c":"keep","d":"trade","e":"keep","f":"trade"},"relearn":"Under a dare, some moves keep your values; others trade them.","cat":"decide-with-values","source":"decide-with-values"},
  {"id":"cr-990","type":"branch","options":[{"text":"Say you can't lie, but offer to help them study instead","consequence":"You stay a true friend without telling a lie for them.","outcome":"caring","best":true},{"text":"Lie to the teacher for them","consequence":"Covering a friend's lie isn't loyalty; it can land you both in trouble."}],"debrief":"Covering a lie isn't loyalty; honest care is.","cat":"friendship-crossroads","persona":"Diya","source":"loyalty vs right","relearn":"Helping a friend lie isn't real loyalty; care for them honestly.","hook":"A friend asks you to lie to the teacher that they were sick, so they skip the test."},
  {"id":"cr-991","type":"branch","options":[{"text":"Tell both you won't pick sides or pass messages","consequence":"You keep both friendships and stay out of their fight.","outcome":"wise","best":true},{"text":"Block whoever texts last","consequence":"Picking a side drags you into a fight that isn't yours."}],"debrief":"You can stay friends with both; you don't have to pick a side.","cat":"friendship-crossroads","persona":"Diya","source":"pick-a-side / third path","relearn":"You don't have to pick a side; stay kind to both and don't carry messages.","hook":"Two friends had a fight in class and each texts you to block the other."},
  {"id":"cr-992","type":"branch","options":[{"text":"Invite Meena along anyway","consequence":"You do the kind thing; sometimes others follow your lead.","outcome":"ally","best":true},{"text":"Stay quiet and go with the group","consequence":"Going along with leaving her out makes you part of it."}],"debrief":"You can choose to include someone, even when the group won't.","cat":"friendship-crossroads","persona":"any","source":"inclusion","relearn":"Including a left-out friend is a values choice you can make even alone.","hook":"At the chai stall after school, your group starts leaving Meena out of every plan."},
  {"id":"cr-993","type":"branch","options":[{"text":"Tell a trusted adult, even though you promised","consequence":"A grown-up can help stop it; their safety comes first.","outcome":"caring","best":true},{"text":"Keep the secret so they trust you","consequence":"A safety secret is the one you tell a trusted adult."}],"debrief":"A friend's safety beats a secret; tell a trusted adult.","cat":"friendship-crossroads","persona":"Asha","source":"safeguarding","relearn":"For a friend's safety, telling a trusted adult is the caring choice.","hook":"A friend says, in secret, they're being bullied online and makes you promise to tell no one."},
  {"id":"cr-994","type":"branch","options":[{"text":"Refuse: \"I'm with you, but I won't spread that\"","consequence":"You support your friend without hurting another person.","outcome":"caring","best":true},{"text":"Spread it to prove you're loyal","consequence":"Hurting someone to 'prove' loyalty harms three people at once."}],"debrief":"A real friend won't ask you to harm someone; you can say no.","cat":"friendship-crossroads","persona":"Diya","source":"cover-up / values","relearn":"Being a good friend doesn't mean doing something unkind for them.","hook":"Your best friend wants you to spread a rumour about a girl who 'wronged' her."},
  {"id":"cr-995","type":"branch","options":[{"text":"Say you'll hang out after, but you're not bunking","consequence":"You keep the friend AND your own line; a third path.","outcome":"creative","best":true},{"text":"Bunk so they don't drop you","consequence":"A friend who drops you for one 'no' was testing, not befriending."}],"debrief":"You can say no to a dare and still be a good friend.","cat":"friendship-crossroads","persona":"Aarav","source":"ultimatum / values","relearn":"You can refuse an ultimatum without losing yourself.","hook":"A friend dares you both to bunk tuition; if you don't, they say you're 'no fun anymore'."},
  {"id":"cr-996","type":"branch","options":[{"text":"Tell your friend to return it, or tell a trusted adult","consequence":"You give them a chance to fix it; you don't help hide it.","outcome":"caring","best":true},{"text":"Pretend you saw nothing","consequence":"Looking away makes you part of it and the other kid pays."}],"debrief":"Loyalty isn't covering a wrong; the kind move can be hard.","cat":"friendship-crossroads","persona":"any","source":"loyalty vs right","relearn":"Loyalty doesn't mean covering a wrong; caring can be the hard move.","hook":"You see your friend quietly take money from a classmate's bag."},
  {"id":"cr-997","type":"branch","options":[{"text":"Offer to help them make their own instead","consequence":"They learn something and you both stay honest.","outcome":"caring","best":true},{"text":"Let them copy yours","consequence":"Copying robs them of learning and risks you both getting caught."}],"debrief":"Helping a friend cheat isn't kindness; offering real help is.","cat":"friendship-crossroads","persona":"any","source":"honesty / friendship","relearn":"Real friends care for your wellbeing; helping them cheat helps no one.","hook":"Your friend wants to copy your project and pass it as their own for the class display."},
  {"id":"cr-998","type":"branch","options":[{"text":"Go sit with the new student anyway","consequence":"You make someone's hard day better; that's the real cool.","outcome":"ally","best":true},{"text":"Avoid them to stay in with the group","consequence":"Cool fades; how you treated someone alone is remembered."}],"debrief":"You can welcome a new kid even if the group calls it uncool.","cat":"friendship-crossroads","persona":"Diya","source":"inclusion / values","relearn":"Including someone is a values choice, even when the group teases you for it.","hook":"A new student sits alone; your friends say sitting with them makes you 'uncool'."},
  {"id":"cr-999","type":"branch","options":[{"text":"Tell your friend to stop, and don't like the memes","consequence":"You stay kind; your 'no' can make them rethink it.","outcome":"caring","best":true},{"text":"Like them so your friend isn't annoyed","consequence":"Liking a pile-on adds to the harm and signals it's okay."}],"debrief":"You don't have to join a friend's pile-on; you can say stop.","cat":"friendship-crossroads","persona":"any","source":"bystander / friendship","relearn":"You can refuse to join a friend in being unkind to someone else.","hook":"Your friend keeps sending a classmate cruel memes and wants you to like them."},
  {"id":"cr-1000","type":"branch","options":[{"text":"Refuse to delete it; suggest they own up instead","consequence":"You don't help a cover-up; owning up is the braver path.","outcome":"caring","best":true},{"text":"Delete it to protect them","consequence":"Helping hide it makes you part of the wrong and breaks trust."}],"debrief":"Hiding evidence for a friend isn't loyalty; honesty is.","cat":"friendship-crossroads","persona":"any","source":"cover-up / honesty","relearn":"Hiding a wrong for a friend isn't loyalty; honesty is.","hook":"A friend wants you to delete a chat that proves they teased someone."},
  {"id":"cr-1001","type":"branch","options":[{"text":"Be honest and split the day or join each for a while","consequence":"Both feel valued; you didn't have to rank a friendship.","outcome":"honest","best":true},{"text":"Secretly skip one and lie about why","consequence":"A lie to dodge it usually comes out and hurts more."}],"debrief":"Be honest and find a fair plan, don't pick a favourite.","cat":"friendship-crossroads","persona":"Diya","source":"third path / honesty","relearn":"Friend clashes have a fair third path, not a favourite to pick.","hook":"Two close friends have birthdays on the same day, each wanting you only at theirs."},
  {"id":"cr-1002","type":"branch","options":[{"text":"Say stop, don't send it, and tell a trusted adult","consequence":"You may have kept your friend safe from a real risk.","outcome":"caring","best":true},{"text":"Say 'your choice' and stay out of it","consequence":"A safety risk is the time to speak up, not stay neutral."}],"debrief":"Warn a friend off a risky move; tell a trusted adult.","cat":"friendship-crossroads","persona":"Asha","source":"safety / trusted adult","relearn":"If a friend's safety is at risk, the caring move is to speak up.","hook":"A friend is about to send their home address to a stranger in a game chat."},
  {"id":"cr-1003","type":"branch","options":[{"text":"Tell your friend you'd rather just own what you did","consequence":"You skip the revenge and keep your self-respect.","outcome":"accountable","best":true},{"text":"Join the plan to get back at the kid","consequence":"Revenge piles a second wrong on the first; it never clears it."}],"debrief":"Owning what you did beats ganging up on the reporter.","cat":"friendship-crossroads","persona":"Aarav","source":"accountability / friendship","relearn":"Real friends don't pull you into revenge; own your part.","hook":"Your friend wants to gang up on a kid who reported you both for a rule you broke."},
  {"id":"cr-1004","type":"branch","options":[{"text":"Say you won't unfollow; you can be friends with both","consequence":"You keep both and show a friend can't own your choices.","outcome":"wise","best":true},{"text":"Unfollow to keep the friend happy","consequence":"Doing a 'loyalty test' once invites the next, bigger one."}],"debrief":"You can refuse a loyalty test; you choose your friends.","cat":"friendship-crossroads","persona":"Diya","source":"ultimatum / autonomy","relearn":"You can refuse a loyalty test; you choose your own friends.","hook":"A friend pressures you to unfollow another friend to 'prove' you're on their side."},
  {"id":"cr-1005","type":"branch","options":[{"text":"Tell a trusted adult or call Childline 1098 now","consequence":"You get your friend real help; their safety beats a promise.","outcome":"caring","best":true},{"text":"Keep the promise and say nothing","consequence":"Some secrets are too heavy to hold alone; getting help is caring."}],"debrief":"A secret about real harm is one you tell a trusted adult.","cat":"friendship-crossroads","persona":"Asha","source":"safety overrides secret","relearn":"A safety secret is one you tell a trusted adult.","hook":"You promised to keep a friend's secret, but it's that they plan to hurt themselves."},
  {"id":"cr-1006","type":"branch","options":[{"text":"Say you're out of this game and change the subject","consequence":"You stop adding to it; others often quietly agree.","outcome":"caring","best":true},{"text":"Score her low so the group laughs","consequence":"A cheap laugh now is a memory she carries a long time."}],"debrief":"You can refuse to join a game that puts someone down.","cat":"friendship-crossroads","persona":"any","source":"peer pressure / kindness","relearn":"Going along with a cruel group game isn't loyalty; you can opt out.","hook":"Your group plays a 'rate everyone's looks' game and looks at you to score a quiet girl low."},
  {"id":"cr-1007","type":"branch","options":[{"text":"Tell the truth and ask your parents the real plan","consequence":"Honesty keeps you out of a tangle and they usually say yes.","outcome":"caring","best":true},{"text":"Lie so the plan works","consequence":"One lie needs another; the truth was simpler all along."}],"debrief":"You can include a friend without lying to your parents.","cat":"friendship-crossroads","persona":"any","source":"honesty / trusted adult","relearn":"You can care for a friend without lying to your own family.","hook":"A friend wants to come to your house but asks you to lie to your parents that it's for studies."},
  {"id":"cr-1008","type":"branch","options":[{"text":"Calmly tell them it hurt and ask them to take it down","consequence":"You name the boundary; a good friend will fix it.","outcome":"repair","best":true},{"text":"Post their private chat back to get even","consequence":"Getting even spreads the harm; it doesn't undo yours."}],"debrief":"You can name a crossed line and ask a friend to fix it.","cat":"friendship-crossroads","persona":"any","source":"repair / boundaries","relearn":"You can tell a friend they crossed a line and ask them to fix it.","hook":"Your friend posts your private chat to the class group as a 'joke'."},
  {"id":"cr-1009","type":"branch","options":[{"text":"Refuse to share it and don't pass it on","consequence":"You stop the chain; a cruel clip doesn't spread through you.","outcome":"caring","best":true},{"text":"Share it so the older friend likes you","consequence":"Spreading it hurts the target and your name is on the share."}],"debrief":"You can say no to spreading a cruel video, whoever asks.","cat":"friendship-crossroads","persona":"any","source":"values / online","relearn":"You can refuse to spread something cruel, whoever pushes.","hook":"An older friend keeps pushing you to share a cruel prank video so it spreads."},
  {"id":"cr-1010","type":"branch","options":[{"text":"Tell your friend you'll both own up honestly","consequence":"You stay fair; the cousin isn't punished for nothing.","outcome":"honest","best":true},{"text":"Let the cousin take the blame","consequence":"Letting someone innocent take the fall is a wrong you'd carry."}],"debrief":"Framing an innocent person is never the loyal choice.","cat":"friendship-crossroads","persona":"any","source":"honesty / fairness","relearn":"Blaming an innocent person to escape is never the loyal choice.","hook":"You and a friend both broke a vase at a relative's; the friend wants to blame a cousin."},
  {"id":"cr-1011","type":"branch","options":[{"text":"Stand with them; go to a trusted adult together if it keeps on","consequence":"Your friend isn't alone; together you can get help if needed.","outcome":"ally","best":true},{"text":"Stay back so you're not teased too","consequence":"Leaving a friend to face it alone is lonely for both."}],"debrief":"Being there for a teased friend is real friendship.","cat":"friendship-crossroads","persona":"Diya","source":"allyship","relearn":"Standing with a teased friend is a caring choice you can make.","hook":"Your friend is being teased and asks you to stand near so they're not alone."},
  {"id":"cr-1012","type":"branch","options":[{"text":"Say no to keeping watch and step away from the plan","consequence":"You don't get pulled into a wrong that wasn't yours.","outcome":"caring","best":true},{"text":"Keep watch so you're not the odd one out","consequence":"Keeping watch makes you part of the theft, not a bystander."}],"debrief":"You can refuse to be part of a plan that's clearly wrong.","cat":"friendship-crossroads","persona":"Aarav","source":"values / pressure","relearn":"A real friend won't ask you to help do wrong; you can refuse.","hook":"At a hangout, a kid plans to shoplift and a friend asks you to keep watch."},
  {"id":"cr-1013","type":"branch","options":[{"text":"Tell them you care for them AND can be civil to others","consequence":"You hold your ground kindly; a real friend comes around.","outcome":"values","best":true},{"text":"Be cold to the other person to win them back","consequence":"Being unkind on command trades your values for approval."}],"debrief":"You choose who you're kind to; a friend can't forbid it.","cat":"friendship-crossroads","persona":"Diya","source":"autonomy / friendship","relearn":"A friend doesn't get to pick who you're kind to.","hook":"A friend ignores you because you stayed kind to someone they fell out with."},
  {"id":"cr-1014","type":"strike-rewrite","myth":{"un":"True friends cover for you no matter what.","re":"Real friends care for your wellbeing, not just your wishes.","why":"Helping a friend do harm isn't loyalty."},"cat":"friendship-crossroads","persona":"any","source":"loyalty","relearn":"A real friend cares for the real you, not just for covering up.","hook":"\"A true friend covers for you, whatever you've done.\""},
  {"id":"cr-1015","type":"strike-rewrite","myth":{"un":"When friends fight, you must choose one of them.","re":"You can stay kind to both and refuse to carry messages.","why":"Picking sides drags you into a fight that isn't yours."},"cat":"friendship-crossroads","persona":"Diya","source":"third path","relearn":"You don't have to pick a side; a kind third path usually exists.","hook":"\"You always have to pick a side when friends fight.\""},
  {"id":"cr-1016","type":"strike-rewrite","myth":{"un":"Telling an adult about a friend's danger is betrayal.","re":"If a friend is unsafe, telling a trusted adult is the caring choice.","why":"Safety comes before a secret, even if the friend is upset."},"cat":"friendship-crossroads","persona":"Asha","source":"safety not snitching","relearn":"Telling a trusted adult to keep a friend safe is caring, not snitching.","hook":"\"Telling a grown-up when a friend's in danger is snitching.\""},
  {"id":"cr-1017","type":"strike-rewrite","myth":{"un":"Say no to a friend and you'll have no friends.","re":"You can refuse a 'pick me or them' ultimatum and still have friends.","why":"Real friendship survives a respectful 'no'."},"cat":"friendship-crossroads","persona":"any","source":"ultimatum","relearn":"A friend who drops you for one honest 'no' wasn't a real friend.","hook":"\"If you don't do what your friend says, you'll be alone.\""},
  {"id":"cr-1018","type":"strike-rewrite","myth":{"un":"If the group excludes someone, it's okay to join in.","re":"Popular and right aren't the same; you can choose to include.","why":"Going along with exclusion still hurts the person left out."},"cat":"friendship-crossroads","persona":"any","source":"inclusion","relearn":"Including a left-out kid is a values choice you can make alone.","hook":"\"Leaving someone out is fine if the whole group does it.\""},
  {"id":"cr-1019","type":"strike-rewrite","myth":{"un":"A good friend sorts every serious problem alone.","re":"Asking a trusted adult is part of helping a friend well.","why":"Some problems are too big to carry without help."},"cat":"friendship-crossroads","persona":"Asha","source":"ask an adult","relearn":"Getting a trusted adult for a serious problem is caring, not weak.","hook":"\"A good friend handles a serious problem all by themselves.\""},
  {"id":"cr-1020","type":"strike-rewrite","myth":{"un":"Refusing a friend's plan proves you don't care.","re":"Real care is about their wellbeing, not just agreeing.","why":"Sometimes the caring move is the harder, honest one."},"cat":"friendship-crossroads","persona":"Diya","source":"care vs compliance","relearn":"Caring for a friend can mean saying no to a plan that could hurt them.","hook":"\"Saying no to a friend's plan means you don't care about them.\""},
  {"id":"cr-1021","type":"reflect","prompt":"What do you think?","options":["Not really","A real friend respects me","Red flag"],"affirm":"A friend who respects your choices is the real kind.","cat":"friendship-crossroads","persona":"Diya","source":"autonomy","relearn":"Real friends respect your right to make your own choices.","hook":"Lensy: a friend who only likes you when you obey them, real friend?"},
  {"id":"cr-1022","type":"reflect","prompt":"Be honest.","options":["Saying no","Being left out","Both, honestly"],"affirm":"Knowing what's hard for you is the first step to handling it.","cat":"friendship-crossroads","persona":"any","source":"self-awareness","relearn":"Knowing your soft spot helps you stand by your values under pressure.","hook":"Lensy: which is harder for you, saying no to a friend or being left out?"},
  {"id":"cr-1023","type":"reflect","prompt":"What do you think?","options":["Yes, one or two","A few","I'm picturing them"],"affirm":"Those friends are keepers; honesty is safe with them.","cat":"friendship-crossroads","persona":"Diya","source":"real friendship","relearn":"Friends who accept your honest 'no' are the ones worth keeping.","hook":"Lensy: think of a friend who'd still like you after an honest 'no'. Got one?"},
  {"id":"cr-1024","type":"reflect","prompt":"What do you think?","options":["Safety wins","Tell a trusted adult","Their secret can wait"],"affirm":"Safety comes first; a trusted adult can help keep a friend safe.","cat":"friendship-crossroads","persona":"Asha","source":"safety first","relearn":"When safety's at stake, telling a trusted adult comes first.","hook":"Lensy: a friend's safety vs keeping their secret, which wins?"},
  {"id":"cr-1025","type":"reflect","prompt":"What do you think?","options":["Yes","It did","I want to more"],"affirm":"A kind third path often keeps everyone, and it's yours to find.","cat":"friendship-crossroads","persona":"any","source":"third path","relearn":"Looking for a kind third path is a friendship superpower.","hook":"Lensy: have you ever found a third path between two friends? Felt good?"},
  {"id":"cr-1026","type":"reflect","prompt":"What do you think?","options":["Brave","Small but big","Worth doing"],"affirm":"Small or brave, including someone is always a kind choice.","cat":"friendship-crossroads","persona":"any","source":"inclusion","relearn":"Including someone left out is a values choice, big or small.","hook":"Lensy: including the kid no one talks to, brave choice or small one?"},
  {"id":"cr-1027","type":"reflect","prompt":"What do you think?","options":["Happy and safe","Not just agreeing","My wellbeing"],"affirm":"Friends who want you safe, not just agreeable, are the real ones.","cat":"friendship-crossroads","persona":"Diya","source":"wellbeing vs wishes","relearn":"Real friends care for your wellbeing, not just your wishes.","hook":"Lensy: a real friend wants you happy AND safe, or just agreeing?"},
  {"id":"cr-1028","type":"reflect","prompt":"Pick one.","options":["A parent","A teacher","An elder cousin","Childline 1098"],"affirm":"Having someone in mind means you're ready if a friend needs help.","cat":"friendship-crossroads","persona":"Asha","source":"trusted adult","relearn":"Knowing your trusted adult ahead of time makes asking easier.","hook":"Lensy: who's a grown-up you'd tell if a friend was in real trouble?"},
  {"id":"cr-1029","type":"reflect","prompt":"What do you think?","options":["Strong","Self-respect","I can do it"],"affirm":"Refusing the ultimatum itself is the strong, free choice.","cat":"friendship-crossroads","persona":"any","source":"ultimatum","relearn":"Refusing an ultimatum is a strong, self-respecting choice.","hook":"Lensy: refusing a 'pick me or them' ultimatum, weak or strong?"},
  {"id":"cr-1030","type":"reflect","prompt":"Be honest.","options":["I'd notice","Maybe not","I'd want to know"],"affirm":"A friend who only likes you when you agree isn't really backing you.","cat":"friendship-crossroads","persona":"Diya","source":"autonomy","relearn":"Watch for friends who only stay happy when you do what they want.","hook":"Lensy: would you notice if a friend only stayed nice while you agreed with them?"},
  {"id":"cr-1031","type":"sort","items":[{"id":"a","text":"Telling a friend a hard truth kindly"},{"id":"b","text":"Helping a friend cheat"},{"id":"c","text":"Standing up for a friend"},{"id":"d","text":"Joining in to exclude someone"},{"id":"e","text":"Warning a friend off a risky plan"},{"id":"f","text":"Spreading a friend's secret"}],"bins":[{"id":"true","label":"True-friend move","valence":"pos"},{"id":"goalong","label":"Just going along","valence":"neg"}],"key":{"a":"true","b":"goalong","c":"true","d":"goalong","e":"true","f":"goalong"},"cat":"friendship-crossroads","persona":"any","source":"friendship / values","relearn":"True-friend moves care for people; go-along moves just avoid friction.","hook":"Sort: a true-friend move, or just going along?"},
  {"id":"cr-1032","type":"sort","items":[{"id":"a","text":"A surprise birthday plan"},{"id":"b","text":"A friend being bullied online"},{"id":"c","text":"Who has a crush on whom"},{"id":"d","text":"A friend planning to hurt themselves"},{"id":"e","text":"A nickname you made up"},{"id":"f","text":"A friend being touched in a way that scares them"}],"bins":[{"id":"keep","label":"Safe to keep","valence":"pos"},{"id":"tell","label":"Tell a trusted adult","valence":"tell"}],"key":{"a":"keep","b":"tell","c":"keep","d":"tell","e":"keep","f":"tell"},"cat":"friendship-crossroads","persona":"Asha","source":"safety vs secret","relearn":"Fun secrets you keep; safety secrets you tell a trusted adult.","hook":"Sort: a secret you keep, or one you tell a trusted adult?"},
  {"id":"cr-1033","type":"sort","items":[{"id":"a","text":"Helping a friend study for the test"},{"id":"b","text":"Lying so a friend skips trouble"},{"id":"c","text":"Telling a friend the truth gently"},{"id":"d","text":"Hiding what a friend did wrong"},{"id":"e","text":"Sticking up for a friend who's right"},{"id":"f","text":"Spreading a rumour for a friend"}],"bins":[{"id":"loyal","label":"Real loyalty","valence":"pos"},{"id":"cover","label":"Just covering up","valence":"neg"}],"key":{"a":"loyal","b":"cover","c":"loyal","d":"cover","e":"loyal","f":"cover"},"cat":"friendship-crossroads","persona":"any","source":"loyalty vs cover-up","relearn":"Real loyalty cares for a friend; covering up just hides a wrong.","hook":"Sort: shows real loyalty, or just covering up?"},
  {"id":"cr-1034","type":"sort","items":[{"id":"a","text":"Staying kind to both friends"},{"id":"b","text":"Blocking the friend they're mad at"},{"id":"c","text":"Refusing to carry messages"},{"id":"d","text":"Telling one friend the other's secret"},{"id":"e","text":"Saying 'I won't choose between you'"},{"id":"f","text":"Ganging up on one friend"}],"bins":[{"id":"third","label":"Kind third path","valence":"pos"},{"id":"side","label":"Picking a side","valence":"neg"}],"key":{"a":"third","b":"side","c":"third","d":"side","e":"third","f":"side"},"cat":"friendship-crossroads","persona":"Diya","source":"third path","relearn":"Third paths keep both friends; side-picking drops one.","hook":"Sort: a kind third path, or picking a side?"},
  {"id":"cr-1035","type":"sort","items":[{"id":"a","text":"Inviting the new kid to sit with you"},{"id":"b","text":"Making inside jokes to exclude"},{"id":"c","text":"Asking a quiet kid to join the game"},{"id":"d","text":"Whispering so someone feels left out"},{"id":"e","text":"Sharing your snack with someone alone"},{"id":"f","text":"Saving seats only for the 'in' group"}],"bins":[{"id":"in","label":"Includes them","valence":"pos"},{"id":"out","label":"Leaves them out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"cat":"friendship-crossroads","persona":"any","source":"inclusion","relearn":"Including welcomes people in; the others quietly push them out.","hook":"Sort: includes someone, or leaves them out?"},
  {"id":"cr-1036","type":"sort","items":[{"id":"a","text":"Respecting your 'no'"},{"id":"b","text":"Demanding you drop other friends"},{"id":"c","text":"Being happy you have other friends"},{"id":"d","text":"Giving you the silent treatment for saying no"},{"id":"e","text":"Cheering your own choices"},{"id":"f","text":"Testing your 'loyalty' with dares"}],"bins":[{"id":"real","label":"Real friend","valence":"pos"},{"id":"control","label":"Controlling","valence":"neg"}],"key":{"a":"real","b":"control","c":"real","d":"control","e":"real","f":"control"},"cat":"friendship-crossroads","persona":"Diya","source":"autonomy","relearn":"Real friends respect your choices; controlling ones try to own them.","hook":"Sort: a real friend's move, or a controlling one?"},
  {"id":"cr-1037","type":"sort","items":[{"id":"a","text":"Talking a friend out of a risky dare"},{"id":"b","text":"Lying to cover their mistake"},{"id":"c","text":"Getting help when they're unsafe"},{"id":"d","text":"Helping them get back at someone"},{"id":"e","text":"Telling them a hard truth kindly"},{"id":"f","text":"Doing their dare so they're not annoyed"}],"bins":[{"id":"well","label":"Their wellbeing","valence":"pos"},{"id":"wish","label":"Just their wishes","valence":"neg"}],"key":{"a":"well","b":"wish","c":"well","d":"wish","e":"well","f":"wish"},"cat":"friendship-crossroads","persona":"any","source":"wellbeing vs wishes","relearn":"Wellbeing cares about what's good for them; wishes are just what they want.","hook":"Sort: caring for a friend's wellbeing, or just their wishes?"},
  {"id":"cr-1038","type":"role-play","setup":"Refuse the ultimatum. Say:","yourLine":[{"text":"\"I'm not going to choose; I can be friends with both of you.\"","best":true},{"text":"\"Okay, fine, I'll drop them.\""}],"cat":"friendship-crossroads","persona":"Diya","source":"ultimatum / voice","relearn":"You can refuse a 'pick me or them' ultimatum.","hook":"A friend pressures you to drop another friend or you're 'out'."},
  {"id":"cr-1039","type":"role-play","setup":"Stay honest but kind. Say:","yourLine":[{"text":"\"I can't lie for you, but I'll help you tell them yourself.\"","best":true},{"text":"\"Sure, I'll say whatever you want.\""}],"cat":"friendship-crossroads","persona":"any","source":"honesty / voice","relearn":"You can care for a friend without telling lies for them.","hook":"A friend asks you to lie to their parents about where they really went."},
  {"id":"cr-1040","type":"role-play","setup":"Be honestly caring. Say:","yourLine":[{"text":"\"As your friend, I don't think that's safe, here's why.\"","best":true},{"text":"\"Whatever, do what you want.\""}],"cat":"friendship-crossroads","persona":"Asha","source":"honest care / voice","relearn":"A caring friend shares honest concern about a risky choice.","hook":"Your friend's heading into something risky and asks what you really think."},
  {"id":"cr-1041","type":"role-play","setup":"Opt out kindly. Say:","yourLine":[{"text":"\"I'm not into this, let's just leave them alone.\"","best":true},{"text":"\"Haha yeah, good one.\""}],"cat":"friendship-crossroads","persona":"any","source":"bystander / voice","relearn":"You can refuse to join in mockery.","hook":"The group is mocking a classmate and turns to you to join in."},
  {"id":"cr-1042","type":"role-play","setup":"Refuse clearly. Say:","yourLine":[{"text":"\"No, I'm not doing that, and I think you shouldn't either.\"","best":true},{"text":"\"Um, okay, I guess I'll watch.\""}],"cat":"friendship-crossroads","persona":"Aarav","source":"values / voice","relearn":"You can refuse to be part of a plan that's wrong.","hook":"A friend wants you to keep watch while they take something that isn't theirs."},
  {"id":"cr-1043","type":"role-play","setup":"Welcome them. Say:","yourLine":[{"text":"\"Hey, come sit with us, there's space.\"","best":true},{"text":"\"Better not, the others will tease me.\""}],"cat":"friendship-crossroads","persona":"Diya","source":"inclusion / voice","relearn":"You can welcome someone in, even if the group teases you.","hook":"A new kid is sitting alone and your friends say not to bother."},
  {"id":"cr-1044","type":"role-play","setup":"Be caring and honest. Say:","yourLine":[{"text":"\"I care too much to keep this secret, let's tell someone who can help.\"","best":true},{"text":"\"Okay, I won't tell anyone, ever.\""}],"cat":"friendship-crossroads","persona":"Asha","source":"safety / voice","relearn":"You can gently tell a friend you need to get them help.","hook":"A friend told you something heavy that's about their safety."},
  {"id":"cr-1045","type":"build","prompt":"Pick the marks of a real friend.","pieces":["respects your 'no'","wants you safe","is honest with you","cheers your other friends","makes you choose sides","tells you to lie for them"],"mode":"assemble","key":["respects your 'no'","wants you safe","is honest with you","cheers your other friends"],"cat":"friendship-crossroads","persona":"any","source":"real friendship","relearn":"A real friend respects your no, wants you safe, and is honest with you.","hook":"Build: what makes a real friend?"},
  {"id":"cr-1046","type":"build","prompt":"Order the steps.","pieces":["stay calm","tell your friend you care","tell a trusted adult","let an adult help"],"mode":"sequence","key":["stay calm","tell your friend you care","tell a trusted adult","let an adult help"],"cat":"friendship-crossroads","persona":"Asha","source":"safety routine","relearn":"Stay calm, tell them you care, then tell a trusted adult.","hook":"Build: your steps when a friend is unsafe."},
  {"id":"cr-1047","type":"build","prompt":"Pick the third-path moves.","pieces":["stay kind to both","don't carry messages","don't pick a side","let them sort their own fight","block one of them","spread what each said"],"mode":"assemble","key":["stay kind to both","don't carry messages","don't pick a side","let them sort their own fight"],"cat":"friendship-crossroads","persona":"Diya","source":"third path","relearn":"Stay kind to both, don't carry messages, and don't pick a side.","hook":"Build: how to handle two friends fighting."},
  {"id":"cr-1048","type":"build","prompt":"Order the steps.","pieces":["take a breath","say you won't choose","offer to be friends with both","let them cool off"],"mode":"sequence","key":["take a breath","say you won't choose","offer to be friends with both","let them cool off"],"cat":"friendship-crossroads","persona":"any","source":"ultimatum","relearn":"Stay calm, say you won't choose, and offer to stay friends with both.","hook":"Build: how to refuse an ultimatum kindly."},
  {"id":"cr-1049","type":"build","prompt":"Pick the including moves.","pieces":["invite them to sit","ask them to join the game","share your snack","learn their name","make jokes they can't get","save seats only for friends"],"mode":"assemble","key":["invite them to sit","ask them to join the game","share your snack","learn their name"],"cat":"friendship-crossroads","persona":"any","source":"inclusion","relearn":"Invite them over, ask them to join, share, and learn their name.","hook":"Build: ways to include a left-out kid."},
  {"id":"cr-1050","type":"build","prompt":"Order the steps.","pieces":["own what you did","say a real sorry","ask how to fix it","do better next time"],"mode":"sequence","key":["own what you did","say a real sorry","ask how to fix it","do better next time"],"cat":"friendship-crossroads","persona":"any","source":"repair","relearn":"Own it, say a real sorry, ask how to fix it, then change.","hook":"Build: how to repair after you hurt a friend."},
  {"id":"cr-1051","type":"build","prompt":"Pick the controlling signs.","pieces":["makes you pick sides","tells you to drop others","tests your loyalty","guilts you for saying no","is glad you have other friends","respects your choices"],"mode":"assemble","key":["makes you pick sides","tells you to drop others","tests your loyalty","guilts you for saying no"],"cat":"friendship-crossroads","persona":"Diya","source":"autonomy","relearn":"They make you pick sides, drop others, prove loyalty, or guilt your 'no'.","hook":"Build: signs a 'friend' is really controlling you."},
  {"id":"cr-1052","type":"build","prompt":"Order the steps.","pieces":["pause and think","look for a third path","weigh who's affected","choose by your values"],"mode":"sequence","key":["pause and think","look for a third path","weigh who's affected","choose by your values"],"cat":"friendship-crossroads","persona":"any","source":"decision routine","relearn":"Pause, look for a third path, weigh who's affected, then choose by your values.","hook":"Build: how to decide a tricky friend dilemma."},
  {"id":"cr-1053","type":"match","pairs":[{"left":"Two friends fighting","right":"Stay kind to both, no message-carrying"},{"left":"Friend asks you to lie","right":"Offer to help them tell the truth"},{"left":"Group leaving someone out","right":"Invite that person along"},{"left":"Friend is unsafe","right":"Tell a trusted adult"},{"left":"Asked to pick a side","right":"Say you won't choose"}],"cat":"friendship-crossroads","persona":"Diya","source":"third path","relearn":"Most friend dilemmas have a kind third path.","hook":"Match the friend dilemma to a caring third path."},
  {"id":"cr-1054","type":"match","pairs":[{"left":"A friend is being hurt online","right":"A trusted adult"},{"left":"A friend planning to hurt themselves","right":"A trusted adult (or Childline 1098)"},{"left":"A small fight between friends","right":"The two of you talking"},{"left":"Choosing a weekend plan","right":"You and your friend together"},{"left":"A scary secret too big to hold","right":"A trusted grown-up"}],"cat":"friendship-crossroads","persona":"Asha","source":"trusted adult / help","relearn":"Match each problem to the right helper.","hook":"Match the situation to who can best help."},
  {"id":"cr-1055","type":"match","pairs":[{"left":"Telling a hard truth kindly","right":"A caring friend"},{"left":"Helping a friend cheat","right":"Not real help"},{"left":"Including a left-out kid","right":"A kind friend"},{"left":"Covering up a wrong","right":"A false loyalty"},{"left":"Standing with a teased friend","right":"A brave friend"}],"cat":"friendship-crossroads","persona":"any","source":"loyalty vs right","relearn":"Each choice shows the kind of friend you are.","hook":"Match the choice to what kind of friend it shows."},
  {"id":"cr-1056","type":"match","pairs":[{"left":"\"Lie for me\"","right":"\"I can't lie, but I'll help another way\""},{"left":"\"Pick me or them\"","right":"\"I won't choose; I like you both\""},{"left":"\"Spread this rumour\"","right":"\"I'm with you, but I won't spread that\""},{"left":"\"Keep my safety secret\"","right":"\"I care too much, let's get help\""},{"left":"\"Skip class with me\"","right":"\"Let's hang out after instead\""}],"cat":"friendship-crossroads","persona":"any","source":"saying no / voice","relearn":"You can answer a hard request kindly and honestly.","hook":"Match the friend's request to a kind, honest reply."},
  {"id":"cr-1057","type":"match","pairs":[{"left":"Honesty","right":"Telling a friend the truth gently"},{"left":"Loyalty done right","right":"Caring for a friend's wellbeing"},{"left":"Kindness","right":"Including someone left out"},{"left":"Courage","right":"Standing up for a teased friend"},{"left":"Respect","right":"Accepting a friend's 'no'"}],"cat":"friendship-crossroads","persona":"any","source":"values","relearn":"Your values point to choices that honour them.","hook":"Match the value to a friendship choice that honours it."},
  {"id":"cr-1058","type":"match","pairs":[{"left":"Respects your no","right":"Guilts you for saying no"},{"left":"Glad you have other friends","right":"Makes you drop them"},{"left":"Honest with you","right":"Asks you to lie"},{"left":"Wants you safe","right":"Pushes risky dares"},{"left":"Lets you choose","right":"Tests your loyalty"}],"cat":"friendship-crossroads","persona":"Diya","source":"real vs controlling","relearn":"Real-friend signs have a controlling opposite.","hook":"Match the 'real friend' sign to its opposite."},
  {"id":"cr-1059","type":"match","pairs":[{"left":"A surprise gift plan","right":"Keep it, it's a happy surprise"},{"left":"A friend being bullied","right":"Tell a trusted adult"},{"left":"A made-up nickname","right":"Keep it, it's just for fun"},{"left":"A plan to self-harm","right":"Tell a trusted adult right now"},{"left":"Who has a crush on whom","right":"Keep it, it's private and harmless"}],"cat":"friendship-crossroads","persona":"Asha","source":"safety vs secret","relearn":"Fun secrets you keep; safety secrets you tell a trusted adult.","hook":"Match the secret to the right next step."},
  {"id":"cr-1060","type":"match","pairs":[{"left":"Friend wants to cheat off you","right":"Offer to help them learn"},{"left":"Friend posts your private chat","right":"Ask them to take it down"},{"left":"Friend mocks a classmate","right":"Say stop and don't join"},{"left":"New kid sits alone","right":"Invite them over"},{"left":"Friend in real danger","right":"Get a trusted adult"}],"cat":"friendship-crossroads","persona":"any","source":"friendship crossroads","relearn":"Each crossroads has a caring move.","hook":"Match the friend crossroads to the caring move."},
  {"id":"cr-1080","cat":"own-your-choice","type":"branch","hook":"You broke your sister's clay diya by accident, and no one saw.","options":[{"text":"Tell her yourself and offer to help remake it","consequence":"She's a bit sad but trusts you more for owning it.","outcome":"honest","best":true},{"text":"Quietly hide the pieces and say nothing","consequence":"Hiding it grows a knot in your stomach; owning it is lighter."}],"debrief":"Owning a mistake yourself beats waiting to be found out.","relearn":"Own a mistake yourself instead of hiding it.","persona":"Diya","source":"accountability"},
  {"id":"cr-1081","cat":"own-your-choice","type":"branch","hook":"You spent your tuition saved-up money on a game you regret buying.","options":[{"text":"Admit it to yourself and plan to save again","consequence":"You feel okay; one money mistake becomes a lesson.","outcome":"growth","best":true},{"text":"Tell yourself you're hopeless with money","consequence":"One slip doesn't define you; a plan does more than self-blame."}],"debrief":"A money slip is a lesson, not proof you're hopeless.","relearn":"A money mistake is a lesson; make a plan, don't beat yourself up.","persona":"any","source":"self-compassion / money"},
  {"id":"cr-1082","cat":"own-your-choice","type":"branch","hook":"You snapped at your friend over a misunderstanding on the bus.","options":[{"text":"Go back and say 'I was wrong to snap, sorry'","consequence":"The friendship repairs faster than you feared.","outcome":"repair","best":true},{"text":"Decide it's too late to fix now","consequence":"It's rarely too late; a simple sorry can still mend it."}],"debrief":"Owning a snap and apologising can repair things fast.","relearn":"It's not too late to own a snap and apologise.","persona":"Aarav","source":"repair / accountability"},
  {"id":"cr-1083","cat":"own-your-choice","type":"branch","hook":"A big choice about switching tuition centres has you stuck and scared.","options":[{"text":"Ask your dad to talk it through with you","consequence":"A calm outside view makes the choice clearer.","outcome":"resourceful","best":true},{"text":"Keep worrying about it alone all week","consequence":"Asking a trusted adult beats stewing on a big call alone."}],"debrief":"For a big choice, asking a trusted adult is smart, not weak.","relearn":"For big choices, ask a trusted adult instead of stewing alone.","persona":"Rohit","source":"help-seeking"},
  {"id":"cr-1084","cat":"own-your-choice","type":"branch","hook":"You chose a group project topic that's flopping; the team's frustrated.","options":[{"text":"Own it and suggest pivoting to a better topic","consequence":"The team resets and the project gets back on track.","outcome":"growth","best":true},{"text":"Insist on sticking with it to avoid admitting it","consequence":"Owning the call and changing course beats saving face."}],"debrief":"You can own a choice that isn't working and change course.","relearn":"Own a choice that isn't working and change course.","persona":"any","source":"flexibility / accountability"},
  {"id":"cr-1085","cat":"own-your-choice","type":"branch","hook":"You forgot to pass on a message and a friend missed the cricket match.","options":[{"text":"Say 'that was on me, I forgot, I'm sorry'","consequence":"They're let down but respect that you owned it.","outcome":"honest","best":true},{"text":"Blame the bad network for the missed message","consequence":"Owning your part keeps trust; a fake excuse chips it."}],"debrief":"Owning your part beats inventing an excuse.","relearn":"Own your part instead of inventing an excuse.","persona":"any","source":"accountability"},
  {"id":"cr-1086","cat":"own-your-choice","type":"branch","hook":"You teased a quiet classmate for a laugh and now feel awful.","options":[{"text":"Apologise privately and mean it","consequence":"They feel seen; you act like the person you want to be.","outcome":"repair","best":true},{"text":"Hope they just forget about it","consequence":"A real apology repairs more than hoping it fades."}],"debrief":"A choice that hurt someone can be owned and repaired.","relearn":"If a choice hurt someone, own it and apologise for real.","persona":"Diya","source":"repair"},
  {"id":"cr-1087","cat":"own-your-choice","type":"branch","hook":"You lied to skip a family function and got caught out.","options":[{"text":"Admit the lie and explain why honestly","consequence":"It's awkward, but trust starts rebuilding.","outcome":"honest","best":true},{"text":"Double down with a second lie","consequence":"A second lie digs deeper; owning the first one ends it."}],"debrief":"Owning a lie ends it; doubling down digs deeper.","relearn":"Own a lie rather than covering it with another.","persona":"any","source":"honesty / accountability"},
  {"id":"cr-1088","cat":"own-your-choice","type":"branch","hook":"You're torn between two coaching options and can't decide alone.","options":[{"text":"Ask Asha, your near-peer mentor, to help you weigh it","consequence":"Talking it out helps you see the choice clearly.","outcome":"resourceful","best":true},{"text":"Flip a coin and hope for the best","consequence":"For a real choice, a trusted person's view beats a coin flip."}],"debrief":"Asking someone you trust beats leaving a real choice to chance.","relearn":"For a real choice, ask someone you trust, don't leave it to chance.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1089","cat":"own-your-choice","type":"branch","hook":"Your harsh online comment upset a classmate; you regret posting it.","options":[{"text":"Delete it and message a genuine sorry","consequence":"You limit the harm and own what you posted.","outcome":"repair","best":true},{"text":"Leave it up and pretend it's no big deal","consequence":"Owning and undoing it beats pretending it didn't land."}],"debrief":"You can own an online choice, delete it, and make it right.","relearn":"Own a regretted post: delete it and apologise.","persona":"any","source":"accountability / online"},
  {"id":"cr-1090","cat":"own-your-choice","type":"branch","hook":"You broke a promise to study with a friend because you got busy.","options":[{"text":"Own it, apologise, and reschedule","consequence":"They feel respected and the plan still happens.","outcome":"honest","best":true},{"text":"Avoid them so you don't have to explain","consequence":"Owning it and rescheduling beats avoiding them."}],"debrief":"Own a broken promise and make a new plan.","relearn":"Own a broken promise and offer to make it right.","persona":"any","source":"accountability"},
  {"id":"cr-1091","cat":"own-your-choice","type":"branch","hook":"You picked the easy elective, then realised you actually wanted the other.","options":[{"text":"Ask the teacher calmly if you can still switch","consequence":"You may switch; either way you owned the choice.","outcome":"growth","best":true},{"text":"Sulk about it and blame your friend's advice","consequence":"You chose it; own it and act, don't blame the adviser."}],"debrief":"You chose, even on advice, so own it and try to fix it.","relearn":"Even a choice made on advice is yours to own and fix.","persona":"any","source":"accountability"},
  {"id":"cr-1092","cat":"own-your-choice","type":"branch","hook":"You realise mid-week you made the wrong call quitting the art club.","options":[{"text":"Own it and ask to rejoin","consequence":"Changing your mind is allowed; you go back happily.","outcome":"growth","best":true},{"text":"Stay out just to seem decisive","consequence":"Changing course on a wrong call is smarter than seeming decisive."}],"debrief":"Changing course when a choice was wrong is strength, not weakness.","relearn":"You can change course on a choice that turned out wrong.","persona":"any","source":"flexibility"},
  {"id":"cr-1093","cat":"own-your-choice","type":"branch","hook":"You and a friend both chose to bunk practice; the coach is upset.","options":[{"text":"Own your share without throwing your friend under","consequence":"You're fair and the coach respects the honesty.","outcome":"accountable","best":true},{"text":"Say it was all your friend's idea","consequence":"Owning your share is fairer than pinning it all on a friend."}],"debrief":"Own your share of a shared choice; don't scapegoat a friend.","relearn":"Own your share of a shared choice; don't scapegoat.","persona":"Aarav","source":"accountability"},
  {"id":"cr-1094","cat":"own-your-choice","type":"branch","hook":"A confusing choice about a friend's secret feels too big to handle alone.","options":[{"text":"Talk it through with a trusted adult","consequence":"A wise grown-up helps you find the right path.","outcome":"resourceful","best":true},{"text":"Carry the whole thing by yourself silently","consequence":"A too-big choice is a cue to ask a trusted adult."}],"debrief":"For a choice that feels too big, ask a trusted grown-up.","relearn":"A choice that feels too big is a cue to ask a trusted adult.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1095","cat":"own-your-choice","type":"strike-rewrite","hook":"\"One bad choice and you've ruined everything for good.\"","myth":{"un":"One bad choice ruins everything forever.","re":"You can own it, change course, and learn from a bad call.","why":"A decision isn't a life sentence; most can be repaired."},"relearn":"A bad choice isn't forever; you can change course and learn.","persona":"any","source":"growth mindset"},
  {"id":"cr-1096","cat":"own-your-choice","type":"strike-rewrite","hook":"\"Saying sorry for a choice makes you look weak.\"","myth":{"un":"Apologising for a choice makes you look weak.","re":"Owning a choice and apologising shows real strength.","why":"It takes courage to admit a mistake and make it right."},"relearn":"Owning a choice and apologising is strength, not weakness.","persona":"Aarav","source":"accountability"},
  {"id":"cr-1097","cat":"own-your-choice","type":"strike-rewrite","hook":"\"Asking an adult for advice means you can't decide yourself.\"","myth":{"un":"Asking an adult for advice means you can't decide.","re":"Asking a trusted adult is a smart, resourceful part of deciding.","why":"Good deciders gather advice, then choose for themselves."},"relearn":"Asking a trusted adult for advice is smart deciding, not weakness.","persona":"Rohit","source":"help-seeking"},
  {"id":"cr-1098","cat":"own-your-choice","type":"strike-rewrite","hook":"\"If a choice goes wrong, it's always someone else's fault.\"","myth":{"un":"When a choice goes wrong it's always someone else's fault.","re":"Owning your part of a choice is how your judgement grows.","why":"Blaming others skips the learning that makes you better."},"relearn":"Own your part of a choice; blaming others skips the lesson.","persona":"any","source":"accountability"},
  {"id":"cr-1099","cat":"own-your-choice","type":"strike-rewrite","hook":"\"Once you've decided, changing your mind makes you a flake.\"","myth":{"un":"Changing your mind after deciding makes you a flake.","re":"Changing course when a choice isn't working is wise.","why":"New information can rightly change a good decision."},"relearn":"Changing course on a choice that isn't working is wise.","persona":"any","source":"flexibility"},
  {"id":"cr-1100","cat":"own-your-choice","type":"strike-rewrite","hook":"\"A mistake means you're just bad at making choices.\"","myth":{"un":"A mistake proves you're bad at making choices.","re":"Everyone makes some bad calls; practice builds good deciding.","why":"Judgement grows from owning mistakes, not from never making any."},"relearn":"A mistake doesn't make you a bad decider; learning sharpens you.","persona":"any","source":"growth mindset"},
  {"id":"cr-1101","cat":"own-your-choice","type":"strike-rewrite","hook":"\"Owning up only matters if you got caught.\"","myth":{"un":"Owning up to a choice only matters if you got caught.","re":"Owning a choice is right even when no one would ever know.","why":"Taking responsibility is for you, not just for an audience."},"relearn":"Owning a choice matters even when no one would ever find out.","persona":"any","source":"integrity / accountability"},
  {"id":"cr-1102","cat":"own-your-choice","type":"reflect","hook":"Lensy: owning a choice means you get to learn from it. Like that idea?","prompt":"What do you think?","options":["Yes","I'd rather learn","Makes sense"],"affirm":"Owning a choice turns even a wrong one into something you learn from.","relearn":"Owning a choice lets you learn from it.","persona":"any","source":"growth"},
  {"id":"cr-1103","cat":"own-your-choice","type":"reflect","hook":"Lensy: when a choice flops, is it kinder to blame yourself or learn from it?","prompt":"What feels right?","options":["Learn from it","Be kind to myself","Both"],"affirm":"Being kind to yourself and learning beats harsh self-blame every time.","relearn":"Be kind to yourself and learn, rather than harshly self-blaming.","persona":"any","source":"self-compassion"},
  {"id":"cr-1104","cat":"own-your-choice","type":"reflect","hook":"Lensy: it's okay to ask a grown-up's advice on a big call. How does that feel?","prompt":"What do you think?","options":["A relief","Smart","I'll ask next time"],"affirm":"Asking a trusted adult on a big choice is smart and brave.","relearn":"Asking a trusted adult for advice on a big choice is smart.","persona":"Rohit","source":"help-seeking"},
  {"id":"cr-1105","cat":"own-your-choice","type":"reflect","hook":"Lensy: a choice that goes wrong doesn't make you a bad person. Believe it?","prompt":"What do you think?","options":["Yes","I'm still learning","Good to hear"],"affirm":"A choice gone wrong doesn't make you bad, it makes you human and learning.","relearn":"A choice that goes wrong doesn't make you a bad person.","persona":"any","source":"self-compassion"},
  {"id":"cr-1106","cat":"own-your-choice","type":"reflect","hook":"Lensy: you can change course if a choice stops working. Useful to know?","prompt":"What do you think?","options":["Yes","I can adjust","Reassuring"],"affirm":"You're never locked in; you can change course when a choice isn't working.","relearn":"You can change course when a choice isn't working out.","persona":"any","source":"flexibility"},
  {"id":"cr-1107","cat":"own-your-choice","type":"reflect","hook":"Lensy: what's one choice you owned recently and felt good about?","prompt":"Think of one.","options":["An honest one","A brave one","A kind one"],"affirm":"Hold onto that feeling, owning your choices builds real confidence.","relearn":"Noticing choices you owned well builds confidence.","persona":"any","source":"self-efficacy"},
  {"id":"cr-1108","cat":"own-your-choice","type":"reflect","hook":"Lensy: after a tough call, asking 'what would I do differently?' helps. Try it?","prompt":"What do you think?","options":["Yes","Good question","I'll use it"],"affirm":"'What would I do differently?' turns any choice into a lesson for next time.","relearn":"Ask 'what would I do differently?' to learn from a choice.","persona":"any","source":"reflection"},
  {"id":"cr-1109","cat":"own-your-choice","type":"reflect","hook":"Lensy: owning your choices is part of growing up. Feel ready for that?","prompt":"What do you think?","options":["Yes","Getting there","I want to"],"affirm":"Owning your choices, bit by bit, is exactly how you grow up well.","relearn":"Owning your choices is part of growing up.","persona":"any","source":"agency"},
  {"id":"cr-1110","cat":"own-your-choice","type":"reflect","hook":"Lensy: when you mess up, do you forgive yourself as you would a friend?","prompt":"Be honest.","options":["I try","Not always","I will more"],"affirm":"Treat yourself as kindly as you'd treat a friend who slipped up.","relearn":"Forgive yourself for a slip as kindly as you would a friend.","persona":"Diya","source":"self-compassion"},
  {"id":"cr-1111","cat":"own-your-choice","type":"reflect","hook":"Lensy: a wrong call you own teaches you more than a lucky right one. See why?","prompt":"What do you think?","options":["Yes","Owned ones stick","Interesting"],"affirm":"An owned mistake teaches more than a lucky win you didn't think about.","relearn":"An owned mistake teaches more than a lucky win.","persona":"any","source":"growth"},
  {"id":"cr-1112","cat":"own-your-choice","type":"reflect","hook":"Lensy: who's a trusted grown-up you'd ask about a hard choice?","prompt":"Picture them.","options":["A parent","A teacher","An older cousin","Asha-type mentor"],"affirm":"Knowing who you'd ask makes a hard choice feel less heavy.","relearn":"Know which trusted adult you'd ask about a hard choice.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1113","cat":"own-your-choice","type":"reflect","hook":"Lensy: owning a choice means saying 'that was mine'. Comfortable with that?","prompt":"What do you think?","options":["Yes","Getting there","I'll practise"],"affirm":"Saying 'that was my choice' is a brave, grown-up thing to do.","relearn":"Owning a choice means saying 'that was mine'.","persona":"any","source":"accountability"},
  {"id":"cr-1114","cat":"own-your-choice","type":"reflect","hook":"Lensy: do you let one bad call ruin your whole day, or move on?","prompt":"Be honest.","options":["I move on","Sometimes it sticks","I'll let go faster"],"affirm":"One bad call is just one moment; you can learn and move forward.","relearn":"One bad call needn't ruin everything; learn and move on.","persona":"any","source":"self-compassion"},
  {"id":"cr-1115","cat":"own-your-choice","type":"reflect","hook":"Lensy: when you own a choice, does blaming others stop feeling tempting?","prompt":"What do you think?","options":["Yes","A bit","I notice the urge"],"affirm":"Owning your part quietly removes the urge to blame everyone else.","relearn":"Owning your part removes the urge to blame others.","persona":"any","source":"accountability"},
  {"id":"cr-1116","cat":"own-your-choice","type":"reflect","hook":"Lensy: 'I got that wrong' is a hard sentence to say. Worth practising?","prompt":"What do you think?","options":["Yes","It's brave","I'll try"],"affirm":"Practising 'I got that wrong' makes owning real mistakes far easier.","relearn":"Practising 'I got that wrong' makes owning mistakes easier.","persona":"Aarav","source":"accountability"},
  {"id":"cr-1117","cat":"own-your-choice","type":"reflect","hook":"Lensy: every choice you own adds to your judgement. Feel it building?","prompt":"What do you think?","options":["Yes","Slowly","I'm learning"],"affirm":"Each owned choice quietly sharpens the judgement you'll use next time.","relearn":"Each owned choice sharpens your judgement over time.","persona":"any","source":"growth"},
  {"id":"cr-1118","cat":"own-your-choice","type":"reflect","hook":"Lensy: is asking for help on a big choice a sign of strength or weakness?","prompt":"What do you think?","options":["Strength","Both","Strength, mostly"],"affirm":"Reaching out on a big choice takes strength, not weakness.","relearn":"Asking for help on a big choice is a strength.","persona":"Rohit","source":"help-seeking"},
  {"id":"cr-1119","cat":"own-your-choice","type":"reflect","hook":"Lensy: after a choice goes wrong, do you look at who it touched before fixing it?","prompt":"What do you do?","options":["Check who's affected","Just move on","Ask, then fix"],"affirm":"Owning a choice includes noticing how it affected others, then making it right.","relearn":"Owning a choice includes noticing how it affected others.","persona":"any","source":"empathy / accountability"},
  {"id":"cr-1120","cat":"own-your-choice","type":"reflect","hook":"Lensy: your choices over time shape who you become. Worth owning them?","prompt":"What do you think?","options":["Yes","Definitely","I want to choose well"],"affirm":"Owning each choice, good or bad, shapes the person you're becoming.","relearn":"Owning your choices shapes who you become.","persona":"any","source":"character"},
  {"id":"cr-1121","cat":"own-your-choice","type":"reflect","hook":"Lensy: when a friend owns their mistake to you, how do you feel about them?","prompt":"What do you think?","options":["More trust","Respect","Closer"],"affirm":"Owning a mistake earns trust, the same way it does when you do it.","relearn":"Owning a mistake earns trust, in you and in others.","persona":"Diya","source":"accountability"},
  {"id":"cr-1122","cat":"own-your-choice","type":"reflect","hook":"Lensy: 'next time I'll choose differently' is a quiet promise. Made one lately?","prompt":"Think of one.","options":["Yes","I'm working on it","I'll make one"],"affirm":"A quiet 'next time I'll choose differently' is how owning turns into growing.","relearn":"'Next time I'll choose differently' turns owning into growing.","persona":"any","source":"growth"},
  {"id":"cr-1123","cat":"own-your-choice","type":"reflect","hook":"Lensy: what's your motto for owning your choices?","prompt":"Pick one.","options":["Own it","Learn from it","Change course","Ask if it's big"],"affirm":"Carry that motto, you're ready to own whatever you choose.","relearn":"Own it, learn from it, change course, ask when it's big.","persona":"any","source":"consolidation"},
  {"id":"cr-1124","cat":"own-your-choice","type":"reflect","hook":"Lensy: a too-big choice can go to a trusted grown-up. Feel less alone knowing that?","prompt":"What do you think?","options":["Yes","Much less","Good to remember"],"affirm":"You never have to carry a too-big choice alone, a trusted grown-up can help.","relearn":"You don't have to carry a too-big choice alone.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1125","cat":"own-your-choice","type":"role-play","hook":"You realise a plan you pushed for went badly for the group.","setup":"Own it out loud. Say:","yourLine":[{"text":"\"That was my call and it didn't work, sorry, let's fix it.\"","best":true},{"text":"\"Don't look at me, it's not my problem.\""}],"relearn":"You can own a call that went wrong and offer to fix it.","persona":"Aarav","source":"accountability / voice"},
  {"id":"cr-1126","cat":"own-your-choice","type":"role-play","hook":"A teacher asks who left the lab untidy, and it was partly you.","setup":"Tell the truth. Say:","yourLine":[{"text":"\"Part of that was me, I'll help clean it up.\"","best":true},{"text":"\"No idea, wasn't me at all.\""}],"relearn":"Own your part honestly instead of denying it.","persona":"any","source":"accountability / voice"},
  {"id":"cr-1127","cat":"own-your-choice","type":"role-play","hook":"You want a grown-up's advice on a confusing choice.","setup":"Ask for it clearly. Say:","yourLine":[{"text":"\"This choice feels too big, can you help me think it through?\"","best":true},{"text":"\"It's fine, I'll just figure it out alone.\""}],"relearn":"You can ask a trusted adult to help with a big choice.","persona":"Rohit","source":"help-seeking / voice"},
  {"id":"cr-1128","cat":"own-your-choice","type":"role-play","hook":"You changed your mind about a plan and need to tell your friend.","setup":"Be honest and kind. Say:","yourLine":[{"text":"\"I've thought again and I want to change my choice, here's why.\"","best":true},{"text":"\"Uh, I don't know, whatever you want.\""}],"relearn":"You can honestly tell someone you've changed your choice.","persona":"Diya","source":"flexibility / voice"},
  {"id":"cr-1129","cat":"own-your-choice","type":"role-play","hook":"Your choice let a teammate down and you want to make it right.","setup":"Take responsibility. Say:","yourLine":[{"text":"\"That was on me, I'm sorry, how can I make it right?\"","best":true},{"text":"\"Everyone messes up, so what.\""}],"relearn":"Owning a choice that let someone down is mature and respected.","persona":"any","source":"accountability / voice"},
  {"id":"cr-1130","cat":"own-your-choice","type":"role-play","hook":"You got something wrong and people are waiting to hear what you say.","setup":"Own it calmly. Say:","yourLine":[{"text":"\"I got that wrong, and here's what I'll do differently.\"","best":true},{"text":"\"It wasn't really my fault, you know.\""}],"relearn":"Saying 'I got that wrong' calmly is strong, not weak.","persona":"Aarav","source":"accountability / voice"},
  {"id":"cr-1131","cat":"own-your-choice","type":"role-play","hook":"A friend asks how you feel after a choice that flopped.","setup":"Be honest without self-blame. Say:","yourLine":[{"text":"\"It didn't go well, but I'm learning from it.\"","best":true},{"text":"\"I'm just useless at everything.\""}],"relearn":"You can own a flop honestly without calling yourself useless.","persona":"Diya","source":"self-compassion / voice"},
  {"id":"cr-1132","cat":"own-your-choice","type":"sort","hook":"Sort: owning a choice, or dodging it?","items":[{"id":"a","text":"\"That was my decision\""},{"id":"b","text":"\"It's all their fault\""},{"id":"c","text":"\"Here's what I learned\""},{"id":"d","text":"\"I never said that\""},{"id":"e","text":"\"Let me make it right\""},{"id":"f","text":"\"Nothing to do with me\""}],"bins":[{"id":"own","label":"Owning it","valence":"pos"},{"id":"dodge","label":"Dodging it","valence":"neg"}],"key":{"a":"own","b":"dodge","c":"own","d":"dodge","e":"own","f":"dodge"},"relearn":"Owning means accepting, learning and fixing; dodging just deflects.","persona":"any","source":"accountability"},
  {"id":"cr-1133","cat":"own-your-choice","type":"sort","hook":"Sort: helps you own a choice well, or stops you?","items":[{"id":"a","text":"Admitting your part"},{"id":"b","text":"Blaming a friend"},{"id":"c","text":"Saying 'I'll do better'"},{"id":"d","text":"Making excuses"},{"id":"e","text":"Asking an adult's advice"},{"id":"f","text":"Hiding the mistake"}],"bins":[{"id":"helps","label":"Helps you own it","valence":"pos"},{"id":"stops","label":"Stops you owning it","valence":"neg"}],"key":{"a":"helps","b":"stops","c":"helps","d":"stops","e":"helps","f":"stops"},"relearn":"Admitting, improving and asking help you own it; blaming and hiding don't.","persona":"any","source":"accountability"},
  {"id":"cr-1134","cat":"own-your-choice","type":"sort","hook":"Sort: a learning response to a bad call, or a giving-up one?","items":[{"id":"a","text":"\"What can I do differently?\""},{"id":"b","text":"\"I'm hopeless, why bother\""},{"id":"c","text":"\"I'll try again\""},{"id":"d","text":"\"Everything I do fails\""},{"id":"e","text":"\"One slip, I'll learn\""},{"id":"f","text":"\"I'll just quit\""}],"bins":[{"id":"learn","label":"Learning from it","valence":"pos"},{"id":"giveup","label":"Giving up","valence":"neg"}],"key":{"a":"learn","b":"giveup","c":"learn","d":"giveup","e":"learn","f":"giveup"},"relearn":"A bad call is for learning from, not for giving up over.","persona":"any","source":"growth"},
  {"id":"cr-1135","cat":"own-your-choice","type":"sort","hook":"Sort: a choice you can handle yourself, or one to ask a trusted adult about?","items":[{"id":"a","text":"Which game to play at break"},{"id":"b","text":"A friend hinting they're being hurt"},{"id":"c","text":"What snack to pick"},{"id":"d","text":"A scary secret a friend shared"},{"id":"e","text":"Which book to read next"},{"id":"f","text":"A choice that feels too big and risky"}],"bins":[{"id":"self","label":"Handle yourself","valence":"neutral"},{"id":"ask","label":"Ask a trusted adult","valence":"tell"}],"key":{"a":"self","b":"ask","c":"self","d":"ask","e":"self","f":"ask"},"relearn":"Small choices you can make; big or risky ones go to a trusted adult.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1136","cat":"own-your-choice","type":"sort","hook":"Sort: taking responsibility, or shifting the blame?","items":[{"id":"a","text":"\"I should have checked first\""},{"id":"b","text":"\"You made me do it\""},{"id":"c","text":"\"I'll fix what I broke\""},{"id":"d","text":"\"It's the teacher's fault\""},{"id":"e","text":"\"My choice, my responsibility\""},{"id":"f","text":"\"Everyone else does it too\""}],"bins":[{"id":"resp","label":"Taking responsibility","valence":"pos"},{"id":"blame","label":"Shifting blame","valence":"neg"}],"key":{"a":"resp","b":"blame","c":"resp","d":"blame","e":"resp","f":"blame"},"relearn":"Taking responsibility owns the choice; shifting blame avoids it.","persona":"any","source":"accountability"},
  {"id":"cr-1137","cat":"own-your-choice","type":"sort","hook":"Sort: kind self-talk after a mistake, or harsh self-talk?","items":[{"id":"a","text":"\"I'm still learning\""},{"id":"b","text":"\"I'm so stupid\""},{"id":"c","text":"\"I can do better next time\""},{"id":"d","text":"\"I always mess up\""},{"id":"e","text":"\"One mistake, not the end\""},{"id":"f","text":"\"I ruin everything\""}],"bins":[{"id":"kind","label":"Kind self-talk","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Kind self-talk helps you learn; harsh self-talk just hurts.","persona":"Diya","source":"self-compassion"},
  {"id":"cr-1138","cat":"own-your-choice","type":"sort","hook":"Sort: changing course wisely, or stubbornly sticking?","items":[{"id":"a","text":"\"This isn't working, let's switch\""},{"id":"b","text":"\"I won't change, ever\""},{"id":"c","text":"\"New facts, new plan\""},{"id":"d","text":"\"I'd rather be wrong than admit it\""},{"id":"e","text":"\"Let's adjust and try again\""},{"id":"f","text":"\"Changing means I lose\""}],"bins":[{"id":"adapt","label":"Changing course wisely","valence":"pos"},{"id":"stuck","label":"Stubbornly stuck","valence":"neg"}],"key":{"a":"adapt","b":"stuck","c":"adapt","d":"stuck","e":"adapt","f":"stuck"},"relearn":"Changing course on new facts is wise; refusing to budge isn't.","persona":"any","source":"flexibility"},
  {"id":"cr-1139","cat":"own-your-choice","type":"build","hook":"Build the steps of owning a mistake.","prompt":"Order how to own a choice that went wrong.","pieces":["admit it was my choice","say sorry if it hurt someone","plan to do better"],"mode":"sequence","key":["admit it was my choice","say sorry if it hurt someone","plan to do better"],"relearn":"Admit it was yours, apologise if needed, then plan to do better.","persona":"any","source":"accountability"},
  {"id":"cr-1140","cat":"own-your-choice","type":"build","hook":"Build a kind 'learn from it' response to a bad call.","prompt":"Pick what belongs in learning from a mistake.","pieces":["I made a choice","it didn't work out","what can I change?","I'll try again"],"mode":"assemble","key":["I made a choice","it didn't work out","what can I change?","I'll try again"],"relearn":"Owning a bad call: I chose, it flopped, what can I change, try again.","persona":"any","source":"growth"},
  {"id":"cr-1141","cat":"own-your-choice","type":"build","hook":"Build the steps for a choice that feels too big.","prompt":"Order what to do with a too-big choice.","pieces":["notice it's too big for me alone","find a trusted adult","ask them to help me decide"],"mode":"sequence","key":["notice it's too big for me alone","find a trusted adult","ask them to help me decide"],"relearn":"Notice it's too big, find a trusted adult, ask them to help decide.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1142","cat":"own-your-choice","type":"build","hook":"Build a genuine apology for a choice that hurt someone.","prompt":"Pick what makes an apology real.","pieces":["name what I did","say I'm sorry","offer to make it right","mean it"],"mode":"assemble","key":["name what I did","say I'm sorry","offer to make it right","mean it"],"relearn":"A real apology names it, says sorry, offers a fix, and means it.","persona":"Diya","source":"repair"},
  {"id":"cr-1143","cat":"own-your-choice","type":"build","hook":"Build the steps to change course on a wrong choice.","prompt":"Order how to switch a choice that isn't working.","pieces":["admit it isn't working","see a better option","own it and switch"],"mode":"sequence","key":["admit it isn't working","see a better option","own it and switch"],"relearn":"Admit it isn't working, find a better option, own it and switch.","persona":"any","source":"flexibility"},
  {"id":"cr-1144","cat":"own-your-choice","type":"build","hook":"Build your 'own it' toolkit.","prompt":"Pick what belongs in owning your choices.","pieces":["honesty about my part","kindness to myself","willingness to fix it","learning for next time"],"mode":"assemble","key":["honesty about my part","kindness to myself","willingness to fix it","learning for next time"],"relearn":"Owning means honesty, self-kindness, fixing it, and learning.","persona":"any","source":"accountability"},
  {"id":"cr-1145","cat":"own-your-choice","type":"build","hook":"Build the steps to bounce back from a regretted choice.","prompt":"Order how to recover after a choice you regret.","pieces":["forgive myself","work out the lesson","make a better plan","move forward"],"mode":"sequence","key":["forgive myself","work out the lesson","make a better plan","move forward"],"relearn":"Forgive yourself, find the lesson, plan better, then move forward.","persona":"any","source":"self-compassion"},
  {"id":"cr-1146","cat":"own-your-choice","type":"match","hook":"Match the owning-it move to what it shows.","pairs":[{"left":"Saying 'that was my call'","right":"Taking responsibility"},{"left":"Apologising and fixing it","right":"Making it right"},{"left":"'What can I do differently?'","right":"Learning from it"},{"left":"Asking a grown-up on a big call","right":"Being resourceful"},{"left":"Switching when it isn't working","right":"Changing course"}],"relearn":"Each owning-it move shows a different part of good deciding.","persona":"any","source":"accountability"},
  {"id":"cr-1147","cat":"own-your-choice","type":"match","hook":"Match the choice that went wrong to a healthy next step.","pairs":[{"left":"Snapped at a friend","right":"Apologise and explain"},{"left":"Forgot a promise","right":"Own it and reschedule"},{"left":"Picked a flopping plan","right":"Pivot to a better one"},{"left":"Confused by a big choice","right":"Ask a trusted adult"},{"left":"Posted something mean","right":"Delete it and say sorry"}],"relearn":"Every choice that goes wrong has a healthy next step you can take.","persona":"any","source":"accountability"},
  {"id":"cr-1148","cat":"own-your-choice","type":"match","hook":"Match the self-talk to whether it helps you grow.","pairs":[{"left":"'I'm still learning'","right":"Helps you grow"},{"left":"'I always fail'","right":"Keeps you stuck"},{"left":"'I'll try a new way'","right":"Moves you forward"},{"left":"'It's all my fault, I'm bad'","right":"Just hurts"},{"left":"'One slip, not the end'","right":"Keeps it in proportion"}],"relearn":"Kind, learning self-talk grows you; harsh self-talk keeps you stuck.","persona":"Diya","source":"self-compassion"},
  {"id":"cr-1149","cat":"own-your-choice","type":"match","hook":"Match the value to an owning-your-choice action.","pairs":[{"left":"Honesty","right":"Admitting it was your call"},{"left":"Courage","right":"Saying 'I got it wrong'"},{"left":"Care","right":"Fixing harm you caused"},{"left":"Wisdom","right":"Asking advice on a big call"},{"left":"Growth","right":"Planning to do better"}],"relearn":"Owning a choice puts your values into action.","persona":"any","source":"values / accountability"},
  {"id":"cr-1150","cat":"own-your-choice","type":"match","hook":"Match the situation to who can best help you decide.","pairs":[{"left":"A scary secret a friend told you","right":"A trusted adult"},{"left":"Choosing between two hobbies","right":"A parent or mentor"},{"left":"A friend's safety at risk","right":"A trusted adult or Childline 1098"},{"left":"A small everyday pick","right":"Yourself"},{"left":"Stuck on a confusing call","right":"Someone you respect"}],"relearn":"Match a choice to the right helper; big or unsafe ones go to a trusted adult.","persona":"Asha","source":"help-seeking"},
  {"id":"cr-1151","cat":"own-your-choice","type":"match","hook":"Match owning a choice to the result it brings.","pairs":[{"left":"Admitting your part","right":"More trust from others"},{"left":"Learning from a slip","right":"Better judgement next time"},{"left":"Apologising sincerely","right":"A repaired friendship"},{"left":"Changing a wrong course","right":"A better outcome"},{"left":"Asking for advice","right":"A clearer decision"}],"relearn":"Owning your choices brings trust, growth and clearer decisions.","persona":"any","source":"accountability"},
  {"id":"cr-1152","cat":"own-your-choice","type":"match","hook":"Match the dodge to the owning-it line that replaces it.","pairs":[{"left":"'It wasn't me'","right":"'Part of that was me'"},{"left":"'You made me'","right":"'I chose that'"},{"left":"'Whatever, who cares'","right":"'I'll make it right'"},{"left":"'I'm hopeless'","right":"'I'm still learning'"},{"left":"'It's too late now'","right":"'I can still fix this'"}],"relearn":"Every dodge has an owning-it line that's braver and truer.","persona":"Aarav","source":"accountability"},
  {"id":"cr-1153","cat":"own-your-choice","type":"match","hook":"Match the choice-routine step to owning the outcome.","pairs":[{"left":"You chose in a rush","right":"Own that you skipped the pause"},{"left":"You missed a third option","right":"Look wider next time"},{"left":"You ignored the consequences","right":"Ask 'then what?' sooner"},{"left":"You went against your values","right":"Realign and apologise"},{"left":"You decided well","right":"Notice and repeat it"}],"relearn":"Owning the outcome links straight back to each decision step.","persona":"any","source":"consolidation"},
  {"type":"branch","options":[{"text":"Offer a third path: help them study at break instead","consequence":"You keep the friendship and neither of you cheats.","outcome":"wise","best":true},{"text":"Slide the answers over to keep the peace","consequence":"An ultimatum is a false binary; you can refuse it and still offer help."}],"debrief":"An 'or-else' threat hides a kinder third option.","id":"cr-1170","cat":"see-options","persona":"any","source":"options / friendship","relearn":"You can refuse an ultimatum and still be a good friend.","hook":"A classmate says copy answers in the test or you're not friends."},
  {"type":"branch","options":[{"text":"Suggest a different plan: include them or just leave it","consequence":"You shift the group away from cruelty without a big fight.","outcome":"wise","best":true},{"text":"Go along so the group doesn't turn on you","consequence":"Joining in isn't the only choice; a quieter third path shifts the mood."}],"debrief":"Between 'join in' and 'stay silent' sits a kinder path.","id":"cr-1171","cat":"see-options","persona":"Diya","source":"options / friendship (links g09)","relearn":"You can steer a group to kindness instead of picking a side.","hook":"Your group chat is planning to gang up and exclude one kid."},
  {"type":"branch","options":[{"text":"Find a third move: turn it into a harmless joke, or pass","consequence":"You stay in the fun without hurting anyone.","outcome":"creative","best":true},{"text":"Send it so you don't look boring","consequence":"'Send it or be boring' is a false two; a lighter option exists."}],"debrief":"A dare with two ugly ends usually has a third, kinder one.","id":"cr-1172","cat":"see-options","persona":"Aarav","source":"options thinking","relearn":"When a dare feels like two bad ends, look for a third.","hook":"Friends dare you to send a mean prank message from your phone."},
  {"type":"branch","options":[{"text":"Hand the extra back, or tell them quietly","consequence":"You do the honest thing and feel clear about it.","outcome":"wise","best":true},{"text":"Keep it since no one would know","consequence":"It isn't only 'keep it or make a scene'; quietly returning it is the third path."}],"debrief":"Even small money choices have more than two options.","id":"cr-1173","cat":"see-options","persona":"any","source":"options / values","relearn":"Quietly returning a mistake is an easy third option.","hook":"A shopkeeper gave you too much change by mistake."},
  {"type":"branch","options":[{"text":"Brainstorm: split the day, or celebrate one early","consequence":"You honour both without ranking your friends.","outcome":"creative","best":true},{"text":"Just pick the more popular friend's party","consequence":"You don't have to pick one and drop the other; times can be shared."}],"debrief":"A clash of two plans often has a 'do a bit of both' answer.","id":"cr-1174","cat":"see-options","persona":"Diya","source":"options thinking","relearn":"A scheduling clash usually has a share-the-time third option.","hook":"Two friends each invite you to their birthday on the same day."},
  {"type":"branch","options":[{"text":"Offer an alternative: a short practice then hang out","consequence":"You get both without being the odd one out.","outcome":"creative","best":true},{"text":"Skip practice so you don't seem like a spoilsport","consequence":"It's not 'all-in or left-out'; a smaller version pleases both."}],"debrief":"Half-and-half is a real option when a group splits two ways.","id":"cr-1175","cat":"see-options","persona":"any","source":"options thinking","relearn":"You can offer a middle plan instead of choosing all-or-nothing.","hook":"Your team wants to skip practice to hang out; you'd rather not."},
  {"type":"branch","options":[{"text":"Offer a different help: go with them to tell the truth","consequence":"You support your friend without lying for them.","outcome":"wise","best":true},{"text":"Cover the story to be a 'good friend'","consequence":"Real help isn't only 'lie or refuse'; standing in the truth is the third path."}],"debrief":"Helping a friend has options beyond covering.","id":"cr-1176","cat":"see-options","persona":"Asha","source":"options / friendship","relearn":"Helping a friend can mean standing with them in the truth.","hook":"A friend asks you to lie to their parents about where they were."},
  {"type":"branch","options":[{"text":"Tell them and offer to fix or replace it","consequence":"You own it and most likely keep their trust.","outcome":"wise","best":true},{"text":"Stay quiet and hope nobody finds out","consequence":"It isn't 'confess loudly or hide forever'; a calm 'I did it, sorry' is the third way."}],"debrief":"Owning a small mistake is a simple, real option.","id":"cr-1177","cat":"see-options","persona":"any","source":"options / values","relearn":"Owning a mistake calmly is a real, often easiest option.","hook":"You broke a classmate's pencil case by accident; they didn't see."},
  {"type":"branch","options":[{"text":"Suggest playing fair, or play a different round","consequence":"You keep the game fun and your own line.","outcome":"creative","best":true},{"text":"Go along because everyone seems into it","consequence":"'Cheat with them or lose them' is false; suggesting fair play is a third move."}],"debrief":"Peer pressure narrows your view to two; widen it.","id":"cr-1178","cat":"see-options","persona":"Aarav","source":"options thinking","relearn":"Under pressure, name a third option before you decide.","hook":"Older kids pressure you to share a game's cheat trick with them."},
  {"type":"branch","options":[{"text":"Suggest waiting and talking calmly later","consequence":"Tempers cool and the talk goes better.","outcome":"wise","best":true},{"text":"Join them to confront the kid immediately","consequence":"It's not 'rush in or abandon your friend'; waiting together is a wiser third path."}],"debrief":"'Now' and 'never' aren't the only timings.","id":"cr-1179","cat":"see-options","persona":"any","source":"options thinking","relearn":"Waiting to talk calmly is a real third option.","hook":"A friend wants to confront another kid right now while angry."},
  {"type":"branch","options":[{"text":"Ask if you can try both, or alternate weeks","consequence":"You discover the 'only one' rule was never really fixed.","outcome":"creative","best":true},{"text":"Just pick fast so you stop feeling stuck","consequence":"The 'pick one forever' framing was assumed; asking reveals more options."}],"debrief":"Question a 'choose one' rule before you obey it.","id":"cr-1180","cat":"see-options","persona":"any","source":"options thinking","relearn":"Ask whether a 'pick one' rule is actually fixed.","hook":"You're told to choose this club or that one, with no overlap allowed."},
  {"type":"branch","options":[{"text":"Refuse the either-or: 'I can like you both'","consequence":"You keep your friend and stay fair to the new kid.","outcome":"wise","best":true},{"text":"Agree just to keep your friend happy","consequence":"A 'with-me-or-against-me' line is a false binary you can decline."}],"debrief":"You're allowed to reject an ultimatum itself.","id":"cr-1181","cat":"see-options","persona":"Diya","source":"options / friendship","relearn":"You can refuse a 'with me or against me' choice.","hook":"A friend says: agree with me about the new kid or you're against me."},
  {"type":"branch","options":[{"text":"Offer a safer fun thing the group can do instead","consequence":"The group switches without you being 'the scared one'.","outcome":"creative","best":true},{"text":"Climb so you don't look like a chicken","consequence":"'Climb or be mocked' is a false two; redirecting the fun is the third path."}],"debrief":"Risky dares often have a safer, equally-fun swap.","id":"cr-1182","cat":"see-options","persona":"Aarav","source":"options thinking","relearn":"Redirect a risky dare to a safer, fun option.","hook":"Everyone's daring each other to climb the school's locked gate."},
  {"type":"branch","options":[{"text":"Suggest the three of you walk together at a comfy pace","consequence":"Nobody is left out and the walk is still fun.","outcome":"wise","best":true},{"text":"Speed off with your friend and leave them behind","consequence":"It isn't 'ditch them or ditch your friend'; including everyone is the third way."}],"debrief":"Including the third person is often the kindest option.","id":"cr-1183","cat":"see-options","persona":"Diya","source":"options / friendship","relearn":"Walking together is a kinder third option than ditching.","hook":"Your friend wants to ditch a slower kid on the walk home."},
  {"type":"branch","options":[{"text":"Delete it and send a short sorry","consequence":"You repair it before it grows.","outcome":"wise","best":true},{"text":"Leave it up and hope it blows over","consequence":"It's not 'leave it or panic'; a quiet delete-and-sorry is a calm third move."}],"debrief":"A small repair beats waiting for trouble.","id":"cr-1184","cat":"see-options","persona":"any","source":"options / values","relearn":"Quietly fixing a slip is a real, calm option.","hook":"You said something unkind in a chat; it's still up."},
  {"type":"branch","options":[{"text":"Suggest a tweak that works for you, then join","consequence":"You join on terms you're okay with.","outcome":"creative","best":true},{"text":"Cave to their exact plan to not miss out","consequence":"'Their way or miss out' is false; proposing a small change is a third option."}],"debrief":"You can shape a plan instead of just accepting or refusing.","id":"cr-1185","cat":"see-options","persona":"any","source":"options thinking","relearn":"You can propose a tweak instead of all-or-nothing.","hook":"Friends want you to choose: their plan, or stay home alone."},
  {"type":"branch","options":[{"text":"Wait, ask a grown-up, or look for other sellers","consequence":"The rush fades and you choose calmly.","outcome":"wise","best":true},{"text":"Buy fast so you don't miss the 'deal'","consequence":"A 'now or never' sales push is a false binary made to rush you."}],"debrief":"Pressure to decide instantly is a sign to widen your options.","id":"cr-1186","cat":"see-options","persona":"any","source":"options thinking","relearn":"A 'now or never' push is a cue to slow down and look wider.","hook":"A seller online says 'buy now or the deal's gone' on your saved-up money."},
  {"type":"branch","options":[{"text":"Tell a trusted grown-up so your friend gets help","consequence":"Your friend gets support, even if upset at first.","outcome":"wise","best":true},{"text":"Keep the secret because they asked you to","consequence":"Keeping a safety secret isn't the only loyal move; getting help is caring."}],"debrief":"When safety's at stake, telling a trusted adult is a caring option.","id":"cr-1187","cat":"see-options","persona":"Asha","source":"options / friendship (links g15)","relearn":"For a friend's safety, telling a trusted adult is caring.","hook":"A friend wants you to keep a worrying secret about their safety."},
  {"type":"branch","options":[{"text":"Ask each if a swap, split, or trial run is possible","consequence":"You find a workable plan nobody offered upfront.","outcome":"creative","best":true},{"text":"Drop one quickly to end the stress","consequence":"The 'pick one now' was the only option shown; asking surfaces more."}],"debrief":"Brainstorm options before settling on a forced two.","id":"cr-1188","cat":"see-options","persona":"any","source":"options thinking","relearn":"Ask around before accepting a forced 'pick one'.","hook":"Two clubs both want you at the same hour and say you must pick."},
  {"type":"branch","options":[{"text":"Ask for more time, or do a smaller honest version","consequence":"You hand in your own work without the panic-copy.","outcome":"wise","best":true},{"text":"Copy it so it's done tonight","consequence":"It's not 'copy or fail'; asking for time is a third path teachers respect."}],"debrief":"A deadline crunch still has options beyond copying.","id":"cr-1189","cat":"see-options","persona":"any","source":"options thinking","relearn":"A time crunch has options beyond copying.","hook":"You're tempted to copy a friend's project to finish fast."},
  {"type":"strike-rewrite","myth":{"un":"If someone gives me two choices, those must be the only ones.","re":"You can always ask 'what else could I do here?' and find more.","why":"Other people's two options are rarely all the options."},"id":"cr-1190","cat":"see-options","persona":"any","source":"options thinking","relearn":"Two given options aren't the whole list; ask what else you could do.","hook":"\"If two people offer me a choice, those are my only two.\""},
  {"type":"strike-rewrite","myth":{"un":"Hunting for more options is a waste of time.","re":"A quick 'what else?' often finds a better path fast.","why":"More options usually means a better, not slower, choice."},"id":"cr-1191","cat":"see-options","persona":"any","source":"options thinking","relearn":"Looking for more options makes the final choice better, not slower.","hook":"\"Looking for more options just wastes time.\""},
  {"type":"strike-rewrite","myth":{"un":"Choosing to wait means I gave up on deciding.","re":"Waiting on purpose is a real choice that keeps your options open.","why":"Pausing to gather more is active, not giving up."},"id":"cr-1192","cat":"see-options","persona":"any","source":"options thinking","relearn":"Choosing to wait is a real option, not giving up.","hook":"\"Doing nothing for now means I gave up.\""},
  {"type":"strike-rewrite","myth":{"un":"A clash can only end with my way or their way winning.","re":"Many clashes end in a shared third plan that fits both.","why":"Win-lose isn't the only outcome; win-win options exist."},"id":"cr-1193","cat":"see-options","persona":"Diya","source":"options / compromise","relearn":"A clash can end in a shared plan, not just my way or theirs.","hook":"\"It has to be my way or their way.\""},
  {"type":"strike-rewrite","myth":{"un":"Saying no to a dare means losing the friends.","re":"You can decline and still offer a different way to have fun.","why":"Refusing one thing isn't refusing the friendship."},"id":"cr-1194","cat":"see-options","persona":"Aarav","source":"options / friendship","relearn":"You can refuse a dare and still keep the friends.","hook":"\"If I refuse the dare, I lose the friends.\""},
  {"type":"strike-rewrite","myth":{"un":"Asking 'what else could I do?' makes me look unsure.","re":"Good deciders ask it on every crossroads; it's a skill, not doubt.","why":"Widening options is how careful deciders work."},"id":"cr-1195","cat":"see-options","persona":"any","source":"options thinking","relearn":"Asking 'what else could I do?' is a skill, not weakness.","hook":"\"Asking what else I could do makes me look unsure.\""},
  {"type":"strike-rewrite","myth":{"un":"Every choice has exactly one correct option hidden in it.","re":"Often several options are fine; you pick the one that fits your values.","why":"Many crossroads have more than one good path."},"id":"cr-1196","cat":"see-options","persona":"any","source":"options thinking","relearn":"Many choices have several okay options, not one secret 'right' one.","hook":"\"There is always one single right option to find.\""},
  {"type":"strike-rewrite","myth":{"un":"A hard choice means I've run out of options.","re":"Hard often means the good options are close; slow down and list them.","why":"Difficulty doesn't mean fewer options exist."},"id":"cr-1197","cat":"see-options","persona":"any","source":"options thinking","relearn":"A hard choice doesn't mean you're out of options.","hook":"\"If a choice is hard, that means I am out of options.\""},
  {"type":"strike-rewrite","myth":{"un":"If two friends fight, I have to choose a side.","re":"Staying kind to both and not carrying messages is a real third path.","why":"Neutral-and-kind is an option, not a cop-out."},"id":"cr-1198","cat":"see-options","persona":"Diya","source":"options / friendship (links g09)","relearn":"You can stay kind to both friends instead of choosing a side.","hook":"\"In a fight between two friends, I must choose a side.\""},
  {"type":"strike-rewrite","myth":{"un":"If the group has decided, that's the only option left.","re":"You can still suggest another path; groups change their mind often.","why":"A group's first idea isn't the final list of options."},"id":"cr-1199","cat":"see-options","persona":"any","source":"options thinking","relearn":"A group's pick isn't your only option; you can suggest another.","hook":"\"Whatever the group picks is the only real option.\""},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I'll list them","Good habit"],"affirm":"Listing every option first makes the real choice clearer.","id":"cr-1200","cat":"see-options","persona":"any","source":"options thinking","relearn":"Listing your options first makes choosing clearer.","hook":"Lensy: before choosing, you list every option you can think of. Worth trying?"},
  {"type":"reflect","prompt":"Honestly?","options":["I'd try it","Worth a shot","Hadn't thought of that"],"affirm":"Asking for a kinder way often reveals a gentler third path.","id":"cr-1201","cat":"see-options","persona":"any","source":"options thinking","relearn":"Asking 'is there a kinder way?' uncovers gentler options.","hook":"Lensy: stuck between two harsh choices — would asking 'is there a kinder way?' help you?"},
  {"type":"reflect","prompt":"Pick one.","options":["Freeing","Less trapped","Empowering"],"affirm":"You can decline a false either-or instead of choosing inside it.","id":"cr-1202","cat":"see-options","persona":"any","source":"options thinking","relearn":"You can refuse a false either-or, not just pick within it.","hook":"Lensy: you can refuse an 'either-or' itself. How does that feel to know?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Teamwork","I'll try it"],"affirm":"Asking others to brainstorm grows the list of good options.","id":"cr-1203","cat":"see-options","persona":"Diya","source":"options / brainstorm","relearn":"Asking others 'what else could we try?' widens the options.","hook":"Lensy: asking a friend 'what else could we try?' invites more ideas. Like it?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Makes sense","I see it"],"affirm":"Calming down first lets you spot options anger hides.","id":"cr-1204","cat":"see-options","persona":"Aarav","source":"options thinking","relearn":"Calming down first reveals options that anger hides.","hook":"Lensy: a calm question often unlocks an option anger would hide. Notice that?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Good to know","I'll remember"],"affirm":"Splitting or sharing is a real option many people forget.","id":"cr-1205","cat":"see-options","persona":"any","source":"options thinking","relearn":"Sharing or splitting is a real option people often forget.","hook":"Lensy: 'do a little of both' is sometimes possible. Handy to remember?"},
  {"type":"reflect","prompt":"Pick one.","options":["Lighter","More open","Hopeful"],"affirm":"Spotting options turns a stuck feeling into an open one.","id":"cr-1206","cat":"see-options","persona":"any","source":"agency","relearn":"Spotting options turns 'stuck' into 'open'.","hook":"Lensy: noticing you have options makes a stuck moment feel...?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I'll ask someone","Smart"],"affirm":"Asking someone you trust can reveal options you missed.","id":"cr-1207","cat":"see-options","persona":"Rohit","source":"options / ask-adult","relearn":"Asking someone you trust reveals options you missed.","hook":"Lensy: 'who could help me see more options?' A good question to keep?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I can picture them","Nice trick"],"affirm":"Sketching a few paths first makes the choice less rushed.","id":"cr-1208","cat":"see-options","persona":"any","source":"options thinking","relearn":"Sketching a few paths first slows a rushed choice.","hook":"Lensy: at a fork, you sketch three paths in your head before picking. Helpful?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I can do that","Good to hear"],"affirm":"Staying kind to both is a path you can pick, not a non-choice.","id":"cr-1209","cat":"see-options","persona":"Diya","source":"options / friendship","relearn":"Staying kind to both is a real path you can pick.","hook":"Lensy: 'kind to both' is a path you can choose between two friends. Reassuring?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Hadn't thought of it","I'll use it"],"affirm":"Asking for a little more time is a complete, valid option.","id":"cr-1210","cat":"see-options","persona":"any","source":"options thinking","relearn":"Asking for one more day is a complete, valid option.","hook":"Lensy: even 'ask for one more day' is an option. Did that occur to you?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I'll pause","True"],"affirm":"Your first idea is a start, not the whole list of options.","id":"cr-1211","cat":"see-options","persona":"any","source":"options thinking","relearn":"Your first idea is a start, not the full list.","hook":"Lensy: the first idea isn't always the only idea. Worth pausing on?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Interesting","I'll try it"],"affirm":"Sometimes you can change the situation instead of choosing inside it.","id":"cr-1212","cat":"see-options","persona":"any","source":"options thinking","relearn":"You can sometimes change the situation, not just choose within it.","hook":"Lensy: 'change the situation' can be an option, not just 'pick within it.' New idea?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I'll look harder","Good cue"],"affirm":"Two bad-feeling paths is a signal a better third one may exist.","id":"cr-1213","cat":"see-options","persona":"any","source":"options thinking","relearn":"Two bad-feeling paths is a cue to keep looking.","hook":"Lensy: when two paths both feel bad, that's a cue to look harder. Agree?"},
  {"type":"reflect","prompt":"Pick one.","options":["Yes","I feel freer","Makes sense"],"affirm":"Knowing your options gives freedom, whatever you finally choose.","id":"cr-1214","cat":"see-options","persona":"any","source":"agency","relearn":"Knowing your options is freedom, whatever you choose.","hook":"Lensy: more options means more freedom, even if you pick the same thing. See it?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Clever","I'll ask it"],"affirm":"Imagining a friend's situation can reveal options you'd miss for yourself.","id":"cr-1215","cat":"see-options","persona":"any","source":"options thinking","relearn":"'What would I tell a friend?' reveals options you'd miss.","hook":"Lensy: 'what would I tell a friend to do here?' A good way to spot options?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","I can say it","Sounds fine"],"affirm":"Saying you'll think of a few ways is calm and confident, never weak.","id":"cr-1216","cat":"see-options","persona":"any","source":"options thinking","relearn":"Saying 'let me think of a few ways' is calm and confident.","hook":"Lensy: you can say 'let me think of a few ways' out loud. Comfortable with that?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Sounds fun","I'll try"],"affirm":"Even silly options can jog a great real one loose.","id":"cr-1217","cat":"see-options","persona":"any","source":"options / brainstorm","relearn":"Even silly options can shake a better real one loose.","hook":"Lensy: brainstorming silly options too can shake a better real one loose. Try it?"},
  {"type":"reflect","prompt":"What do you think?","options":["Yes","Good to know","I'll use it"],"affirm":"'Not yet' is a fair answer while you collect more options.","id":"cr-1218","cat":"see-options","persona":"any","source":"options thinking","relearn":"'Not yet' is a fair answer while you gather options.","hook":"Lensy: 'not yet' can be your answer while you gather more options. Useful?"},
  {"type":"reflect","prompt":"Pick one.","options":["Yes","Love it","Nice image"],"affirm":"A third path is like a hidden door you learn to look for.","id":"cr-1219","cat":"see-options","persona":"any","source":"options thinking","relearn":"A third path is a hidden door you learn to look for.","hook":"Lensy: spotting a third path feels like finding a hidden door. Like that picture?"},
  {"type":"sort","items":[{"id":"a","text":"Suggest you both try something new"},{"id":"b","text":"Obey them or be alone"},{"id":"c","text":"Ask a grown-up for ideas"},{"id":"d","text":"Win or lose, nothing between"},{"id":"e","text":"Take turns this time"},{"id":"f","text":"Their plan or no plan at all"}],"bins":[{"id":"real","label":"Real option","valence":"pos"},{"id":"false","label":"False 'only two'","valence":"neg"}],"key":{"a":"real","b":"false","c":"real","d":"false","e":"real","f":"false"},"id":"cr-1220","cat":"see-options","persona":"any","source":"options thinking","relearn":"Trying new things, asking, and taking turns are real options; 'only two' lines are traps.","hook":"Sort: a real third option here, or a false 'only two'?"},
  {"type":"sort","items":[{"id":"a","text":"Ask 'what else could I do?'"},{"id":"b","text":"Decide in the first hot second"},{"id":"c","text":"Brainstorm with a friend"},{"id":"d","text":"Agree because everyone is"},{"id":"e","text":"Sleep on it overnight"},{"id":"f","text":"Say yes just to end it"}],"bins":[{"id":"wide","label":"Widens options","valence":"pos"},{"id":"narrow","label":"Narrows to two","valence":"neg"}],"key":{"a":"wide","b":"narrow","c":"wide","d":"narrow","e":"wide","f":"narrow"},"id":"cr-1221","cat":"see-options","persona":"any","source":"options thinking","relearn":"Asking, brainstorming and sleeping on it widen options; snap-yes choices narrow you.","hook":"Sort each move: widens your options, or narrows you to two?"},
  {"type":"sort","items":[{"id":"a","text":"Stay friendly with both"},{"id":"b","text":"Repeat one's insults to the other"},{"id":"c","text":"Refuse to carry messages"},{"id":"d","text":"Help one freeze the other out"},{"id":"e","text":"Invite both to the same game"},{"id":"f","text":"Drop whoever I like less"}],"bins":[{"id":"third","label":"Third path","valence":"pos"},{"id":"side","label":"Picks a side","valence":"neg"}],"key":{"a":"third","b":"side","c":"third","d":"side","e":"third","f":"side"},"id":"cr-1222","cat":"see-options","persona":"Diya","source":"options / friendship (links g09)","relearn":"Staying kind, not carrying messages and inviting both are third paths; the rest pick a side.","hook":"Sort: a kind third path between two friends, or picking a side?"},
  {"type":"sort","items":[{"id":"a","text":"Ask for one more day"},{"id":"b","text":"I just have to do it"},{"id":"c","text":"Offer a small change to the plan"},{"id":"d","text":"There's nothing I can do"},{"id":"e","text":"Look for a different person to ask"},{"id":"f","text":"It's too late to change anything"}],"bins":[{"id":"choice","label":"Real choice","valence":"pos"},{"id":"nochoice","label":"False 'no choice'","valence":"neg"}],"key":{"a":"choice","b":"nochoice","c":"choice","d":"nochoice","e":"choice","f":"nochoice"},"id":"cr-1223","cat":"see-options","persona":"any","source":"options thinking","relearn":"Asking for time, tweaking a plan and asking someone else are real choices; 'no choice' is a trap.","hook":"Sort: a real answer at a crossroads, or a false 'no choice'?"},
  {"type":"sort","items":[{"id":"a","text":"Stay calm before deciding"},{"id":"b","text":"Panic and rush"},{"id":"c","text":"Write the choices down"},{"id":"d","text":"Insist it's my way only"},{"id":"e","text":"Ask 'is there a kinder way?'"},{"id":"f","text":"Say 'there's no point trying'"}],"bins":[{"id":"open","label":"Opens options","valence":"pos"},{"id":"shut","label":"Shuts options","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"id":"cr-1224","cat":"see-options","persona":"any","source":"options thinking","relearn":"Staying calm, listing choices and asking for kinder ways open options; panic and 'no point' shut them.","hook":"Sort: helps you find more options, or shuts options down?"},
  {"type":"sort","items":[{"id":"a","text":"Like both new and old friends"},{"id":"b","text":"Pick me or pick them"},{"id":"c","text":"Join in part-way, on my terms"},{"id":"d","text":"All in or you're out"},{"id":"e","text":"Suggest a swap that suits both"},{"id":"f","text":"Do it now or never speak again"}],"bins":[{"id":"true","label":"True option","valence":"pos"},{"id":"ultimatum","label":"False ultimatum","valence":"neg"}],"key":{"a":"true","b":"ultimatum","c":"true","d":"ultimatum","e":"true","f":"ultimatum"},"id":"cr-1225","cat":"see-options","persona":"any","source":"options thinking","relearn":"Liking both, joining on your terms and suggesting a swap are real options; ultimatums are false.","hook":"Sort: a true third option, or a false ultimatum?"},
  {"type":"sort","items":[{"id":"a","text":"Take a slow breath first"},{"id":"b","text":"Just grab the nearest choice"},{"id":"c","text":"List two or three paths"},{"id":"d","text":"Decide before I even think"},{"id":"e","text":"Ask what each path leads to"},{"id":"f","text":"Go with whatever's loudest"}],"bins":[{"id":"calm","label":"Calm option","valence":"pos"},{"id":"snap","label":"Snap-now trap","valence":"neg"}],"key":{"a":"calm","b":"snap","c":"calm","d":"snap","e":"calm","f":"snap"},"id":"cr-1226","cat":"see-options","persona":"Aarav","source":"options thinking","relearn":"Breathing, listing paths and asking 'then what?' are calm options; grabbing or going loud is a snap-trap.","hook":"Sort: a calm option when you're stuck, or a 'snap-now' trap?"},
  {"type":"build","prompt":"What helps you find more than two options?","pieces":["ask 'what else could I do?'","picture each path's ending","ask someone you trust","check if it's a false 'only two'"],"mode":"assemble","key":["ask 'what else could I do?'","picture each path's ending","ask someone you trust","check if it's a false 'only two'"],"id":"cr-1227","cat":"see-options","persona":"any","source":"options thinking","relearn":"Ask 'what else?', picture each path, ask someone, and spot a false 'only two'.","hook":"Build your option-finder."},
  {"type":"build","prompt":"What goes into staying fair to both?","pieces":["stay friendly to each","don't carry messages","don't pick a side","invite both along"],"mode":"assemble","key":["stay friendly to each","don't carry messages","don't pick a side","invite both along"],"id":"cr-1228","cat":"see-options","persona":"Diya","source":"options / friendship","relearn":"Stay friendly, carry no messages, pick no side, and include both.","hook":"Build a kind third path between two friends."},
  {"type":"build","prompt":"Put the option-widening steps in order.","pieces":["pause the pressure","ask 'what else could I do?'","list a few paths","pick the one that fits"],"mode":"sequence","key":["pause the pressure","ask 'what else could I do?'","list a few paths","pick the one that fits"],"id":"cr-1229","cat":"see-options","persona":"any","source":"options thinking","relearn":"Pause, ask what else, list a few paths, then pick the fitting one.","hook":"Build the steps to widen a tight choice."},
  {"type":"build","prompt":"What turns 'their way or else' into a real choice?","pieces":["name the false either-or","stay calm","offer a third option","be okay if they're upset"],"mode":"assemble","key":["name the false either-or","stay calm","offer a third option","be okay if they're upset"],"id":"cr-1230","cat":"see-options","persona":"any","source":"options thinking","relearn":"Name the false either-or, stay calm, offer a third option, accept some upset.","hook":"Build your answer to an ultimatum."},
  {"type":"build","prompt":"Order how you brainstorm options together.","pieces":["agree to look for more ideas","each say any idea, even silly","keep the ones that could work","choose together"],"mode":"sequence","key":["agree to look for more ideas","each say any idea, even silly","keep the ones that could work","choose together"],"id":"cr-1231","cat":"see-options","persona":"Diya","source":"options / brainstorm","relearn":"Agree to brainstorm, throw out ideas, keep the workable ones, then choose together.","hook":"Build a brainstorm with a friend."},
  {"type":"build","prompt":"What makes waiting a real, active choice?","pieces":["decide on purpose to wait","set when you'll revisit it","gather more info meanwhile","stay ready to choose"],"mode":"assemble","key":["decide on purpose to wait","set when you'll revisit it","gather more info meanwhile","stay ready to choose"],"id":"cr-1232","cat":"see-options","persona":"any","source":"options thinking","relearn":"Choose to wait on purpose, set a revisit time, gather info, and stay ready.","hook":"Build a 'wait and see' option."},
  {"type":"build","prompt":"Order the check for a false binary.","pieces":["notice it feels like only two","ask 'what else could I do?'","look for a third path","decide from the wider list"],"mode":"sequence","key":["notice it feels like only two","ask 'what else could I do?'","look for a third path","decide from the wider list"],"id":"cr-1233","cat":"see-options","persona":"any","source":"options thinking","relearn":"Notice the 'only two' feel, ask what else, find a third path, then decide.","hook":"Build the 'is this really only two?' check."},
  {"type":"build","prompt":"What goes into finding a better third?","pieces":["take a breath","name why both feel bad","ask if you can change the situation","look for an option you missed"],"mode":"assemble","key":["take a breath","name why both feel bad","ask if you can change the situation","look for an option you missed"],"id":"cr-1234","cat":"see-options","persona":"any","source":"options thinking","relearn":"Breathe, name why both feel bad, ask if you can change it, and hunt the missed option.","hook":"Build a calm plan when two paths both feel bad."},
  {"type":"match","pairs":[{"left":"Two friends want me to pick a side","right":"Stay kind to both, no messages"},{"left":"'Copy my answers or we're done'","right":"Offer to help them study"},{"left":"Dared to do something I dislike","right":"Suggest a different, fun thing"},{"left":"Two plans clash on one day","right":"Take turns or do both"},{"left":"Pushed to decide this instant","right":"Ask for time to think"}],"id":"cr-1235","cat":"see-options","persona":"any","source":"options thinking","relearn":"Every 'only two' hides a smarter third option.","hook":"Match the tight spot to a third option that opens it."},
  {"type":"match","pairs":[{"left":"Their way or no friends","right":"Offer a plan that fits you both"},{"left":"Win the argument or lose","right":"Find a fair shared answer"},{"left":"Join the teasing or be next","right":"Quietly include the teased kid"},{"left":"Lie for my friend or refuse","right":"Stand with them in the truth"},{"left":"Buy now or miss the deal","right":"Wait and ask a grown-up first"}],"id":"cr-1236","cat":"see-options","persona":"any","source":"options thinking","relearn":"A false either-or always hides a real third option.","hook":"Match the false either-or to the real third path."},
  {"type":"match","pairs":[{"left":"'What else could I do?'","right":"More options than the obvious two"},{"left":"'Is there a kinder way?'","right":"A gentler path for everyone"},{"left":"'Who could help me think?'","right":"Ideas a trusted person sees"},{"left":"'What does each path lead to?'","right":"The likely 'then what?' of each"},{"left":"'Can I change the situation?'","right":"A way out of choosing inside it"}],"id":"cr-1237","cat":"see-options","persona":"any","source":"options thinking","relearn":"Good questions are tools that uncover hidden options.","hook":"Match the question to what it helps you find."},
  {"type":"match","pairs":[{"left":"Asking 'what else?'","right":"Widens your options"},{"left":"Deciding in the first hot second","right":"Narrows you to two"},{"left":"Brainstorming with a friend","right":"Widens your choices"},{"left":"Caving because 'everyone is'","right":"Narrows you to one"},{"left":"Sleeping on a big choice","right":"Opens up your options"}],"id":"cr-1238","cat":"see-options","persona":"any","source":"options thinking","relearn":"Some moves open the door to options; some slam it.","hook":"Match the move to whether it widens or narrows your options."},
  {"type":"match","pairs":[{"left":"Friend wants to ditch a slower kid","right":"Walk together at a comfy pace"},{"left":"Got too much change back","right":"Hand the extra back quietly"},{"left":"Friend's safety worries you","right":"Tell a trusted grown-up"},{"left":"Said something unkind online","right":"Delete it and send a sorry"},{"left":"Group plans to exclude a kid","right":"Suggest including them instead"}],"id":"cr-1239","cat":"see-options","persona":"Diya","source":"options / friendship","relearn":"Most real crossroads have a kind, doable third path.","hook":"Match the crossroads to the third path that fits."},
  {"type":"match","pairs":[{"left":"Wait and see","right":"'Let me get back to you tomorrow'"},{"left":"Ask for help thinking","right":"'Can you help me weigh this?'"},{"left":"Change the situation","right":"Move the talk to a calmer time"},{"left":"Offer a compromise","right":"'Half your plan, half mine'"},{"left":"Refuse the either-or","right":"'I won't pick; I can do both'"}],"id":"cr-1240","cat":"see-options","persona":"any","source":"options thinking","relearn":"There are many option types beyond the obvious two.","hook":"Match the option type to a clear example."},
  {"type":"match","pairs":[{"left":"'Decide right now!'","right":"Ask for a moment to think"},{"left":"'Everyone's already in'","right":"Decide for yourself anyway"},{"left":"'It's me or them'","right":"Say you can be friends with both"},{"left":"'There's no other way'","right":"Ask 'what else could we try?'"},{"left":"'You'll regret missing this'","right":"Slow down and check other options"}],"id":"cr-1241","cat":"see-options","persona":"Aarav","source":"options thinking","relearn":"Pressure tries to hide options; a calm question reveals them.","hook":"Match the pressure line to how to widen it."},
  {"type":"match","pairs":[{"left":"Both choices feel wrong","right":"Look harder for a third path"},{"left":"Too rushed to think","right":"Ask for a little time"},{"left":"Torn between two friends","right":"Choose to stay kind to both"},{"left":"Unsure and stuck","right":"Ask someone you trust for ideas"},{"left":"Tempted to copy in a panic","right":"Ask for extra time instead"}],"id":"cr-1242","cat":"see-options","persona":"any","source":"options thinking","relearn":"A stuck feeling is a signpost toward a better option.","hook":"Match the feeling to the option it points to."},
  {"type":"role-play","setup":"Open up a third path. Say:","yourLine":[{"text":"\"Could we try a different way that works for us both?\"","best":true},{"text":"\"Fine, we'll just do it your way.\""}],"id":"cr-1243","cat":"see-options","persona":"any","source":"options / voice","relearn":"You can ask for a third path instead of taking a forced two.","hook":"A friend pushes a my-way-or-else choice on you."},
  {"type":"role-play","setup":"Keep both, fairly. Say:","yourLine":[{"text":"\"I'd rather not pick a side; I can be friends with both.\"","best":true},{"text":"\"Okay, I'll side with you, I guess.\""}],"id":"cr-1244","cat":"see-options","persona":"Diya","source":"options / friendship / voice","relearn":"You can voice the third path: kind to both, no side picked.","hook":"Two friends each want you on their side."},
  {"type":"role-play","setup":"Buy time to find options. Say:","yourLine":[{"text":"\"Give me a bit to think of a few ways first.\"","best":true},{"text":"\"Okay, whatever, let's just decide now.\""}],"id":"cr-1245","cat":"see-options","persona":"any","source":"options / voice","relearn":"Asking for time to find options is calm and smart.","hook":"You're pushed to decide on the spot."},
  {"type":"role-play","setup":"Offer a swap. Say:","yourLine":[{"text":"\"Not that, but how about we do this instead?\"","best":true},{"text":"\"Ugh, fine, I'll do the dare.\""}],"id":"cr-1246","cat":"see-options","persona":"Aarav","source":"options / voice","relearn":"You can redirect a dare to a fun option you're okay with.","hook":"Friends dare you to do something you don't want to."},
  {"type":"role-play","setup":"Slow the rush. Say:","yourLine":[{"text":"\"I'll think it over and check other options first.\"","best":true},{"text":"\"Okay, I'll buy it right now.\""}],"id":"cr-1247","cat":"see-options","persona":"any","source":"options / voice","relearn":"You can refuse a 'now or never' and widen your options.","hook":"A seller online rushes you with 'now or never.'"},
  {"type":"role-play","setup":"Offer real help instead. Say:","yourLine":[{"text":"\"I won't lie, but I'll go with you to sort it out.\"","best":true},{"text":"\"Alright, I'll cover for you.\""}],"id":"cr-1248","cat":"see-options","persona":"Asha","source":"options / friendship / voice","relearn":"Helping a friend has an honest third option you can voice.","hook":"A friend asks you to cover a story for them."},
  {"type":"role-play","setup":"Name the better option. Say:","yourLine":[{"text":"\"Let's just include them; there's room for everyone.\"","best":true},{"text":"\"Fine, we'll leave them out.\""}],"id":"cr-1249","cat":"see-options","persona":"Diya","source":"options / voice","relearn":"You can voice the kinder third path to a group.","hook":"Your group says include the new kid or look uncool."},
  {"type":"role-play","setup":"Open the question. Say:","yourLine":[{"text":"\"Before we settle, what else could we try?\"","best":true},{"text":"\"I guess there's really no other way.\""}],"id":"cr-1250","cat":"see-options","persona":"any","source":"options / voice","relearn":"Asking 'what else could we try?' out loud reopens options.","hook":"Someone insists there's no other choice but theirs."},
  {"id":"cr-1260","cat":"stop-think","type":"branch","hook":"Cousins shout 'jump off the high wall, now!' and everyone's watching.","options":[{"text":"Say 'wait, let me look first' and check the drop","consequence":"You see it's too high and skip it; the pause kept you safe.","outcome":"careful","best":true},{"text":"Jump before you lose face","consequence":"A dare in the heat of the moment skips thinking; pause first."}],"debrief":"A loud 'now!' is exactly when to slow down and look.","relearn":"Pause and check before acting on a dare, even with everyone watching.","persona":"any","source":"stop and think / pressure"},
  {"id":"cr-1261","cat":"stop-think","type":"branch","hook":"In the auto home, your friend wants to text the whole class a secret.","options":[{"text":"Say 'let's wait till we're calm and sure'","consequence":"By evening you're glad you didn't send it.","outcome":"thoughtful","best":true},{"text":"Send it right away while it feels fun","consequence":"Sent-in-the-moment messages are hard to take back; pause first."}],"debrief":"A message can wait a few minutes; that pause saves regret.","relearn":"Wait before sending something you can't unsend.","persona":"any","source":"stop and think"},
  {"id":"cr-1262","cat":"stop-think","type":"branch","hook":"During an online game, a teammate yells 'rage-quit and report him, do it!'","options":[{"text":"Mute, breathe, decide after the match","consequence":"You cool off and handle it calmly later.","outcome":"regulated","best":true},{"text":"Quit and report in a fury","consequence":"Choices made mid-rage often miss the facts; cool down first."}],"debrief":"Heat-of-the-match anger is the worst moment to decide.","relearn":"Step back and cool down before deciding when you're raging.","persona":"Aarav","source":"emotion + decisions"},
  {"id":"cr-1263","cat":"stop-think","type":"branch","hook":"A shop's 'last piece, buy in 10 seconds!' sign makes your heart race.","options":[{"text":"Walk one lap and decide if you still want it","consequence":"The rush fades; you choose with a clear head.","outcome":"savvy","best":true},{"text":"Grab it before the countdown ends","consequence":"A countdown is a push to skip thinking; slow down."}],"debrief":"A ticking clock is usually a sales push, not a real deadline.","relearn":"A pause beats a countdown; real choices can wait a minute.","persona":"any","source":"decisions / persuasion"},
  {"id":"cr-1264","cat":"stop-think","type":"branch","hook":"Seniors crowd you at the gate: 'come bunk the next period with us, fast.'","options":[{"text":"Say 'give me a minute, I need to think'","consequence":"The minute lets you choose, not just go along.","outcome":"thoughtful","best":true},{"text":"Follow them so they don't think you're scared","consequence":"Going along to look brave skips your own thinking; pause."}],"debrief":"Asking for a minute under pressure is a power move, not weakness.","relearn":"You can ask for a minute before deciding under pressure.","persona":"any","source":"stop and think / peer pressure"},
  {"id":"cr-1265","cat":"stop-think","type":"branch","hook":"You just got a thrilling tournament invite and want to say yes this second.","options":[{"text":"Say 'sounds great, let me confirm by evening'","consequence":"You check your other plans and choose well.","outcome":"careful","best":true},{"text":"Shout yes before checking anything","consequence":"Excitement can rush a yes you'll have to undo; pause first."}],"debrief":"Even a happy 'yes' is better after a short think.","relearn":"Pause before a yes, even when you're excited.","persona":"any","source":"excitement + decisions"},
  {"id":"cr-1266","cat":"stop-think","type":"branch","hook":"A reel says 'real men decide instantly, only cowards pause.'","options":[{"text":"Scroll on; thinking first is the strong move","consequence":"You keep your pausing habit, which serves you well.","outcome":"grounded","best":true},{"text":"Believe it and start snap-deciding everything","consequence":"That 'no-pause' line is a myth; pausing is the smart move."}],"debrief":"Pausing to think is strength, whatever a hype reel claims.","relearn":"Don't let 'decide instantly' clips push you into snap calls.","persona":"Aarav","source":"alpha myths / stop and think"},
  {"id":"cr-1267","cat":"stop-think","type":"branch","hook":"At a wedding, a relative says 'pick your career right now, beta, quick!'","options":[{"text":"Say 'it's a big one, I want to think it over'","consequence":"They respect that; you keep room to decide well.","outcome":"thoughtful","best":true},{"text":"Blurt out any answer to end the spotlight","consequence":"A rushed answer to escape attention isn't really your choice; pause."}],"debrief":"Big choices deserve time, even when someone's pushing for now.","relearn":"You can take time on big choices, even when put on the spot.","persona":"any","source":"stop and think / family"},
  {"id":"cr-1268","cat":"stop-think","type":"branch","hook":"Your group chat is on fire and everyone wants you to pick a side NOW.","options":[{"text":"Type 'I'll reply after I've thought, not right now'","consequence":"The heat passes and you answer with a clear head.","outcome":"thoughtful","best":true},{"text":"Fire back instantly to keep up","consequence":"Replying to keep up means the chat decides for you; pause first."}],"debrief":"A fast group chat is built to rush you; you can step out and think.","relearn":"You don't owe the group an instant answer; you can pause.","persona":"any","source":"stop and think / online pressure"},
  {"id":"cr-1269","cat":"stop-think","type":"branch","hook":"A kid dares you to copy a risky stunt from a video, 'before the bus comes.'","options":[{"text":"Say 'no rush is worth this, I'm not doing it'","consequence":"You skip the stunt and feel fine about it after.","outcome":"safe","best":true},{"text":"Try it quickly before the bus arrives","consequence":"A 'do it before time runs out' push skips your safety check; pause."}],"debrief":"A made-up deadline is no reason to skip thinking about safety.","relearn":"Don't let a fake deadline rush you into something risky.","persona":"any","source":"stop and think / safety"},
  {"id":"cr-1270","cat":"stop-think","type":"branch","hook":"You're hurt by a comment and your thumb's over 'post this clapback.'","options":[{"text":"Save it to drafts, decide tomorrow","consequence":"By morning you don't even want to post it.","outcome":"regulated","best":true},{"text":"Post the clapback while you're stinging","consequence":"A reply sent while you're hurt usually backfires; wait it out."}],"debrief":"Sleep on a hot reply; future-you will thank you.","relearn":"Park a hot reply overnight before you decide to post it.","persona":"any","source":"emotion + decisions"},
  {"id":"cr-1271","cat":"stop-think","type":"branch","hook":"Friends keep chanting 'do it, do it' to push you up a shaky old ladder.","options":[{"text":"Stop and say 'I'll check if it's safe first'","consequence":"You spot the broken rung the chant made you ignore.","outcome":"careful","best":true},{"text":"Climb fast so the chanting stops","consequence":"A chant is pressure noise, not a safety check; pause and look."}],"debrief":"A chant pushes you to skip the look; that's exactly when to pause.","relearn":"Pause and check, even when friends are chanting.","persona":"any","source":"peer pressure / stop and think"},
  {"id":"cr-1272","cat":"stop-think","type":"strike-rewrite","hook":"\"If I pause, the moment passes and I lose my chance.\"","myth":{"un":"Pausing means you miss the moment.","re":"A short pause helps you choose better, and real chances wait.","why":"Anything that vanishes in seconds is usually pressure, not a real chance."},"relearn":"A short pause rarely costs a real chance; it improves your choice.","persona":"any","source":"stop and think"},
  {"id":"cr-1273","cat":"stop-think","type":"strike-rewrite","hook":"\"Counting to three before deciding is babyish.\"","myth":{"un":"Counting to three before you decide is childish.","re":"A three-count is a quick reset that even careful adults use.","why":"That tiny pause cools the rush so you think clearly."},"relearn":"A quick count before deciding is a smart reset, not babyish.","persona":"any","source":"stop and think"},
  {"id":"cr-1274","cat":"stop-think","type":"strike-rewrite","hook":"\"Whoever answers fastest in the group looks the smartest.\"","myth":{"un":"The fastest answer makes you look smartest.","re":"A thought-through answer beats a fast one that's wrong.","why":"Speed isn't the same as getting it right."},"relearn":"A careful answer beats a fast one; speed isn't smartness.","persona":"any","source":"stop and think / peer pressure"},
  {"id":"cr-1275","cat":"stop-think","type":"strike-rewrite","hook":"\"If I'm excited enough about something, I should just go for it.\"","myth":{"un":"Big excitement means you should decide on the spot.","re":"Excitement is a great signal, but still worth a pause to check.","why":"Strong feelings can hide a downside you'd spot if you slowed down."},"relearn":"Pause to check even an exciting choice; feelings can hide downsides.","persona":"any","source":"excitement + decisions"},
  {"id":"cr-1276","cat":"stop-think","type":"strike-rewrite","hook":"\"Saying 'let me think' means I don't have an opinion.\"","myth":{"un":"\"Let me think\" means you have no opinion.","re":"\"Let me think\" means you take the choice seriously.","why":"Careful deciders gather their thoughts before they answer."},"relearn":"\"Let me think\" shows you take a choice seriously, not that you're unsure.","persona":"any","source":"stop and think"},
  {"id":"cr-1277","cat":"stop-think","type":"strike-rewrite","hook":"\"Angry is the best time to sort someone out, while you mean it.\"","myth":{"un":"Anger is the best time to settle things.","re":"Sorting things out works better once the anger cools.","why":"Anger narrows your thinking and you miss the calm options."},"relearn":"Settle things after anger cools, not in the heat of it.","persona":"Aarav","source":"emotion + decisions"},
  {"id":"cr-1278","cat":"stop-think","type":"strike-rewrite","hook":"\"A pause is just stalling; deciders never hesitate.\"","myth":{"un":"Pausing is the same as stalling.","re":"A pause is for thinking, then you decide; stalling never decides.","why":"The pause leads into your options and consequences, not nowhere."},"relearn":"A thinking pause leads to a choice; that's not stalling.","persona":"any","source":"stop and think"},
  {"id":"cr-1279","cat":"stop-think","type":"strike-rewrite","hook":"\"If a friend's waiting, it's rude to take time to think.\"","myth":{"un":"Taking time to think is rude to whoever's waiting.","re":"A real friend can wait a minute while you think it through.","why":"Pressuring you for an instant answer is the less fair move."},"relearn":"A friend can wait a minute; thinking first isn't rude.","persona":"Diya","source":"stop and think / friendship"},
  {"id":"cr-1280","cat":"stop-think","type":"role-play","hook":"A classmate pushes you to commit to a plan you're unsure about.","setup":"Hold your ground for a think. Say:","yourLine":[{"text":"\"I'm not deciding on the spot; I'll tell you tomorrow.\"","best":true},{"text":"\"Ugh, fine, count me in I guess.\""}],"relearn":"\"I'll tell you tomorrow\" is a full, fair answer.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1281","cat":"stop-think","type":"role-play","hook":"Your team captain wants an instant yes to a risky shortcut.","setup":"Ask for a beat to think. Say:","yourLine":[{"text":"\"Give me a sec, I want to think before I agree.\"","best":true},{"text":"\"Sure, whatever you say, captain.\""}],"relearn":"\"Give me a sec\" buys you the think you need.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1282","cat":"stop-think","type":"role-play","hook":"Someone keeps repeating 'come on, yes or no, right now?'","setup":"Refuse the false rush. Say:","yourLine":[{"text":"\"If it has to be this second, the answer is no.\"","best":true},{"text":"\"Okay okay, yes, stop asking!\""}],"relearn":"A forced 'now' can fairly get a calm 'then no'.","persona":"Aarav","source":"pressure / voice"},
  {"id":"cr-1283","cat":"stop-think","type":"role-play","hook":"A relative on a call wants your decision before you've even thought.","setup":"Buy honest thinking time. Say:","yourLine":[{"text":"\"Can I think and call you back in a bit?\"","best":true},{"text":"\"Haan haan, whatever you think is best.\""}],"relearn":"\"Let me call you back\" is a respectful way to get think-time.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1284","cat":"stop-think","type":"role-play","hook":"Friends laugh that you're 'too slow' for pausing before you choose.","setup":"Own your pause calmly. Say:","yourLine":[{"text":"\"I think before I decide; that's not slow, it's smart.\"","best":true},{"text":"\"Fine, I'll just pick anything, happy?\""}],"relearn":"You can name your pause as smart without getting defensive.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1285","cat":"stop-think","type":"role-play","hook":"A seller online pings 'reply YES in 1 min or you lose the deal.'","setup":"Don't let the timer decide. Type:","yourLine":[{"text":"\"If it's only good for one minute, I'll pass.\"","best":true},{"text":"\"YES YES, send it before time's up!\""}],"relearn":"A one-minute timer is a push; you can pass on it.","persona":"any","source":"decisions / persuasion / voice"},
  {"id":"cr-1286","cat":"stop-think","type":"role-play","hook":"Your best friend wants you to promise something while you're both upset.","setup":"Wait for calm first. Say:","yourLine":[{"text":"\"Let's both cool down, then decide, not right now.\"","best":true},{"text":"\"Okay I promise, anything, just don't be mad.\""}],"relearn":"\"Let's cool down first\" protects you both from a rushed promise.","persona":"Diya","source":"emotion + decisions / voice"},
  {"id":"cr-1287","cat":"stop-think","type":"role-play","hook":"Kids on the field chant for a quick decision so the game can start.","setup":"Take your beat anyway. Say:","yourLine":[{"text":"\"Two seconds, I'm thinking; then I'll say.\"","best":true},{"text":"\"Forget it, I'll just go with the crowd.\""}],"relearn":"\"Two seconds, I'm thinking\" holds your space to decide.","persona":"any","source":"peer pressure / voice"},
  {"id":"cr-1288","cat":"stop-think","type":"reflect","hook":"Lensy: a Crossroads is any moment you must choose. What's one you hit today?","prompt":"Think of a small one.","options":["What to eat","Whether to reply","Who to sit with","Something bigger"],"affirm":"Even small forks are practice; the pause habit grows from them.","relearn":"You hit choices all day; each is a chance to practise the pause.","persona":"any","source":"decision awareness"},
  {"id":"cr-1289","cat":"stop-think","type":"reflect","hook":"Lensy: where do you feel a rush in your body when someone pushes you?","prompt":"Notice it.","options":["Fast heartbeat","Tight chest","Hot face","Jumpy hands"],"affirm":"That body signal is your cue; feel it, then pause before you choose.","relearn":"Your body's rush is a signal to pause before deciding.","persona":"any","source":"self-awareness"},
  {"id":"cr-1290","cat":"stop-think","type":"reflect","hook":"Lensy: which pause works best for you in a tense moment?","prompt":"Pick your go-to.","options":["A slow breath","Counting to three","Stepping back","Saying 'let me think'"],"affirm":"Any of these buys you a clear head; keep the one that fits you.","relearn":"You have several ways to pause; use whichever fits the moment.","persona":"any","source":"stop and think"},
  {"id":"cr-1291","cat":"stop-think","type":"reflect","hook":"Lensy: when do you most often wish you'd waited before deciding?","prompt":"Be honest with yourself.","options":["When angry","When excited","When teased","When tired"],"affirm":"Spotting your weak moment is how you build a pause right there.","relearn":"Knowing when you rush helps you plan a pause for that moment.","persona":"Aarav","source":"self-awareness"},
  {"id":"cr-1292","cat":"stop-think","type":"reflect","hook":"Lensy: someone says 'now or never'. How does that line sit with you?","prompt":"What do you make of it?","options":["It's pressure","Real chances wait","I can still pause","A push, not a rule"],"affirm":"Naming it as pressure takes its power; you can still take your beat.","relearn":"'Now or never' is usually pressure; you can still pause.","persona":"any","source":"stop and think / pressure"},
  {"id":"cr-1293","cat":"stop-think","type":"reflect","hook":"Lensy: think of a calm decider you know. What do they do before choosing?","prompt":"Picture them.","options":["They breathe","They ask questions","They take time","They stay calm"],"affirm":"You can borrow their move; the pause is a habit anyone can copy.","relearn":"Calm deciders pause first; you can copy that habit.","persona":"any","source":"stop and think"},
  {"id":"cr-1294","cat":"stop-think","type":"reflect","hook":"Lensy: would a five-second pause have changed a choice you regret?","prompt":"Look back gently.","options":["Probably yes","Maybe","Worth trying next time","I think so"],"affirm":"No blame here; the point is the pause is yours to use next time.","relearn":"A few seconds of pause can change a choice; it's yours to use.","persona":"any","source":"stop and think"},
  {"id":"cr-1295","cat":"stop-think","type":"reflect","hook":"Lensy: what could you say to buy yourself thinking time?","prompt":"Find your line.","options":["'Let me think'","'I'll get back to you'","'Give me a sec'","'Not deciding now'"],"affirm":"Any of these is a complete, fair answer; pick the one that's easiest to say.","relearn":"You always have a line to buy think-time; it's a full answer.","persona":"any","source":"stop and think"},
  {"id":"cr-1296","cat":"stop-think","type":"reflect","hook":"Lensy: which feeling makes pausing hardest for you?","prompt":"Just notice.","options":["Fear of missing out","Wanting to fit in","Anger","Big excitement"],"affirm":"Knowing your hardest feeling is exactly where to plant your pause.","relearn":"Your hardest feeling is where your pause matters most.","persona":"any","source":"self-awareness"},
  {"id":"cr-1297","cat":"stop-think","type":"reflect","hook":"Lensy: does pausing feel scared and slow, or careful and strong, to you?","prompt":"Be honest.","options":["Careful and strong","Both, honestly","Working on it","Strong, I think"],"affirm":"However it feels now, the pause is a power move; it grows on you.","relearn":"Pausing is a strength, even if it feels slow at first.","persona":"any","source":"stop and think"},
  {"id":"cr-1298","cat":"stop-think","type":"reflect","hook":"Lensy: who could you message later instead of deciding a big thing alone, now?","prompt":"Think of one person.","options":["A parent","An older cousin","A teacher","A trusted friend"],"affirm":"A pause can include 'I'll ask someone first'; that's smart deciding.","relearn":"A pause can mean 'I'll ask a trusted person before I choose'.","persona":"any","source":"stop and think / ask-an-adult"},
  {"id":"cr-1299","cat":"stop-think","type":"reflect","hook":"Lensy: how long do you think a good pause needs to be?","prompt":"Guess.","options":["A breath","A few seconds","A night to sleep on it","Depends on the choice"],"affirm":"All right answers; small choices need a breath, big ones can wait a night.","relearn":"A pause can be a breath or a night, sized to the choice.","persona":"any","source":"stop and think"},
  {"id":"cr-1300","cat":"stop-think","type":"reflect","hook":"Lensy: a friend keeps rushing you. What does that tell you?","prompt":"What do you think?","options":["It's a push","Worth slowing down","I can still pause","Maybe they're nervous too"],"affirm":"Reading the rush as a push helps you keep your own pace.","relearn":"When someone rushes you, that's a cue to slow down, not speed up.","persona":"any","source":"stop and think / pressure"},
  {"id":"cr-1301","cat":"stop-think","type":"reflect","hook":"Lensy: picture your pause as a traffic signal. What colour helps you stop?","prompt":"Just imagine it.","options":["Red, to stop","Amber, to slow","A breath in","Counting down"],"affirm":"Whatever picture works, the goal's the same: a beat before you go.","relearn":"A simple mental signal can remind you to pause before deciding.","persona":"any","source":"stop and think"},
  {"id":"cr-1302","cat":"stop-think","type":"reflect","hook":"Lensy: after you pause, what's the next thing a good decider does?","prompt":"Have a guess.","options":["Look at options","Ask 'then what?'","Check their values","All of these"],"affirm":"The pause opens the door; options, consequences and values come next.","relearn":"A pause leads into options, consequences and your values.","persona":"any","source":"decision process"},
  {"id":"cr-1303","cat":"stop-think","type":"reflect","hook":"Lensy: what's one place you could practise pausing this week?","prompt":"Pick a spot.","options":["In the group chat","On the field","At home","When I'm teased"],"affirm":"Practising in a small spot makes the pause ready for the big moments.","relearn":"Practising the pause in small spots builds it for the big ones.","persona":"any","source":"stop and think"},
  {"id":"cr-1304","cat":"stop-think","type":"reflect","hook":"Lensy: someone calls your pause 'overthinking'. Is it?","prompt":"What do you reckon?","options":["No, it's careful","A bit, maybe","One good think is enough","Depends"],"affirm":"One clear think isn't overthinking; you can pause once and then choose.","relearn":"A single careful think is deciding well, not overthinking.","persona":"any","source":"stop and think"},
  {"id":"cr-1305","cat":"stop-think","type":"build","hook":"Build your 'stop and think' move.","prompt":"Order the first steps of a calm decision.","pieces":["take a breath","name the rush","think before acting"],"mode":"sequence","key":["take a breath","name the rush","think before acting"],"relearn":"Breathe, name the rush you feel, then think before you act.","persona":"any","source":"decision process"},
  {"id":"cr-1306","cat":"stop-think","type":"build","hook":"Build a line that buys you thinking time.","prompt":"Put the words in order.","pieces":["let me","think about it","and get back to you"],"mode":"sequence","key":["let me","think about it","and get back to you"],"relearn":"\"Let me think about it and get back to you\" is a full answer.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1307","cat":"stop-think","type":"build","hook":"Build your pause kit (pick the things that help you stop and think).","prompt":"Assemble what helps you pause.","pieces":["a slow breath","a count to three","stepping back","a 'do it' chant","a ticking timer"],"mode":"assemble","key":["a slow breath","a count to three","stepping back"],"relearn":"Breaths, counts and stepping back help; chants and timers rush you.","persona":"any","source":"stop and think"},
  {"id":"cr-1308","cat":"stop-think","type":"build","hook":"Build the order for a hot-feeling moment.","prompt":"Sequence the steps when you're worked up.","pieces":["cool down","then look at options","then decide"],"mode":"sequence","key":["cool down","then look at options","then decide"],"relearn":"Cool down first, then look at options, then decide.","persona":"Aarav","source":"emotion + decisions"},
  {"id":"cr-1309","cat":"stop-think","type":"build","hook":"Build your anti-rush response to a 'decide now!' push.","prompt":"Pick the moves that resist a rush.","pieces":["name the timer as pressure","take a breath","ask 'what's the real deadline?'","just say yes fast","panic-buy"],"mode":"assemble","key":["name the timer as pressure","take a breath","ask 'what's the real deadline?'"],"relearn":"Name the pressure, breathe, and ask if the deadline is even real.","persona":"any","source":"decisions / persuasion"},
  {"id":"cr-1310","cat":"stop-think","type":"build","hook":"Build the order Aarav uses when a chat pile-on heats up.","prompt":"Sequence his calm-down steps.","pieces":["put the phone down","breathe and reread","reply when calm"],"mode":"sequence","key":["put the phone down","breathe and reread","reply when calm"],"relearn":"Put it down, breathe and reread, then reply when calm.","persona":"Aarav","source":"emotion + decisions / online"},
  {"id":"cr-1311","cat":"stop-think","type":"build","hook":"Build what makes a pause useful (not just a freeze).","prompt":"Pick what turns a pause into thinking.","pieces":["ask 'what's going on?'","picture the choices","check how you feel","stare blankly","wait for someone to decide"],"mode":"assemble","key":["ask 'what's going on?'","picture the choices","check how you feel"],"relearn":"A useful pause asks what's going on, pictures choices, checks feelings.","persona":"any","source":"decision process"},
  {"id":"cr-1312","cat":"stop-think","type":"match","hook":"Match each rushed moment to the pause that fits it.","pairs":[{"left":"Friends chanting 'do it'","right":"Step back and breathe"},{"left":"A 'buy now' countdown","right":"Ask if the deadline is real"},{"left":"You're boiling with anger","right":"Cool down before replying"},{"left":"Put on the spot by a relative","right":"Say 'let me think it over'"},{"left":"A thrilling instant invite","right":"Confirm later, not on the spot"}],"relearn":"Each kind of rush has a pause that fits it.","persona":"any","source":"stop and think"},
  {"id":"cr-1313","cat":"stop-think","type":"match","hook":"Match the pushy line to a calm thing you can say back.","pairs":[{"left":"'Decide right now!'","right":"'I'll decide once I've thought.'"},{"left":"'Yes or no, hurry!'","right":"'If it's this second, it's no.'"},{"left":"'Don't be so slow.'","right":"'Thinking first isn't slow.'"},{"left":"'Everyone's already in.'","right":"'I still want a minute.'"},{"left":"'Now or never.'","right":"'Then I'll let it go.'"}],"relearn":"Every pushy line has a calm answer that keeps your pace.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1314","cat":"stop-think","type":"match","hook":"Match each feeling to where you'd feel its rush.","pairs":[{"left":"Sudden anger","right":"A hot, tight face"},{"left":"Big excitement","right":"A racing heartbeat"},{"left":"Peer pressure","right":"A knot in your stomach"},{"left":"Fear of missing out","right":"Jumpy, restless hands"},{"left":"Feeling teased","right":"A lump in your throat"}],"relearn":"Each rush shows up in your body; that's your cue to pause.","persona":"any","source":"self-awareness"},
  {"id":"cr-1315","cat":"stop-think","type":"match","hook":"Match the pause length to the choice that needs it.","pairs":[{"left":"What snack to grab","right":"One quick breath"},{"left":"Whether to send a hot text","right":"A few minutes"},{"left":"Joining a risky dare","right":"Step back and think"},{"left":"A big plan with friends","right":"Sleep on it"},{"left":"A choice about safety","right":"Ask a trusted adult"}],"relearn":"Bigger choices deserve a longer pause; some need a grown-up.","persona":"any","source":"stop and think"},
  {"id":"cr-1316","cat":"stop-think","type":"match","hook":"Match each pause habit to what it does for you.","pairs":[{"left":"A slow breath","right":"Cools the rush"},{"left":"Counting to three","right":"Resets your head"},{"left":"Saying 'let me think'","right":"Buys you time"},{"left":"Stepping back","right":"Gives you space"},{"left":"Naming the feeling","right":"Takes its power"}],"relearn":"Each pause habit does a different job; together they steady you.","persona":"any","source":"stop and think"},
  {"id":"cr-1317","cat":"stop-think","type":"match","hook":"Match the moment to whether it's a real deadline or a fake rush.","pairs":[{"left":"A 10-second shop timer","right":"Fake rush, you can pass"},{"left":"Chanting 'now now now'","right":"Peer pressure, not a rule"},{"left":"A train you must catch","right":"Real deadline"},{"left":"'Last piece, decide fast'","right":"A sales push"},{"left":"Helping someone who's hurt","right":"Truly urgent"}],"relearn":"Tell a fake rush from a real deadline before you decide.","persona":"any","source":"stop and think / persuasion"},
  {"id":"cr-1318","cat":"stop-think","type":"match","hook":"Match each rushed regret to the pause that would've helped.","pairs":[{"left":"Sent a mean text in anger","right":"Saved it to drafts first"},{"left":"Bought a useless gadget","right":"Walked away and waited"},{"left":"Agreed to a risky dare","right":"Said 'let me think'"},{"left":"Picked a side in a fight","right":"Took a night to decide"},{"left":"Blurted out a secret","right":"Paused before speaking"}],"relearn":"A small pause could have changed each rushed choice.","persona":"any","source":"stop and think"},
  {"id":"cr-1319","cat":"stop-think","type":"match","hook":"Match each pause myth to the truth that busts it.","pairs":[{"left":"'Pausing means missing out'","right":"Real chances can wait"},{"left":"'Fast equals smart'","right":"Careful beats fast"},{"left":"'Asking time looks weak'","right":"It's a careful move"},{"left":"'A pause is just stalling'","right":"It leads to a choice"},{"left":"'Decide in the heat'","right":"Cool down first"}],"relearn":"Each pause myth has a truth that quietly busts it.","persona":"any","source":"stop and think"},
  {"id":"cr-1320","cat":"stop-think","type":"sort","hook":"Sort: a calm pause, or a rushed reaction?","items":[{"id":"a","text":"Counting to three first"},{"id":"b","text":"Hitting send while angry"},{"id":"c","text":"Saying 'let me think'"},{"id":"d","text":"Jumping at a dare"},{"id":"e","text":"Walking one lap before buying"},{"id":"f","text":"Yes-ing to beat a timer"}],"bins":[{"id":"calm","label":"Calm pause","valence":"pos"},{"id":"rushed","label":"Rushed reaction","valence":"uhoh"}],"key":{"a":"calm","b":"rushed","c":"calm","d":"rushed","e":"calm","f":"rushed"},"relearn":"Counting, asking time and waiting are pauses; sending hot and rushing aren't.","persona":"any","source":"stop and think"},
  {"id":"cr-1321","cat":"stop-think","type":"sort","hook":"Sort each line: buys you think-time, or caves to the rush?","items":[{"id":"a","text":"'I'll get back to you.'"},{"id":"b","text":"'Fine, whatever you want.'"},{"id":"c","text":"'Give me a sec to think.'"},{"id":"d","text":"'Okay okay, yes, hurry!'"},{"id":"e","text":"'Not deciding right now.'"},{"id":"f","text":"'Sure, count me in I guess.'"}],"bins":[{"id":"buys","label":"Buys think-time","valence":"tell"},{"id":"caves","label":"Caves to the rush","valence":"uhoh"}],"key":{"a":"buys","b":"caves","c":"buys","d":"caves","e":"buys","f":"caves"},"relearn":"Some lines hold your space to think; others just cave to the push.","persona":"any","source":"stop and think / voice"},
  {"id":"cr-1322","cat":"stop-think","type":"sort","hook":"Sort: a real deadline, or a fake rush dressed up as one?","items":[{"id":"a","text":"A train leaving in two minutes"},{"id":"b","text":"A '10 seconds to buy!' timer"},{"id":"c","text":"A friend hurt and needing help"},{"id":"d","text":"'Decide now or you're out.'"},{"id":"e","text":"A bus you have to catch"},{"id":"f","text":"'Last chance, this second!'"}],"bins":[{"id":"real","label":"Real deadline","valence":"neutral"},{"id":"fake","label":"Fake rush","valence":"uhoh"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Trains, buses and someone hurt are real; sales timers and ultimatums are fake rushes.","persona":"any","source":"stop and think / persuasion"},
  {"id":"cr-1323","cat":"stop-think","type":"sort","hook":"Sort each into the moment to pause, or a moment that's fine to act fast.","items":[{"id":"a","text":"You're boiling with anger"},{"id":"b","text":"Saying hi to a friend"},{"id":"c","text":"Pushed to pick a side"},{"id":"d","text":"Picking a pencil to use"},{"id":"e","text":"A risky dare in your face"},{"id":"f","text":"Choosing today's snack"}],"bins":[{"id":"pause","label":"Pause and think","valence":"tell"},{"id":"fine","label":"Fine to act fast","valence":"pos"}],"key":{"a":"pause","b":"fine","c":"pause","d":"fine","e":"pause","f":"fine"},"relearn":"Pause for hot or risky calls; small low-stakes ones can be quick.","persona":"any","source":"stop and think"},
  {"id":"cr-1324","cat":"stop-think","type":"sort","hook":"Sort: a true thing about pausing, or a myth about it?","items":[{"id":"a","text":"A pause helps you choose well"},{"id":"b","text":"Pausing means you missed out"},{"id":"c","text":"'Let me think' is a fair answer"},{"id":"d","text":"Fast deciders look smartest"},{"id":"e","text":"Cooling down beats deciding hot"},{"id":"f","text":"Asking for time looks weak"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Pausing helps and asking time is fair; 'fast is smart' and 'pause means miss out' are myths.","persona":"any","source":"stop and think"},
  {"id":"cr-1325","cat":"stop-think","type":"sort","hook":"Sort each thing as a pause habit, or a push that rushes you.","items":[{"id":"a","text":"A slow breath"},{"id":"b","text":"A chant of 'do it'"},{"id":"c","text":"Stepping back a moment"},{"id":"d","text":"A countdown clock"},{"id":"e","text":"Naming the feeling"},{"id":"f","text":"A crowd shouting 'hurry'"}],"bins":[{"id":"habit","label":"Pause habit","valence":"pos"},{"id":"push","label":"A push","valence":"uhoh"}],"key":{"a":"habit","b":"push","c":"habit","d":"push","e":"habit","f":"push"},"relearn":"Breaths, stepping back and naming feelings are pauses; chants, clocks and crowds push.","persona":"any","source":"stop and think"},
  {"id":"cr-1326","cat":"stop-think","type":"sort","hook":"Sort each step: comes before you decide, or after?","items":[{"id":"a","text":"Take a breath"},{"id":"b","text":"Pick and own your choice"},{"id":"c","text":"Name the rush you feel"},{"id":"d","text":"Live with what you chose"},{"id":"e","text":"Ask 'what's going on?'"},{"id":"f","text":"Learn from how it went"}],"bins":[{"id":"before","label":"Before deciding","valence":"tell"},{"id":"after","label":"After deciding","valence":"neutral"}],"key":{"a":"before","b":"after","c":"before","d":"after","e":"before","f":"after"},"relearn":"Breathe, name the rush and ask what's going on before; choose, live and learn after.","persona":"any","source":"decision process"},
  {"id":"cr-1350","type":"branch","hook":"A friend shares a classmate's secret with you and says pass it on.","options":[{"text":"Stop: think what passing it on would do, then keep it to yourself","consequence":"The secret stays safe and no one gets hurt.","outcome":"thoughtful","best":true},{"text":"Pass it to the next person","consequence":"A secret spreads fast; 'then what?' shows real hurt ahead."}],"debrief":"Ask 'then what?' before passing a secret on.","relearn":"Ask 'then what?' before you pass on a secret.","persona":"any","source":"then-what / sharing","cat":"weigh-consequences"},
  {"id":"cr-1351","type":"branch","hook":"Your group dares you to prank a shy kid for a laugh on the chat.","options":[{"text":"Weigh how the kid would feel, then say it's not funny","consequence":"You skip it; the shy kid is spared and you keep your name clean.","outcome":"thoughtful","best":true},{"text":"Do the prank so the group laughs","consequence":"The laugh ends fast; the hurt and your reputation last longer."}],"debrief":"Weigh who gets hurt, not just who laughs.","relearn":"Weigh who gets hurt, not just who laughs.","persona":"Aarav","source":"peer pressure / consequences","cat":"weigh-consequences"},
  {"id":"cr-1352","type":"branch","hook":"You found extra change in the shop and the keeper didn't notice.","options":[{"text":"Picture how you'd feel later, then hand the extra back","consequence":"You return it and walk away feeling honest.","outcome":"thoughtful","best":true},{"text":"Pocket it quietly","consequence":"The few rupees fade; how 'tomorrow you' feels about it stays."}],"debrief":"Weigh how future-you will feel before deciding.","relearn":"Ask how future-you will feel before you decide.","persona":"any","source":"money / consequences","cat":"weigh-consequences"},
  {"id":"cr-1353","type":"branch","hook":"A funny clip of your friend tripping would get loads of likes if you post it.","options":[{"text":"Think how they'd feel seeing it, then check before posting","consequence":"You ask first; they laugh too or say no, and trust holds.","outcome":"thoughtful","best":true},{"text":"Post it without asking","consequence":"Online it spreads and stays; weigh the embarrassment it leaves."}],"debrief":"Weigh how a post lands on others first.","relearn":"Weigh how a post lands on others before you share it.","persona":"any","source":"online / consequences","cat":"weigh-consequences"},
  {"id":"cr-1354","type":"branch","hook":"Your best friend wants you to skip another friend's party to be with her.","options":[{"text":"Weigh who gets hurt either way, then find a fair plan","consequence":"You split your time so neither friend feels dropped.","outcome":"thoughtful","best":true},{"text":"Ditch the party with no thought","consequence":"Skipping with no thought can quietly hurt the other friend."}],"debrief":"Weigh who gets hurt before choosing sides.","relearn":"Weigh who's affected before you choose sides.","persona":"Diya","source":"friendship / consequences","cat":"weigh-consequences"},
  {"id":"cr-1355","type":"branch","hook":"You broke a borrowed game controller and could hand it back in silence.","options":[{"text":"Think what happens when they find out, then tell them","consequence":"You own it early; they respect it and you sort it together.","outcome":"thoughtful","best":true},{"text":"Return it and say nothing","consequence":"They'll spot it later; 'then what?' makes owning it the safer call."}],"debrief":"'Then what?' makes owning it the lighter path.","relearn":"Play out 'then what?' before you hide a mistake.","persona":"any","source":"then-what / honesty","cat":"weigh-consequences"},
  {"id":"cr-1356","type":"branch","hook":"You could stay up late gaming the night before an important test.","options":[{"text":"Weigh tomorrow's tiredness against tonight's fun, then log off","consequence":"You sleep, and rested-you handles the test far better.","outcome":"thoughtful","best":true},{"text":"Game on and worry about it later","consequence":"Tonight's fun is short; a foggy test day costs you more."}],"debrief":"Weigh how tomorrow-you pays for tonight.","relearn":"Weigh how tomorrow-you pays for tonight's choice.","persona":"Aarav","source":"gaming / consequences","cat":"weigh-consequences"},
  {"id":"cr-1357","type":"branch","hook":"In a group project you could let one quiet member do all the boring parts.","options":[{"text":"Think how that lands on them, then share the load fairly","consequence":"Everyone pitches in; the team stays friendly and the work's better.","outcome":"thoughtful","best":true},{"text":"Dump the dull bits on the quiet one","consequence":"It feels easy now, but resentment and a weaker project follow."}],"debrief":"Weigh who carries the cost of an 'easy' choice.","relearn":"Weigh who carries the cost of an 'easy' choice.","persona":"any","source":"fairness / consequences","cat":"weigh-consequences"},
  {"id":"cr-1358","type":"branch","hook":"You've saved for one thing, but a cool toy in the shop tempts you today.","options":[{"text":"Weigh the thing you really wanted against this quick buy","consequence":"You wait; the saved-for thing means more than a passing want.","outcome":"thoughtful","best":true},{"text":"Spend it all on the toy now","consequence":"The toy thrills briefly; missing your real goal stings longer."}],"debrief":"Weigh a now-want against your real goal.","relearn":"Weigh a now-want against the thing you're actually saving for.","persona":"any","source":"spending / consequences","cat":"weigh-consequences"},
  {"id":"cr-1359","type":"branch","hook":"You heard a juicy rumour and could be the first to tell everyone.","options":[{"text":"Think what it does to the person, then don't spread it","consequence":"You let it die with you; no one gets hurt and you stay trusted.","outcome":"thoughtful","best":true},{"text":"Tell everyone first for the attention","consequence":"The buzz is brief; the harm to that person and your name lasts."}],"debrief":"Weigh the harm before enjoying being first.","relearn":"Weigh the harm a rumour does before you enjoy being first.","persona":"Diya","source":"rumours / consequences","cat":"weigh-consequences"},
  {"id":"cr-1360","type":"branch","hook":"You could tell your family the homework's done when it isn't, to go play.","options":[{"text":"Picture the talk when it's found out, then just do the work","consequence":"You finish it; no stress hanging over you and trust intact.","outcome":"thoughtful","best":true},{"text":"Say it's done and run off to play","consequence":"It surfaces later; 'then what?' makes doing it now the lighter path."}],"debrief":"Play out where a small lie leads first.","relearn":"Play out where a small lie leads before you tell it.","persona":"any","source":"then-what / chores","cat":"weigh-consequences"},
  {"id":"cr-1361","type":"branch","hook":"You could fake an injury to get out of the match you might lose.","options":[{"text":"Weigh how you'd feel afterward, then play and try your best","consequence":"You play; win or lose you're proud you didn't fake it.","outcome":"thoughtful","best":true},{"text":"Fake the injury to dodge it","consequence":"Ducking out feels safe now but sits badly and your team notices."}],"debrief":"Weigh how future-you feels about dodging.","relearn":"Weigh how future-you feels about dodging versus trying.","persona":"any","source":"sports / consequences","cat":"weigh-consequences"},
  {"id":"cr-1362","type":"branch","hook":"Friends dare you to climb the high wall to prove you're not scared.","options":[{"text":"Weigh a real fall against a moment of cred, then say no","consequence":"You skip it; the dare passes and you're fine.","outcome":"thoughtful","best":true},{"text":"Climb it to look brave","consequence":"A serious fall isn't worth seconds of 'brave'; weigh the real risk."}],"debrief":"Weigh real danger against fleeting 'cool'.","relearn":"Weigh real danger against fleeting 'looking brave'.","persona":"Aarav","source":"dares / safety","cat":"weigh-consequences"},
  {"id":"cr-1363","type":"branch","hook":"A friend asks you to do their chores so they can keep gaming, daily.","options":[{"text":"Think where this leads if it's always you, then talk it out","consequence":"You set a fair share; the friendship stays even, not one-sided.","outcome":"thoughtful","best":true},{"text":"Keep doing it all to keep the peace","consequence":"Always covering them breeds resentment; weigh the long run."}],"debrief":"Weigh the long-run cost of always giving in.","relearn":"Weigh the long-run cost of always giving in.","persona":"any","source":"helping / consequences","cat":"weigh-consequences"},
  {"id":"cr-1364","type":"branch","hook":"You could sneak your sibling's snacks and blame the dog.","options":[{"text":"Picture the fallout when they figure it out, then ask instead","consequence":"You ask; maybe you share, and no blame lands on anyone.","outcome":"thoughtful","best":true},{"text":"Take them and blame the dog","consequence":"The blame unravels; 'then what?' makes asking the cleaner choice."}],"debrief":"Trace 'then what?' before shifting blame.","relearn":"Trace 'then what?' before pinning a choice on someone else.","persona":"any","source":"then-what / trust","cat":"weigh-consequences"},
  {"id":"cr-1365","type":"branch","hook":"The group's laughing at a kid's clothes and you could join in to fit in.","options":[{"text":"Weigh the kid's hurt against fitting in, then stay out of it","consequence":"You don't pile on; you keep your kindness and your self-respect.","outcome":"thoughtful","best":true},{"text":"Join the laughing to fit in","consequence":"Fitting in lasts a second; the hurt you'd add lasts far longer."}],"debrief":"Weigh someone's hurt against fitting in.","relearn":"Weigh someone's hurt against a moment of fitting in.","persona":"Diya","source":"approval / consequences","cat":"weigh-consequences"},
  {"id":"cr-1366","type":"branch","hook":"You could rush your project tonight or spread it over the week.","options":[{"text":"Weigh a rushed mess against steady work, then plan it out","consequence":"You space it out; the work's better and the night's calmer.","outcome":"thoughtful","best":true},{"text":"Cram it into ten panicked minutes","consequence":"Rushing feels quick but the shaky result and stress cost more."}],"debrief":"Weigh quick-but-rough against steady-and-solid.","relearn":"Weigh quick-but-rough against steady-and-solid first.","persona":"any","source":"time / consequences","cat":"weigh-consequences"},
  {"id":"cr-1367","type":"branch","hook":"A friend says an older kid is scaring them, and swears you to secrecy.","options":[{"text":"Put their safety first, then bring in a trusted grown-up","consequence":"A caring adult helps; your friend ends up safer.","outcome":"thoughtful","best":true},{"text":"Keep the secret you promised","consequence":"Some secrets are too big to hold; safety outweighs the promise."}],"debrief":"Safety outweighs a promise; tell a trusted adult.","relearn":"On a safety secret, telling a trusted adult is caring.","persona":"any","source":"secrets / safety","cat":"weigh-consequences"},
  {"id":"cr-1368","type":"branch","hook":"You could let a classmate copy your test answers while the teacher's away.","options":[{"text":"Think what happens if it's spotted, then quietly say no","consequence":"You keep it fair; nobody's in trouble and your work stays yours.","outcome":"thoughtful","best":true},{"text":"Slide your paper over to copy","consequence":"If caught you both pay; 'then what?' makes no the safer call."}],"debrief":"Weigh 'then what?' before cutting a corner.","relearn":"Weigh 'then what?' before helping someone cut a corner.","persona":"any","source":"then-what / school","cat":"weigh-consequences"},
  {"id":"cr-1369","type":"reflect","hook":"Lensy: before a choice, asking 'and then what happens?' Worth a try?","prompt":"What do you think?","options":["Yes","Then-what habit","I'll ask it"],"affirm":"'And then what?' is the question that weighs a choice for you.","relearn":"Ask 'and then what?' for each option before you pick.","persona":"any","source":"then-what / habit","cat":"weigh-consequences"},
  {"id":"cr-1370","type":"reflect","hook":"Lensy: imagine telling next-week-you about this choice. How does that feel?","prompt":"What do you think?","options":["Calming","Helps me see","I'll picture it"],"affirm":"Picturing next-week-you is a quick, honest consequence check.","relearn":"Imagine explaining your choice to future-you before deciding.","persona":"Diya","source":"future-me","cat":"weigh-consequences"},
  {"id":"cr-1371","type":"reflect","hook":"Lensy: a good choice asks 'who else feels this?' Ever skipped that?","prompt":"What do you think?","options":["Sometimes","Others matter","I'll check it"],"affirm":"Checking who else is affected makes a choice fairer.","relearn":"Ask who else your choice touches, not just you.","persona":"any","source":"others","cat":"weigh-consequences"},
  {"id":"cr-1372","type":"reflect","hook":"Lensy: heat-of-the-moment choices skip the 'then what?'. See that in yourself?","prompt":"What do you think?","options":["Yeah","Heat skips thinking","I'll slow down"],"affirm":"Spotting your hot moments is when 'then what?' helps most.","relearn":"In the heat of a moment, slow down and ask 'then what?'.","persona":"Aarav","source":"pressure","cat":"weigh-consequences"},
  {"id":"cr-1373","type":"reflect","hook":"Lensy: a quick goods-and-bads list before a choice. Useful?","prompt":"What do you think?","options":["Yes","Goods and bads","I'll list them"],"affirm":"A fast goods-and-bads list weighs a choice in seconds.","relearn":"Run a quick goods-and-bads list before you choose.","persona":"any","source":"pros-cons","cat":"weigh-consequences"},
  {"id":"cr-1374","type":"reflect","hook":"Lensy: some choices you can undo, some you can't. Worth knowing which?","prompt":"What do you think?","options":["Yes","Can-I-undo-it","I'll ask"],"affirm":"Asking 'can I undo this?' tells you how carefully to weigh it.","relearn":"Ask 'can I undo this?' to know how hard to think.","persona":"Diya","source":"reversible","cat":"weigh-consequences"},
  {"id":"cr-1375","type":"reflect","hook":"Lensy: a big choice deserves more thought than a tiny one. Agree?","prompt":"What do you think?","options":["Yes","Match the thought","Makes sense"],"affirm":"Big choices earn more weighing; small ones need only a beat.","relearn":"Give bigger choices more thought than small ones.","persona":"any","source":"small-vs-big","cat":"weigh-consequences"},
  {"id":"cr-1376","type":"reflect","hook":"Lensy: one choice can set off a chain of things. Seen that happen?","prompt":"What do you think?","options":["Yes","Choices ripple","I'll watch for it"],"affirm":"Following the ripple shows the consequences a choice can set off.","relearn":"Trace the ripple a choice can start before you make it.","persona":"any","source":"ripple","cat":"weigh-consequences"},
  {"id":"cr-1377","type":"reflect","hook":"Lensy: 'would I regret this?' is a fast gut check. Use it?","prompt":"What do you think?","options":["Yes","Regret check","I'll try it"],"affirm":"The 'would I regret this?' question weighs a choice quickly.","relearn":"Ask 'would I regret this?' before you commit.","persona":"Aarav","source":"regret","cat":"weigh-consequences"},
  {"id":"cr-1378","type":"reflect","hook":"Lensy: every choice costs something, even a good one. Noticed?","prompt":"What do you think?","options":["Yes","Always a cost","I'll weigh it"],"affirm":"Naming what a choice costs helps you decide if it's worth it.","relearn":"Name what each option costs before you weigh them.","persona":"any","source":"cost","cat":"weigh-consequences"},
  {"id":"cr-1379","type":"reflect","hook":"Lensy: 'great now, sorry later' is a trap. Caught yourself in it?","prompt":"What do you think?","options":["Yes","Now vs later","I'll check both"],"affirm":"Weighing now AND later keeps the 'great now' trap from fooling you.","relearn":"Weigh both how it feels now and how it feels later.","persona":"Diya","source":"short-vs-long","cat":"weigh-consequences"},
  {"id":"cr-1380","type":"reflect","hook":"Lensy: asking 'what's the worst that could happen?' once. Helpful?","prompt":"What do you think?","options":["Yes","Worst-case peek","I'll ask it"],"affirm":"A quick worst-case peek shows if a risk is worth taking.","relearn":"Ask once 'what's the worst that could happen?' and weigh it.","persona":"any","source":"worst-case","cat":"weigh-consequences"},
  {"id":"cr-1381","type":"reflect","hook":"Lensy: 'who gains and who loses from this?' Worth checking?","prompt":"What do you think?","options":["Yes","Gains and losses","I'll map it"],"affirm":"Mapping who gains and who loses makes a choice clearer.","relearn":"Check who gains and who loses before you decide.","persona":"any","source":"who-benefits","cat":"weigh-consequences"},
  {"id":"cr-1382","type":"reflect","hook":"Lensy: 'could I tell my future self this with a straight face?' Try it?","prompt":"What do you think?","options":["Yes","Straight-face test","I'll use it"],"affirm":"The straight-face test quietly weighs how a choice will sit.","relearn":"Ask if you could own this choice later with a straight face.","persona":"Aarav","source":"own-it-later","cat":"weigh-consequences"},
  {"id":"cr-1383","type":"reflect","hook":"Lensy: weighing means looking at both sides, not just the fun one. Fair?","prompt":"What do you think?","options":["Fair","Both sides","I'll do both"],"affirm":"Looking at both sides, not just the fun one, is real weighing.","relearn":"Weigh both sides of a choice, not only the appealing one.","persona":"any","source":"two-sides","cat":"weigh-consequences"},
  {"id":"cr-1384","type":"reflect","hook":"Lensy: the bigger the choice, the more a slow breath helps. Notice that?","prompt":"What do you think?","options":["Yes","Breathe on big ones","I'll pause"],"affirm":"A slow breath gives a big choice the weighing it deserves.","relearn":"Take a breath before a big choice so you can weigh it.","persona":"Diya","source":"slow-down","cat":"weigh-consequences"},
  {"id":"cr-1385","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Skipping sleep before a test","right":"Tired, foggy mind next day"},{"left":"Saving a bit each week","right":"Enough for the thing you want"},{"left":"Sending an angry message fast","right":"Words you can't take back"},{"left":"Helping a friend revise","right":"Both of you understand it better"},{"left":"Eating only sweets all day","right":"A sore tummy by evening"}],"relearn":"Each choice leads somewhere; you can often predict where.","persona":"any","source":"then-what / pairs","cat":"weigh-consequences"},
  {"id":"cr-1386","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Breaking a promise","right":"A friend trusts you less"},{"left":"Owning up to a mistake","right":"People respect your honesty"},{"left":"Leaving a kid out","right":"They feel hurt and alone"},{"left":"Sharing the credit","right":"The whole team feels valued"},{"left":"Rushing a job carelessly","right":"Mistakes you have to redo"}],"relearn":"Good and bad choices each carry their own 'then what?'.","persona":"any","source":"consequences / pairs","cat":"weigh-consequences"},
  {"id":"cr-1387","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Carrying messages between two friends","right":"You get caught in the middle"},{"left":"Telling a small lie to look cool","right":"A bigger lie to cover it later"},{"left":"Including the new kid","right":"A friend who feels welcome"},{"left":"Copying instead of learning","right":"Stuck when there's no one to copy"},{"left":"Saying sorry quickly","right":"A fight that ends fast"}],"relearn":"Friendship choices ripple; weigh where each one leads.","persona":"Diya","source":"friendship / pairs","cat":"weigh-consequences"},
  {"id":"cr-1388","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Sharing a private photo","right":"It spreads beyond your control"},{"left":"Pausing before an angry reply","right":"A calmer, clearer message"},{"left":"Joining a pile-on comment","right":"Adding to someone's bad day"},{"left":"Logging off to sleep","right":"A clearer head tomorrow"},{"left":"Saving a screenshot to use later","right":"A trust you can't rebuild"}],"relearn":"Online choices last and spread; weigh that before you tap.","persona":"Aarav","source":"online / pairs","cat":"weigh-consequences"},
  {"id":"cr-1389","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"A fun shortcut now","right":"More work to fix it later"},{"left":"Steady practice","right":"Skill that lasts"},{"left":"Spending all your money today","right":"Nothing left for the goal"},{"left":"A kind word to someone down","right":"A friend who remembers it"},{"left":"Ignoring a small problem","right":"A bigger one that grows"}],"relearn":"Some choices pay off later; some bills come due later too.","persona":"any","source":"short-vs-long / pairs","cat":"weigh-consequences"},
  {"id":"cr-1390","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Taking the last seat with friends","right":"Someone else stands"},{"left":"Sharing your notes","right":"A classmate catches up"},{"left":"Blasting music late","right":"Family woken up"},{"left":"Cleaning up your own mess","right":"Less work for someone else"},{"left":"Cutting the queue","right":"People behind you wait longer"}],"relearn":"Most choices touch other people; weigh who feels each one.","persona":"any","source":"who-is-affected / pairs","cat":"weigh-consequences"},
  {"id":"cr-1391","type":"match","hook":"Match the choice to a likely consequence.","pairs":[{"left":"Returning extra change","right":"A clear conscience"},{"left":"Keeping a found thing","right":"A quiet, uneasy feeling"},{"left":"Standing up for a teased kid","right":"Pride in doing right"},{"left":"Laughing along at teasing","right":"Regret when you cool down"},{"left":"Telling the truth when it's hard","right":"Trust that grows"}],"relearn":"Weigh how a choice will sit with you, not just the gain.","persona":"any","source":"values / pairs","cat":"weigh-consequences"},
  {"id":"cr-1392","type":"strike-rewrite","hook":"\"What happens next isn't worth thinking about.\"","myth":{"un":"What happens next isn't worth thinking about.","re":"Asking 'then what?' first is the heart of a good choice.","why":"Every choice has a next; weighing it is how you choose well."},"relearn":"Weigh 'then what?' before you decide, every time.","persona":"any","source":"then-what","cat":"weigh-consequences"},
  {"id":"cr-1393","type":"strike-rewrite","hook":"\"A win now is always worth it.\"","myth":{"un":"A win now is always worth it.","re":"A win now can cost more later; weigh both before you grab it.","why":"Copying tonight saves time but you learn nothing and risk getting caught."},"relearn":"Weigh the later cost, not just the win now.","persona":"any","source":"short-term","cat":"weigh-consequences"},
  {"id":"cr-1394","type":"strike-rewrite","hook":"\"If it helps me, who else it hits doesn't matter.\"","myth":{"un":"If it helps me, who else it hits doesn't matter.","re":"Good choices weigh who else is affected, not only yourself.","why":"A choice that lands on others is only half-weighed if you skip them."},"relearn":"Weigh who else your choice affects.","persona":"any","source":"others","cat":"weigh-consequences"},
  {"id":"cr-1395","type":"strike-rewrite","hook":"\"Thinking about consequences just slows you down.\"","myth":{"un":"Thinking about consequences just slows you down.","re":"A few seconds of 'then what?' makes the choice better, not slower.","why":"Weighing first saves the time a rushed, wrong choice would cost."},"relearn":"A quick weigh-up beats a fast wrong choice.","persona":"any","source":"speed","cat":"weigh-consequences"},
  {"id":"cr-1396","type":"strike-rewrite","hook":"\"Only how I feel right now should decide it.\"","myth":{"un":"Only how I feel right now should decide it.","re":"How you'll feel later counts as much as how you feel now.","why":"A choice can feel great now and bad later; weigh both."},"relearn":"Weigh later-you's feelings, not just right-now's.","persona":"Diya","source":"feelings","cat":"weigh-consequences"},
  {"id":"cr-1397","type":"strike-rewrite","hook":"\"Every choice can be undone, so why weigh it.\"","myth":{"un":"Every choice can be undone, so why weigh it.","re":"Some choices can't be taken back; that's exactly why you weigh them.","why":"Knowing what you can't undo tells you how carefully to choose."},"relearn":"Weigh hardest the choices you can't undo.","persona":"any","source":"reversible","cat":"weigh-consequences"},
  {"id":"cr-1398","type":"strike-rewrite","hook":"\"A big risk is fine if the reward looks cool.\"","myth":{"un":"A big risk is fine if the reward looks cool.","re":"Weigh the real harm against the reward; cool fades, harm can last.","why":"A risk that can hurt you isn't paid for by a moment of looking cool."},"relearn":"Weigh real harm against a fleeting reward.","persona":"Aarav","source":"risk","cat":"weigh-consequences"},
  {"id":"cr-1399","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Order the steps to weigh a choice.","pieces":["List your options","Ask 'then what?' for each","Compare the goods and bads","Pick the one you can own"],"mode":"sequence","key":["List your options","Ask 'then what?' for each","Compare the goods and bads","Pick the one you can own"],"relearn":"Weigh a choice: options, 'then what?', compare, then own it.","persona":"any","source":"then-what / sequence","cat":"weigh-consequences"},
  {"id":"cr-1400","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Build a fuller weigh-up check.","pieces":["The good that could happen","The not-so-good that could happen","Who else it affects","How I'll feel later"],"mode":"assemble","key":["The good that could happen","The not-so-good that could happen","Who else it affects","How I'll feel later"],"relearn":"A full weigh-up: the goods, the bads, others, and later-you.","persona":"any","source":"pros-cons / assemble","cat":"weigh-consequences"},
  {"id":"cr-1401","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Pick the questions that weigh a choice well.","pieces":["Then what happens?","Who else does this touch?","How will I feel tomorrow?","Can I undo it?"],"mode":"assemble","key":["Then what happens?","Who else does this touch?","How will I feel tomorrow?","Can I undo it?"],"relearn":"Weighing questions: then-what, who-else, tomorrow, can-I-undo.","persona":"any","source":"questions / assemble","cat":"weigh-consequences"},
  {"id":"cr-1402","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Order what to do when you're pushed to choose fast.","pieces":["Take one slow breath","Say 'give me a sec'","Ask 'then what?'","Choose for yourself"],"mode":"sequence","key":["Take one slow breath","Say 'give me a sec'","Ask 'then what?'","Choose for yourself"],"relearn":"Under pressure: breathe, buy a sec, ask 'then what?', then choose.","persona":"Aarav","source":"pause / sequence","cat":"weigh-consequences"},
  {"id":"cr-1403","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Build a check for a choice that affects a friend.","pieces":["How would my friend feel?","Is this fair to everyone?","Would I be okay if it were me?","Can I own this choice?"],"mode":"assemble","key":["How would my friend feel?","Is this fair to everyone?","Would I be okay if it were me?","Can I own this choice?"],"relearn":"Weigh a friend-choice: their feelings, fairness, the swap, ownership.","persona":"Diya","source":"values-weigh / assemble","cat":"weigh-consequences"},
  {"id":"cr-1404","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Order how to trace a choice's ripple before deciding.","pieces":["Name the first thing that happens","Then what does that cause?","Who gets touched along the way","Decide if the ripple's worth it"],"mode":"sequence","key":["Name the first thing that happens","Then what does that cause?","Who gets touched along the way","Decide if the ripple's worth it"],"relearn":"Trace a ripple: first effect, then-what, who's touched, worth-it?","persona":"any","source":"ripple / sequence","cat":"weigh-consequences"},
  {"id":"cr-1405","type":"build","hook":"Build a quick weigh-the-choice check.","prompt":"Pick what to compare between two options.","pieces":["What each one costs","What each one gives","Who each one helps or hurts","How long each effect lasts"],"mode":"assemble","key":["What each one costs","What each one gives","Who each one helps or hurts","How long each effect lasts"],"relearn":"Compare options on cost, gain, who's affected, and how long it lasts.","persona":"any","source":"compare / assemble","cat":"weigh-consequences"},
  {"id":"cr-1406","type":"sort","hook":"Sort: a smart long-term choice, or a short win that costs later?","items":[{"id":"a","text":"Revising a little each day"},{"id":"b","text":"Cramming everything the last night"},{"id":"c","text":"Saving up for the thing you want"},{"id":"d","text":"Spending it all the moment you get it"},{"id":"e","text":"Practising a skill weekly"},{"id":"f","text":"Copying to finish fast tonight"}],"bins":[{"id":"good","label":"Smart long-term","valence":"pos"},{"id":"short","label":"Short win, costs later","valence":"neg"}],"key":{"a":"good","b":"short","c":"good","d":"short","e":"good","f":"short"},"relearn":"Good choices often trade a small now for a bigger later.","persona":"any","source":"short-vs-long","cat":"weigh-consequences"},
  {"id":"cr-1407","type":"sort","hook":"Sort: thinking a choice through, or jumping in without weighing it?","items":[{"id":"a","text":"\"What might happen if I do this?\""},{"id":"b","text":"\"Just do it, don't think\""},{"id":"c","text":"\"Who else does this affect?\""},{"id":"d","text":"\"I want it now, who cares later\""},{"id":"e","text":"\"Could I undo this if I'm wrong?\""},{"id":"f","text":"\"Decide it instantly, no thinking\""}],"bins":[{"id":"ahead","label":"Weighing it","valence":"pos"},{"id":"snap","label":"Snap, no weighing","valence":"neg"}],"key":{"a":"ahead","b":"snap","c":"ahead","d":"snap","e":"ahead","f":"snap"},"relearn":"Weighing asks what might happen, who's affected, and can-I-undo.","persona":"any","source":"thinking-ahead","cat":"weigh-consequences"},
  {"id":"cr-1408","type":"sort","hook":"Sort: does this choice mainly affect just you, or other people too?","items":[{"id":"a","text":"Skipping your own dessert"},{"id":"b","text":"Blasting music late at night"},{"id":"c","text":"Choosing which book to read"},{"id":"d","text":"Spreading a rumour about a kid"},{"id":"e","text":"Going to bed early"},{"id":"f","text":"Cutting ahead in the queue"}],"bins":[{"id":"self","label":"Mostly just me","valence":"neutral"},{"id":"others","label":"Touches others too","valence":"uhoh"}],"key":{"a":"self","b":"others","c":"self","d":"others","e":"self","f":"others"},"relearn":"Some choices land only on you; many touch other people too.","persona":"any","source":"who-is-affected","cat":"weigh-consequences"},
  {"id":"cr-1409","type":"sort","hook":"Sort: a choice worth weighing carefully, or a tiny one a beat will do?","items":[{"id":"a","text":"Whether to share a secret"},{"id":"b","text":"Which colour pen to use"},{"id":"c","text":"Whether to skip an important test"},{"id":"d","text":"What snack to grab"},{"id":"e","text":"Whether to keep a found wallet"},{"id":"f","text":"Which seat to sit in"}],"bins":[{"id":"big","label":"Weigh it carefully","valence":"uhoh"},{"id":"tiny","label":"A beat will do","valence":"neutral"}],"key":{"a":"big","b":"tiny","c":"big","d":"tiny","e":"big","f":"tiny"},"relearn":"Big choices deserve more weighing; tiny ones need only a beat.","persona":"any","source":"weigh-or-not","cat":"weigh-consequences"},
  {"id":"cr-1410","type":"sort","hook":"Sort: good now and good later, or good now but sorry later?","items":[{"id":"a","text":"Helping a friend who's stuck"},{"id":"b","text":"Skipping homework to play"},{"id":"c","text":"Owning up to a mistake"},{"id":"d","text":"Lying to dodge trouble"},{"id":"e","text":"Sharing your snack with someone"},{"id":"f","text":"Taking credit that isn't yours"}],"bins":[{"id":"both","label":"Good now and later","valence":"pos"},{"id":"regret","label":"Good now, sorry later","valence":"neg"}],"key":{"a":"both","b":"regret","c":"both","d":"regret","e":"both","f":"regret"},"relearn":"Check both: how it feels now and how it'll feel later.","persona":"any","source":"feels-now-vs-later","cat":"weigh-consequences"},
  {"id":"cr-1411","type":"sort","hook":"Sort: a choice you could undo, or one you can't take back?","items":[{"id":"a","text":"Changing which game to play"},{"id":"b","text":"Sending a mean message"},{"id":"c","text":"Picking a different seat"},{"id":"d","text":"Sharing a private photo"},{"id":"e","text":"Swapping your snack"},{"id":"f","text":"Telling everyone a secret"}],"bins":[{"id":"undo","label":"Can be undone","valence":"pos"},{"id":"stuck","label":"Can't take it back","valence":"uhoh"}],"key":{"a":"undo","b":"stuck","c":"undo","d":"stuck","e":"undo","f":"stuck"},"relearn":"Weigh hardest the choices you can't take back.","persona":"any","source":"reversible-or-not","cat":"weigh-consequences"},
  {"id":"cr-1412","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"Friends push you to do something risky right now, no time to think.","yourLine":[{"text":"Give me a sec, I want to think about what happens after.","best":true},{"text":"Fine, whatever, let's just go."}],"relearn":"Say 'give me a sec to think about what happens after.'","persona":"Aarav","source":"pressure / then-what","cat":"weigh-consequences"},
  {"id":"cr-1413","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"A friend swears you to secrecy that an older kid keeps scaring them.","yourLine":[{"text":"I care about you too much to keep this; let's tell a grown-up together.","best":true},{"text":"Okay, I won't tell anyone, I promise."}],"relearn":"When safety's at stake, telling a trusted adult is the caring choice.","persona":"Diya","source":"friend-secret / safety","cat":"weigh-consequences"},
  {"id":"cr-1414","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"A classmate asks to copy your homework so they don't have to do it.","yourLine":[{"text":"If you get stuck I'll help, but copying could land us both in trouble.","best":true},{"text":"Sure, here, just copy it all."}],"relearn":"Offer help, not a copy; weigh the trouble it could cause you both.","persona":"any","source":"copy / consequences","cat":"weigh-consequences"},
  {"id":"cr-1415","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"Someone's about to tell you a juicy secret about another kid to pass on.","yourLine":[{"text":"I'd rather not, it could really hurt them if it spreads.","best":true},{"text":"Ooh, tell me, I'll pass it on."}],"relearn":"Weigh the hurt before you join in spreading a secret.","persona":"any","source":"gossip / weigh","cat":"weigh-consequences"},
  {"id":"cr-1416","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"The group dares you to do a stunt that could actually hurt you.","yourLine":[{"text":"Not worth it, a few seconds of cred isn't worth a real injury.","best":true},{"text":"Okay, watch this!"}],"relearn":"Weigh real harm against a fleeting bit of 'cool'.","persona":"any","source":"dare / risk","cat":"weigh-consequences"},
  {"id":"cr-1417","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"Your friends want to leave the new kid out of the game.","yourLine":[{"text":"Let's include them; being left out really hurts.","best":true},{"text":"Yeah, let's just not invite them."}],"relearn":"Weigh how being left out lands on someone before you choose.","persona":"Diya","source":"exclusion / others","cat":"weigh-consequences"},
  {"id":"cr-1418","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"You broke something and a friend offers to take the blame for you.","yourLine":[{"text":"Thanks, but I'll own it; hiding it would only get worse.","best":true},{"text":"Great, yeah, say it was you."}],"relearn":"Own a mistake; weigh how hiding it grows the problem.","persona":"any","source":"blame / honesty","cat":"weigh-consequences"},
  {"id":"cr-1419","type":"role-play","hook":"Say it out loud: weigh it, then choose your line.","setup":"You're furious and about to fire off a message you might regret.","yourLine":[{"text":"I'll wait till I've cooled down and think about how it'll land.","best":true},{"text":"I'm sending it right now, I don't care."}],"relearn":"Cool down and weigh how it'll land before you hit send.","persona":"Aarav","source":"pause / impulse","cat":"weigh-consequences"},
];

